{
  "name": "Gemini AI Workspace",
  "description": "A high-performance, aesthetically pleasing React starter template integrated with the Gemini API, featuring a modern dashboard and chat interface.",
  "requestFramePermissions": [
    "camera",
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Role {
  USER = 'user',
  ASSISTANT = 'assistant',
  SYSTEM = 'system'
}

export interface Message {
  id: string;
  role: Role;
  content: string;
  timestamp: Date;
  metadata?: {
    thinking?: string;
    sources?: Array<{ title: string; uri: string }>;
  };
}

export interface ChatSession {
  id: string;
  title: string;
  messages: Message[];
  createdAt: Date;
}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { Message, Role } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateAIResponse = async (
  prompt: string,
  history: Message[] = []
): Promise<{ text: string; sources?: any[] }> => {
  try {
    const chat = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: 'You are a highly capable AI assistant in a modern workspace environment. Be concise, helpful, and professional.',
        tools: [{ googleSearch: {} }]
      },
    });

    // Simple history conversion for basic chat context if needed
    // In a real app, you'd map history to Gemini's expected contents format
    const response = await chat.sendMessage({ message: prompt });

    return {
      text: response.text || "I couldn't generate a response.",
      sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
    };
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Role, Message, ChatSession } from './types';
import { generateAIResponse } from './services/geminiService';
import Sidebar from './components/Sidebar';
import ChatWindow from './components/ChatWindow';

const App: React.FC = () => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [activeSessionId, setActiveSessionId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  // Initialize with a default session
  useEffect(() => {
    const initialSession: ChatSession = {
      id: 'default',
      title: 'New Conversation',
      messages: [
        {
          id: 'welcome',
          role: Role.ASSISTANT,
          content: 'Hello! How can I assist you in your workspace today?',
          timestamp: new Date(),
        },
      ],
      createdAt: new Date(),
    };
    setSessions([initialSession]);
    setActiveSessionId('default');
  }, []);

  const activeSession = sessions.find((s) => s.id === activeSessionId) || null;

  const handleSendMessage = async (text: string) => {
    if (!text.trim() || !activeSessionId) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: Role.USER,
      content: text,
      timestamp: new Date(),
    };

    // Optimistically update UI
    setSessions((prev) =>
      prev.map((s) =>
        s.id === activeSessionId
          ? { ...s, messages: [...s.messages, userMessage] }
          : s
      )
    );

    setIsLoading(true);
    try {
      const result = await generateAIResponse(text, activeSession?.messages || []);

      const aiMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: Role.ASSISTANT,
        content: result.text,
        timestamp: new Date(),
        metadata: {
          sources: result.sources?.map(s => ({ title: s.web?.title || 'Source', uri: s.web?.uri || '#' }))
        }
      };

      setSessions((prev) =>
        prev.map((s) =>
          s.id === activeSessionId
            ? { ...s, messages: [...s.messages, aiMessage] }
            : s
        )
      );
    } catch (error) {
      console.error(error);
      const errorMessage: Message = {
        id: 'error-' + Date.now(),
        role: Role.ASSISTANT,
        content: "I'm sorry, I encountered an error. Please check your connection or try again later.",
        timestamp: new Date(),
      };
      setSessions((prev) =>
        prev.map((s) =>
          s.id === activeSessionId
            ? { ...s, messages: [...s.messages, errorMessage] }
            : s
        )
      );
    } finally {
      setIsLoading(false);
    }
  };

  const createNewSession = () => {
    const id = Date.now().toString();
    const newSession: ChatSession = {
      id,
      title: 'New Chat',
      messages: [{
        id: 'welcome-' + id,
        role: Role.ASSISTANT,
        content: 'Started a new session. How can I help?',
        timestamp: new Date(),
      }],
      createdAt: new Date(),
    };
    setSessions([newSession, ...sessions]);
    setActiveSessionId(id);
  };

  return (
    <div className="flex h-screen w-full overflow-hidden bg-slate-50 text-slate-900">
      <Sidebar 
        sessions={sessions} 
        activeId={activeSessionId} 
        onSelect={setActiveSessionId}
        onNewChat={createNewSession}
      />
      <main className="flex-1 flex flex-col min-w-0 bg-white shadow-xl">
        <ChatWindow 
          session={activeSession} 
          onSendMessage={handleSendMessage}
          isLoading={isLoading}
        />
      </main>
    </div>
  );
};

export default App;

