    'E-Class': ['OM654 (220d)', 'OM656 (350d/400d)', 'M256 (450/53 AMG)'],
    'GLE': ['OM654 (300d)', 'OM656 (350d/400d)', 'M256 (450)']
  },
  'Hyundai': {
    'i30': ['G4LD (1.4 T-GDI)', 'D4FE (1.6 CRDi)', 'G3LE (1.0 T-GDI)', 'G4KH (N 2.0 T-GDI)'],
    'Tucson': ['G4FJ (1.6 T-GDI)', 'D4HD (2.0 CRDi)', 'G4FT (1.6 T-GDI Hybrid)'],
    'i20': ['G3LF (1.0 T-GDI)', 'G4LC (1.4 MPI)']
  },
  'Toyota': {
    'Corolla': ['2ZR-FXE (1.8 Hybrid)', 'M20A-FXS (2.0 Hybrid)'],
    'RAV4': ['A25A-FXS (2.5 Hybrid)', 'M20A-FKS (2.0 Dynamic Force)'],
    'Yaris': ['M15A-FXE (1.5 Hybrid)', 'M15A-FKS (1.5 Dynamic Force)']
  },
  'Peugeot': {
    '308': ['DV5RC (1.5 BlueHDi)', 'EB2ADTS (1.2 PureTech)'],
    '5008': ['DW10FC (2.0 BlueHDi)', 'EB2ADTS (1.2 PureTech)'],
    '208': ['EB2DT (1.2 PureTech)', 'DV5RE (1.5 BlueHDi)']
  },
  'Renault': {
    'Clio': ['H4D (1.0 TCe)', 'K9K (1.5 dCi)', 'H5H (1.3 TCe)'],
    'Megane': ['K9K (1.5 dCi)', 'H5H (1.3 TCe)', 'M5P (RS 1.8T)'],
    'Captur': ['H4D (1.0 TCe)', 'H5H (1.3 TCe)']
  },
  'Ford': {
    'Focus': ['M1DA (1.0 EcoBoost)', 'YZDA (1.5 EcoBoost)', 'ZTDA (1.5 EcoBlue)'],
    'Mondeo': ['T7CN (2.0 TDCi)', 'U9PC (2.0 Hybrid)', 'UNCN (1.5 EcoBoost)'],
    'Kuga': ['T7MA (2.0 TDCi)', 'M8MA (1.5 EcoBoost)']
  }
};

const DRIVE_TYPES = ['Přední (FWD)', 'Zadní (RWD)', '4x4 / AWD', 'xDrive', 'Quattro', '4Motion', '4Matic'];

interface VehicleProps {
  vehicles: Vehicle[];
  customers: Customer[];
  services: ServiceRecord[];
  onAddVehicle?: (vehicle: Vehicle) => void;
  onUpdateVehicle?: (vehicle: Vehicle) => void;
  onDeleteVehicle?: (id: string) => void;
  onNavigateToCustomer?: (customerId: string) => void;
  onNavigateToOrder?: (orderId: string) => void;
  initialVehicleId?: string | null;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  search: string;
  onSearchChange: (value: string) => void;
}

const VehicleManager: React.FC<VehicleProps> = ({ 
  vehicles, 
  customers, 
  services, 
  onAddVehicle, 
  onUpdateVehicle,
  onDeleteVehicle,
  onNavigateToCustomer,
  onNavigateToOrder,
  initialVehicleId,
  autoOpen,
  onModalOpened,
  search,
  onSearchChange
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingVehicleId, setEditingVehicleId] = useState<string | null>(null);
  const [deletingVehicle, setDeletingVehicle] = useState<Vehicle | null>(null);
  const [selectedHistoryVehicle, setSelectedHistoryVehicle] = useState<Vehicle | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const initialFormState = {
    customerId: '',
    make: '',
    model: '',
    year: new Date().getFullYear(),
    vin: '',
    licensePlate: '',
    mileage: 0,
    engineCode: '',
    color: '', // Slouží pro "Pohon" dle UI
    stkExpirationDate: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    nextServiceDate: new Date(Date.now() + 180 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    notes: '',
  };

  const [formData, setFormData] = useState(initialFormState);

  useEffect(() => {
    if (autoOpen) {
      handleAddNew();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const filteredVehicles = vehicles
    .filter(v => 
      v.licensePlate.toLowerCase().includes(search.toLowerCase()) ||
      v.make.toLowerCase().includes(search.toLowerCase()) ||
      v.model.toLowerCase().includes(search.toLowerCase())
    )
    .sort((a, b) => a.make.localeCompare(b.make, 'cs'));

  const handleEdit = (vehicle: Vehicle) => {
    setEditingVehicleId(vehicle.id);
    setFormData({
      customerId: vehicle.customerId,
      make: vehicle.make,
      model: vehicle.model,
      year: vehicle.year,
      vin: vehicle.vin,
      licensePlate: vehicle.licensePlate,
      mileage: vehicle.mileage,
      engineCode: vehicle.engineCode,
      color: vehicle.color,
      stkExpirationDate: vehicle.stkExpirationDate,
      nextServiceDate: vehicle.nextServiceDate,
      notes: vehicle.notes || '',
    });
    setIsModalOpen(true);
    setOpenMenuId(null);
  };

  const handleAddNew = () => {
    setEditingVehicleId(null);
    setFormData(initialFormState);
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingVehicleId) {
      if (!onUpdateVehicle) return;
      const vehicleToUpdate = vehicles.find(v => v.id === editingVehicleId);
      if (vehicleToUpdate) onUpdateVehicle({ ...vehicleToUpdate, ...formData });
    } else {
      if (!onAddVehicle) return;
      const newVehicle: Vehicle = { ...formData, id: `v${Date.now()}`, lastServiceDate: new Date().toISOString().split('T')[0] };
      onAddVehicle(newVehicle);
    }
    setIsModalOpen(false);
    setFormData(initialFormState);
    setEditingVehicleId(null);
  };

  const confirmDelete = () => {
    if (deletingVehicle && onDeleteVehicle) {
      onDeleteVehicle(deletingVehicle.id);
      setDeletingVehicle(null);
    }
  };

  // Dynamické seznamy pro formulář
  const availableModels = useMemo(() => {
    if (VEHICLE_DB[formData.make]) {
      return Object.keys(VEHICLE_DB[formData.make]);
    }
    return [];
  }, [formData.make]);

  const availableEngines = useMemo(() => {
    if (VEHICLE_DB[formData.make] && VEHICLE_DB[formData.make][formData.model]) {
      return VEHICLE_DB[formData.make][formData.model];
    }
    return [];
  }, [formData.make, formData.model]);

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Evidence vozidel</h2>
          <p className="text-slate-500 font-medium">Celkem {vehicles.length} vozidel v péči.</p>
        </div>
        <button 
          onClick={handleAddNew}
          className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg shadow-blue-200"
        >
          <Plus className="w-5 h-5" />
          Nové vozidlo
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
        <Search className="w-5 h-5 text-slate-400" />
        <input 
          type="text" 
          placeholder="Hledat podle SPZ, značky nebo modelu..." 
          className="flex-1 text-sm font-medium outline-none bg-transparent"
          value={search}
          onChange={(e) => onSearchChange(e.target.value)}
        />
        {search && (
          <button onClick={() => onSearchChange('')} className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all">Zrušit filtr</button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 pb-12">
        {filteredVehicles.map(v => {
          const owner = customers.find(c => c.id === v.customerId);

          return (
            <div key={v.id} className={`bg-white rounded-3xl border shadow-sm p-6 hover:shadow-xl transition-all group relative overflow-visible ${initialVehicleId === v.id ? 'ring-4 ring-blue-500/20 border-blue-500' : 'border-slate-100'}`}>
              <div className="absolute top-0 right-0 p-4">
                <div className="relative">
                  <button 
                    onClick={() => setOpenMenuId(openMenuId === v.id ? null : v.id)}
                    className={`p-2 rounded-xl transition-all ${openMenuId === v.id ? 'bg-slate-100 text-slate-900' : 'text-slate-300 hover:text-slate-900'}`}
                  >
                    <MoreHorizontal className="w-6 h-6" />
                  </button>

                  {openMenuId === v.id && (
                    <div ref={menuRef} className="absolute top-12 right-0 w-48 bg-white rounded-2xl shadow-2xl border border-slate-100 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200">
                      <button onClick={() => handleEdit(v)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-sm font-bold">
                        <Edit3 className="w-4 h-4 text-slate-400" />
                        Upravit kartu
                      </button>
                      <button onClick={() => { setDeletingVehicle(v); setOpenMenuId(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold">
                        <Trash2 className="w-4 h-4" />
                        Smazat kartu
                      </button>
                    </div>
                  )}
                </div>
              </div>

              <div className="flex items-center gap-5 mb-6">
                <div className="w-16 h-16 rounded-2xl bg-blue-600 flex items-center justify-center text-white shadow-lg shadow-blue-600/20 group-hover:scale-105 transition-transform">
                  <Car className="w-8 h-8" />
                </div>
                <div>
                  <h3 className="text-lg font-black text-slate-900 leading-tight">{v.make} {v.model}</h3>
                  <div className="bg-slate-900 text-white font-mono font-bold px-2 py-0.5 rounded text-[10px] mt-1 inline-block uppercase tracking-wider">{v.licensePlate}</div>
                </div>
              </div>

              <div className="space-y-3 pt-4 border-t border-slate-50">
                <div className="flex items-center gap-3 text-slate-600">
                  <div className="p-2 bg-slate-50 rounded-lg"><Fingerprint className="w-4 h-4" /></div>
                  <span className="text-xs font-mono font-bold truncate">{v.vin}</span>
                </div>
                <div className="flex items-center gap-3 text-slate-600">
                  <div className="p-2 bg-slate-50 rounded-lg"><ShieldCheck className="w-4 h-4" /></div>
                  <span className="text-sm font-semibold">STK: {v.stkExpirationDate}</span>
                </div>
                <div className="flex items-center gap-3 text-slate-600">
                  <div className="p-2 bg-slate-50 rounded-lg"><Clock className="w-4 h-4" /></div>
                  <span className="text-sm font-semibold">Servis: {v.nextServiceDate}</span>
                </div>
              </div>

              <div className="mt-6 flex gap-2">
                <button 
                  onClick={() => handleEdit(v)}
                  className="flex-1 py-3 bg-slate-100 text-slate-900 rounded-xl font-bold text-xs hover:bg-slate-200 transition-colors uppercase tracking-wider"
                >
                  Detail
                </button>
                <button 
                  onClick={() => setSelectedHistoryVehicle(v)}
                  className="flex-1 py-3 bg-blue-50 text-blue-600 rounded-xl font-bold text-xs hover:bg-blue-100 transition-colors uppercase tracking-wider"
                >
                  Historie
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {/* History Modal */}
      {selectedHistoryVehicle && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setSelectedHistoryVehicle(null)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-slate-900 p-8 text-white flex justify-between items-center">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-slate-800 rounded-xl flex items-center justify-center">
                  <History className="w-6 h-6 text-white" />
                </div>
                <div>
                  <h3 className="text-xl font-black tracking-tight">Servisní historie</h3>
                  <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mt-1">
                    {selectedHistoryVehicle.make} {selectedHistoryVehicle.model} ({selectedHistoryVehicle.licensePlate})
                  </p>
                </div>
              </div>
              <button onClick={() => setSelectedHistoryVehicle(null)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>
            <div className="p-8 space-y-4 max-h-[60vh] overflow-y-auto custom-scrollbar">
              {services.filter(s => s.vehicleId === selectedHistoryVehicle.id).length > 0 ? (
                services
                  .filter(s => s.vehicleId === selectedHistoryVehicle.id)
                  .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
                  .map((service, idx, arr) => (
                    <div key={service.id} className="relative flex gap-6">
                      {idx !== arr.length - 1 && <div className="absolute left-[19px] top-10 bottom-[-16px] w-0.5 bg-slate-100"></div>}
                      <div className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 shadow-sm z-10 ${service.status === 'hotovo' ? 'bg-emerald-100 text-emerald-600' : service.status === 'naplánováno' ? 'bg-blue-100 text-blue-600' : 'bg-amber-100 text-amber-600'}`}>
                        {service.status === 'hotovo' ? <CheckCircle2 className="w-5 h-5" /> : service.status === 'naplánováno' ? <Clock3 className="w-5 h-5" /> : <AlertTriangle className="w-5 h-5" />}
                      </div>
                      <div 
                        onClick={() => { onNavigateToOrder?.(service.id); setSelectedHistoryVehicle(null); }}
                        className="bg-slate-50 p-5 rounded-2xl border border-slate-100 flex-1 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 transition-all group cursor-pointer hover:border-blue-300 hover:bg-white"
                      >
                        <div>
                          <div className="flex items-center gap-2 mb-1">
                            <span className="text-xs font-black text-slate-900">{service.date}</span>
                            <span className={`text-[9px] font-black uppercase tracking-tighter px-2 py-0.5 rounded-full ${service.status === 'hotovo' ? 'bg-emerald-50 text-emerald-700' : service.status === 'naplánováno' ? 'bg-blue-50 text-blue-700' : 'bg-amber-50 text-amber-700'}`}>{service.status}</span>
                          </div>
                          <p className="text-sm font-medium text-slate-600 group-hover:text-blue-600 transition-colors">{service.description}</p>
                        </div>
                        <div className="text-right shrink-0 flex items-center gap-4">
                          <p className="text-lg font-black text-slate-900">{service.cost.toLocaleString()} Kč</p>
                          <ChevronRight className="w-4 h-4 text-slate-300 group-hover:text-blue-500 group-hover:translate-x-1 transition-all" />
                        </div>
                      </div>
                    </div>
                  ))
              ) : (
                <div className="text-center py-10 bg-slate-50 rounded-3xl border-2 border-dashed border-slate-200">
                  <p className="text-slate-400 font-bold italic">Zatím žádné servisní záznamy pro toto vozidlo.</p>
                </div>
              )}
            </div>
            <div className="p-8 border-t border-slate-50">
               <button 
                onClick={() => setSelectedHistoryVehicle(null)}
                className="w-full bg-slate-100 hover:bg-slate-200 text-slate-900 font-black py-4 rounded-2xl transition-all"
              >
                ZAVŘÍT
              </button>
            </div>
          </div>
        </div>
      )}

      {deletingVehicle && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setDeletingVehicle(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6"><AlertCircle className="w-10 h-10" /></div>
              <h3 className="text-2xl font-black text-slate-900 mb-2">Opravdu smazat?</h3>
              <p className="text-slate-500 font-medium mb-8 leading-relaxed">Opravdu chcete smazat kartu vozidla <span className="font-bold text-slate-900">{deletingVehicle.make} {deletingVehicle.model} ({deletingVehicle.licensePlate})</span>?</p>
              <div className="flex gap-3"><button onClick={() => setDeletingVehicle(null)} className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm hover:bg-slate-200">ZRUŠIT</button><button onClick={confirmDelete} className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm hover:bg-red-700 shadow-lg shadow-red-600/20">SMAZAT</button></div>
            </div>
          </div>
        </div>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-blue-600 p-8 text-white flex justify-between items-center">
              <div><h3 className="text-2xl font-black tracking-tight">{editingVehicleId ? 'Upravit vozidlo' : 'Nové vozidlo'}</h3><p className="text-blue-100 text-xs font-bold uppercase tracking-widest mt-1">{editingVehicleId ? `Editace vozu ${formData.licensePlate}` : 'Registrace do vozového parku'}</p></div>
              <button onClick={() => setIsModalOpen(false)}><X className="w-6 h-6" /></button>
            </div>
            <form onSubmit={handleSubmit} className="p-8 grid grid-cols-1 md:grid-cols-2 gap-6 max-h-[70vh] overflow-y-auto custom-scrollbar">
              <div className="md:col-span-2 space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Vlastník</label><select required className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.customerId} onChange={e => setFormData({...formData, customerId: e.target.value})}><option value="">Vyberte zákazníka...</option>{customers.map(c => (<option key={c.id} value={c.id}>{c.firstName} {c.lastName}</option>))}</select></div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Značka</label>
                <input 
                  required 
                  type="text" 
                  list="makes"
                  className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" 
                  value={formData.make} 
                  onChange={e => setFormData({...formData, make: e.target.value})} 
                />
                <datalist id="makes">
                  {Object.keys(VEHICLE_DB).map(make => <option key={make} value={make} />)}
                </datalist>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Model</label>
                <input 
                  required 
                  type="text" 
                  list="models"
                  className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" 
                  value={formData.model} 
                  onChange={e => setFormData({...formData, model: e.target.value})} 
                />
                <datalist id="models">
                  {availableModels.map(model => <option key={model} value={model} />)}
                </datalist>
              </div>

              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">SPZ</label><input required type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold uppercase" value={formData.licensePlate} onChange={e => setFormData({...formData, licensePlate: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">VIN</label><input required type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold uppercase" value={formData.vin} onChange={e => setFormData({...formData, vin: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Rok výroby</label><input required type="number" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.year} onChange={e => setFormData({...formData, year: parseInt(e.target.value)})} /></div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Kód motoru</label>
                <input 
                  type="text" 
                  list="engines"
                  className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold uppercase" 
                  value={formData.engineCode} 
                  onChange={e => setFormData({...formData, engineCode: e.target.value})} 
                />
                <datalist id="engines">
                  {availableEngines.map(engine => <option key={engine} value={engine} />)}
                </datalist>
              </div>

              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nájezd km</label><input required type="number" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.mileage} onChange={e => setFormData({...formData, mileage: parseInt(e.target.value)})} /></div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Pohon</label>
                <input 
                  type="text" 
                  list="drives"
                  className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" 
                  value={formData.color} 
                  onChange={e => setFormData({...formData, color: e.target.value})} 
                />
                <datalist id="drives">
                  {DRIVE_TYPES.map(drive => <option key={drive} value={drive} />)}
                </datalist>
              </div>

              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Datum expirace STK</label><input required type="date" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.stkExpirationDate} onChange={e => setFormData({...formData, stkExpirationDate: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Termín příštího servisu</label><input required type="date" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.nextServiceDate} onChange={e => setFormData({...formData, nextServiceDate: e.target.value})} /></div>
              <div className="md:col-span-2 space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Poznámky</label>
                <textarea 
                  className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold min-h-[100px] resize-none"
                  value={formData.notes}
                  onChange={e => setFormData({...formData, notes: e.target.value})}
                  placeholder="Zapište důležité informace o vozidle..."
                />
              </div>
              <button type="submit" className="md:col-span-2 w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-600/20 transition-all flex items-center justify-center gap-2 mt-4"><Check className="w-5 h-5" />{editingVehicleId ? 'ULOŽIT ZMĚNY' : 'ULOŽIT VOZIDLO'}</button>
            </form>
          </div>
        </div>
      )}
      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: #f1f5f9;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #cbd5e1;
          border-radius: 10px;
        }
      `}</style>
    </div>
  );
};

