import React, { useMemo, useState, useEffect, useRef } from 'react';
import { 
  AlertCircle, 
  Plus, 
  Car, 
  Wrench, 
  ShieldAlert, 
  UserPlus,
  ClipboardPlus,
  Clock,
  ChevronRight,
  ClipboardList,
  CheckCircle2,
  Timer,
