      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Dnešní přehled</h2>
          <p className="text-slate-500 font-medium">Stav vašeho servisu v reálném čase.</p>
        </div>

        <div className="relative" ref={dropdownRef}>
          <button 
            onClick={() => setIsQuickActionOpen(!isQuickActionOpen)}
            className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black shadow-xl shadow-blue-600/30 hover:bg-blue-700 hover:-translate-y-0.5 transition-all flex items-center gap-3"
          >
            <Plus className={`w-6 h-6 transition-transform duration-300 ${isQuickActionOpen ? 'rotate-45' : ''}`} />
            Rychlá akce
          </button>
          {isQuickActionOpen && (
            <div className="absolute top-20 right-0 w-72 bg-white rounded-[2rem] shadow-2xl border border-slate-100 p-4 z-50 animate-in fade-in zoom-in-95 duration-200">
              <div className="space-y-2">
                {quickActions.map((action, idx) => (
                  <button
                    key={idx}
                    onClick={() => { onNavigate(action.view, true); setIsQuickActionOpen(false); }}
                    className="w-full flex items-center gap-4 p-4 rounded-2xl hover:bg-slate-50 transition-colors group text-left"
                  >
                    <div className="w-10 h-10 rounded-xl bg-blue-50 flex items-center justify-center text-blue-600 group-hover:bg-blue-600 group-hover:text-white transition-all">
                      <action.icon className="w-5 h-5" />
                    </div>
                    <div>
                      <p className="text-sm font-black text-slate-900">{action.label}</p>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">{action.desc}</p>
                    </div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Alerts Section (Horizontal scrollable or compact) */}
      {vehicleAlerts.length > 0 && (
        <section>
          <div className="flex items-center gap-3 mb-6">
            <AlertCircle className="w-6 h-6 text-amber-500" />
            <h3 className="text-xl font-black text-slate-900 tracking-tight uppercase">Urgentní upozornění</h3>
          </div>
          <div className="flex gap-4 overflow-x-auto pb-4 custom-scrollbar">
            {vehicleAlerts.map((alert, idx) => (
              <div 
                key={idx} 
                onClick={() => onViewVehicle(alert.vehicle.id)}
                className={`min-w-[320px] p-6 rounded-[2rem] border transition-all hover:scale-[1.02] cursor-pointer flex flex-col justify-between ${
                  alert.type === 'stk' 
                    ? 'bg-red-50 border-red-100 text-red-900' 
                    : 'bg-blue-50 border-blue-100 text-blue-900'
                }`}
              >
                <div className="flex justify-between items-start mb-4">
                  <div className="flex items-center gap-2">
                    {alert.type === 'stk' ? <ShieldAlert className="w-4 h-4 text-red-500" /> : <Wrench className="w-4 h-4 text-blue-500" />}
                    <span className="text-[10px] font-black uppercase tracking-widest">{alert.type === 'stk' ? 'Expirace STK' : 'Plánovaný servis'}</span>
                  </div>
                  <span className={`text-[10px] font-black px-2.5 py-1 rounded-full ${alert.daysLeft <= 5 ? 'bg-red-500 text-white animate-pulse' : 'bg-white/50'}`}>
                    {alert.daysLeft} Dní
                  </span>
                </div>
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 rounded-2xl bg-white flex items-center justify-center shrink-0 shadow-sm"><Car className="w-6 h-6 text-slate-400" /></div>
                  <div>
                    <p className="text-base font-black tracking-tight">{alert.vehicle.make} {alert.vehicle.model}</p>
                    <p className="text-xs font-bold font-mono opacity-60">{alert.vehicle.licensePlate}</p>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </section>
      )}

      {/* Orders Kanban Grid */}
      <section className="space-y-6">
        <div className="flex items-center gap-3 mb-2">
          <ClipboardList className="w-6 h-6 text-blue-600" />
          <h3 className="text-xl font-black text-slate-900 tracking-tight uppercase">Přehled zakázek</h3>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 h-full min-h-[600px]">

          {/* Column 1: Waiting */}
          <div className="bg-slate-100/50 rounded-[2.5rem] p-6 flex flex-col">
            <div className="flex items-center justify-between mb-6 px-2">
              <div className="flex items-center gap-2">
                <div className="w-2 h-2 rounded-full bg-blue-500"></div>
                <h4 className="text-sm font-black text-slate-600 uppercase tracking-widest">K vyřízení</h4>
              </div>
              <span className="bg-white px-2.5 py-1 rounded-full text-[10px] font-black text-slate-400 shadow-sm border border-slate-100">{ordersByStatus.waiting.length}</span>
            </div>
            <div className="space-y-4 overflow-y-auto max-h-[700px] pr-1 custom-scrollbar">
              {/* FIX: Using renderOrderCard function to handle mapping and avoid key prop errors */}
              {ordersByStatus.waiting.map(renderOrderCard)}
              {ordersByStatus.waiting.length === 0 && (
                <div className="py-20 text-center">
                  <Clock className="w-10 h-10 text-slate-200 mx-auto mb-3" />
                  <p className="text-xs font-bold text-slate-400 italic">Žádné čekající zakázky.</p>
                </div>
              )}
            </div>
          </div>

          {/* Column 2: Active */}
          <div className="bg-amber-50/50 rounded-[2.5rem] p-6 flex flex-col border border-amber-100/50">
            <div className="flex items-center justify-between mb-6 px-2">
              <div className="flex items-center gap-2">
                <div className="w-2 h-2 rounded-full bg-amber-500 animate-pulse"></div>
                <h4 className="text-sm font-black text-amber-700 uppercase tracking-widest">Aktuálně probíhá</h4>
              </div>
              <span className="bg-white px-2.5 py-1 rounded-full text-[10px] font-black text-amber-500 shadow-sm border border-amber-100">{ordersByStatus.active.length}</span>
            </div>
            <div className="space-y-4 overflow-y-auto max-h-[700px] pr-1 custom-scrollbar">
              {/* FIX: Using renderOrderCard function to handle mapping and avoid key prop errors */}
              {ordersByStatus.active.map(renderOrderCard)}
              {ordersByStatus.active.length === 0 && (
                <div className="py-20 text-center">
                  <Timer className="w-10 h-10 text-amber-100 mx-auto mb-3" />
                  <p className="text-xs font-bold text-amber-400 italic">Právě se nic neopravuje.</p>
                </div>
              )}
            </div>
          </div>

          {/* Column 3: Done */}
          <div className="bg-emerald-50/50 rounded-[2.5rem] p-6 flex flex-col border border-emerald-100/50">
            <div className="flex items-center justify-between mb-6 px-2">
              <div className="flex items-center gap-2">
                <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
                <h4 className="text-sm font-black text-emerald-700 uppercase tracking-widest">Hotovo</h4>
              </div>
              <span className="bg-white px-2.5 py-1 rounded-full text-[10px] font-black text-emerald-500 shadow-sm border border-emerald-100">{ordersByStatus.done.length}</span>
            </div>
            <div className="space-y-4 overflow-y-auto max-h-[700px] pr-1 custom-scrollbar">
              {/* FIX: Using renderOrderCard function to handle mapping and avoid key prop errors */}
              {ordersByStatus.done.map(renderOrderCard)}
              {ordersByStatus.done.length === 0 && (
                <div className="py-20 text-center">
                  <CheckSquare className="w-10 h-10 text-emerald-100 mx-auto mb-3" />
                  <p className="text-xs font-bold text-emerald-400 italic">Dnes ještě není hotovo.</p>
                </div>
              )}
            </div>
          </div>

        </div>
      </section>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(0, 0, 0, 0.05); border-radius: 10px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: rgba(0, 0, 0, 0.1); }
      `}</style>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  ClipboardList, Plus, User, Car, ArrowRight, X, Check, 
  Search, Package, Printer, Trash2, Tag, FileText, AlertCircle, Eye, CheckSquare, Square, Receipt,
  MoreHorizontal, Edit3, Clock, Timer, CheckCircle2
} from 'lucide-react';
import { ServiceRecord, Vehicle, Customer, PartItem, CompanyInfo, FixedService, VehicleChecklist, PredefinedTask } from '../types';

interface OrderManagerProps {
  services: ServiceRecord[];
  vehicles: Vehicle[];
  customers: Customer[];
  technicians: string[];
  predefinedTasks: PredefinedTask[];
  hourlyRate: number;
  fixedServices: FixedService[];
  companyInfo: CompanyInfo;
  onAddService: (service: ServiceRecord) => void;
  onUpdateService: (service: ServiceRecord) => void;
  onDeleteService: (orderId: string) => void;
  onCreateInvoice?: (orderId: string) => void;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  initialOrderId?: string | null;
  selectedPrinter?: string;
  search: string;
  onSearchChange: (value: string) => void;
}

const OrderManager: React.FC<OrderManagerProps> = ({ 
  services, 
  vehicles, 
  customers, 
  technicians,
  predefinedTasks,
  hourlyRate,
  fixedServices,
  companyInfo,
  onAddService,
  onUpdateService,
  onDeleteService,
  onCreateInvoice,
  autoOpen, 
  onModalOpened, 
  initialOrderId,
  search,
  onSearchChange
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrderId, setEditingOrderId] = useState<string | null>(null);
  const [isPriceListPickerOpen, setIsPriceListPickerOpen] = useState(false);
  const [isTemplatePickerOpen, setIsTemplatePickerOpen] = useState(false);
  const [deletingOrder, setDeletingOrder] = useState<ServiceRecord | null>(null);
  const [showInvoicePrompt, setShowInvoicePrompt] = useState<string | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const [formData, setFormData] = useState({
    id: '',
    vehicleId: '',
    description: '',
    parts: [] as PartItem[],
    date: new Date().toISOString().split('T')[0],
    deliveryDate: '',
    endDate: '',
    technician: technicians[0] || '',
    laborHours: 0,
    status: 'naplánováno' as ServiceRecord['status'],
    fuelLevel: '1/2' as ServiceRecord['fuelLevel'],
    mileageAtEntry: 0,
    estimatedPrice: 0,
    paymentType: 'Hotovost' as ServiceRecord['paymentType'],
    checklist: {
      rezerva: false, zvedak: false, klic: false, naradi: false, hustilka: false,
      trojuhelnik: false, lekarna: false, radio: false, reflektory: false, nosic: false
    } as VehicleChecklist
  });

  const materialCost = useMemo(() => {
    return formData.parts.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
  }, [formData.parts]);

  const calculatedCost = useMemo(() => {
    return (formData.laborHours * hourlyRate) + materialCost;
  }, [formData.laborHours, materialCost, hourlyRate]);

  useEffect(() => {
    if (autoOpen) {
      handleAddNew();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen, onModalOpened]);

  useEffect(() => {
    if (initialOrderId) {
      const order = services.find(s => s.id === initialOrderId);
      if (order) handleEdit(order);
    }
  }, [initialOrderId, services]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleAddNew = () => {
    resetForm();
    setEditingOrderId(null);
    setIsModalOpen(true);
  };

  const handleEdit = (order: ServiceRecord) => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    setEditingOrderId(order.id);
    setFormData({
      id: order.id,
      vehicleId: order.vehicleId,
      description: order.description,
      parts: order.parts || [],
      date: order.date,
      deliveryDate: order.deliveryDate || '',
      endDate: order.endDate || '',
      technician: order.technician,
      laborHours: order.laborHours || 0,
      status: order.status,
      fuelLevel: order.fuelLevel || '1/2',
      mileageAtEntry: order.mileageAtEntry || (vehicle?.mileage || 0),
      estimatedPrice: order.estimatedPrice || 0,
      paymentType: order.paymentType || 'Hotovost',
      checklist: order.checklist || {
        rezerva: false, zvedak: false, klic: false, naradi: false, hustilka: false,
        trojuhelnik: false, lekarna: false, radio: false, reflektory: false, nosic: false
      }
    });
    setIsModalOpen(true);
    setOpenMenuId(null);
  };

  const generateNewId = () => {
    const now = new Date();
    const year = now.getFullYear().toString().slice(-2);
    const month = (now.getMonth() + 1).toString().padStart(2, '0');
    const prefix = `${year}/${month}/`;
    const monthlyOrders = services.filter(s => s.id.startsWith(prefix));
    const nextSequence = (monthlyOrders.length + 1).toString().padStart(3, '0');
    return `${prefix}${nextSequence}`;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalId = editingOrderId || generateNewId();
    const serviceData: ServiceRecord = {
      ...formData,
      id: finalId,
      cost: calculatedCost
    };
    if (editingOrderId) onUpdateService(serviceData);
    else onAddService(serviceData);

    setIsModalOpen(false);

    if (serviceData.status === 'hotovo' && !editingOrderId) {
      setShowInvoicePrompt(finalId);
    }

    resetForm();
  };

  const resetForm = () => {
    setFormData({
      id: '',
      vehicleId: '',
      description: '',
      parts: [],
      date: new Date().toISOString().split('T')[0],
      deliveryDate: '',
      endDate: '',
      technician: technicians[0] || '',
      laborHours: 0,
      status: 'naplánováno',
      fuelLevel: '1/2',
      mileageAtEntry: 0,
      estimatedPrice: 0,
      paymentType: 'Hotovost',
      checklist: {
        rezerva: false, zvedak: false, klic: false, naradi: false, hustilka: false,
        trojuhelnik: false, lekarna: false, radio: false, reflektory: false, nosic: false
      }
    });
  };

  const addPart = () => {
    setFormData({
      ...formData,
      parts: [...formData.parts, { id: Date.now().toString(), description: '', quantity: 1, unit: 'ks', unitPrice: 0 }]
    });
  };

  const removePart = (id: string) => {
    setFormData({ ...formData, parts: formData.parts.filter(p => p.id !== id) });
  };

  const updatePart = (id: string, field: keyof PartItem, value: any) => {
    setFormData({
      ...formData,
      parts: formData.parts.map(p => p.id === id ? { ...p, [field]: value } : p)
    });
  };

  const addFromPriceList = (item: FixedService) => {
    setFormData({
      ...formData,
      parts: [...formData.parts, { id: Date.now().toString(), description: item.name, quantity: 1, unit: 'úkon', unitPrice: item.price }]
    });
    setIsPriceListPickerOpen(false);
  };

  const addFromTemplates = (item: PredefinedTask) => {
    const currentDesc = formData.description;
    const separator = currentDesc.trim() ? '\n\n' : '';
    setFormData({
      ...formData,
      description: `${currentDesc}${separator}${item.description}`
    });
    setIsTemplatePickerOpen(false);
  };

  const toggleChecklist = (key: keyof VehicleChecklist) => {
    setFormData({
      ...formData,
      checklist: { ...formData.checklist, [key]: !formData.checklist[key] }
    });
  };

  const filteredOrders = useMemo(() => {
    return services.filter(order => {
      const vehicle = vehicles.find(v => v.id === order.vehicleId);
      const owner = customers.find(c => c.id === vehicle?.customerId);
      if (!search) return true;
      return (
        order.id.toLowerCase().includes(search.toLowerCase()) ||
        order.description.toLowerCase().includes(search.toLowerCase()) ||
        vehicle?.licensePlate.toLowerCase().includes(search.toLowerCase()) ||
        owner?.lastName.toLowerCase().includes(search.toLowerCase()) ||
        owner?.companyName?.toLowerCase().includes(search.toLowerCase())
      );
    });
  }, [services, vehicles, customers, search]);

  const columns = useMemo(() => ({
    waiting: filteredOrders.filter(o => o.status === 'naplánováno').sort((a, b) => a.date.localeCompare(b.date)),
    active: filteredOrders.filter(o => o.status === 'probíhá').sort((a, b) => a.date.localeCompare(b.date)),
    done: filteredOrders.filter(o => o.status === 'hotovo' || o.status === 'zrušeno').sort((a, b) => b.date.localeCompare(a.date)),
  }), [filteredOrders]);

  const currentVehicle = vehicles.find(v => v.id === formData.vehicleId);
  const currentCustomer = currentVehicle ? customers.find(c => c.id === currentVehicle.customerId) : null;

  const renderOrderCard = (order: ServiceRecord) => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    const customer = customers.find(c => c.id === vehicle?.customerId);

    return (
      <div key={order.id} className="bg-white rounded-3xl border border-slate-100 p-6 shadow-sm hover:shadow-xl transition-all group relative animate-in fade-in zoom-in-95 duration-300">
        <div className="absolute top-0 right-0 p-4">
          <div className="relative">
            <button 
              onClick={() => setOpenMenuId(openMenuId === order.id ? null : order.id)}
              className={`p-2 rounded-xl transition-all ${openMenuId === order.id ? 'bg-slate-100 text-slate-900' : 'text-slate-300 hover:text-slate-900'}`}
            >
              <MoreHorizontal className="w-6 h-6" />
            </button>

            {openMenuId === order.id && (
              <div ref={menuRef} className="absolute top-12 right-0 w-48 bg-white rounded-2xl shadow-2xl border border-slate-100 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200">
                <button onClick={() => handleEdit(order)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-sm font-bold">
                  <Edit3 className="w-4 h-4 text-slate-400" />
                  Upravit / Detail
                </button>
                {order.status === 'hotovo' && onCreateInvoice && (
                  <button onClick={() => { onCreateInvoice(order.id); setOpenMenuId(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-blue-50 text-blue-600 transition-colors text-sm font-bold">
                    <Receipt className="w-4 h-4" />
                    Vystavit fakturu
                  </button>
                )}
                <button onClick={() => { setDeletingOrder(order); setOpenMenuId(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold">
                  <Trash2 className="w-4 h-4" />
                  Smazat zakázku
                </button>
              </div>
            )}
          </div>
        </div>

        <div className="flex items-center gap-5 mb-5">
          <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-white shadow-lg transition-transform group-hover:scale-105 ${
            order.status === 'hotovo' ? 'bg-emerald-500 shadow-emerald-500/20' : 
            order.status === 'probíhá' ? 'bg-amber-500 shadow-amber-500/20' : 
            'bg-blue-600 shadow-blue-600/20'
          }`}>
            <ClipboardList className="w-7 h-7" />
          </div>
          <div>
            <h3 className="text-base font-black text-slate-900 leading-tight">#{order.id}</h3>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">{order.date}</p>
          </div>
        </div>

        <div className="space-y-3 pt-4 border-t border-slate-50">
          <div className="flex items-center gap-3 text-slate-600">
            <div className="p-2 bg-slate-50 rounded-lg"><Car className="w-4 h-4" /></div>
            <div className="min-w-0">
              <p className="text-xs font-bold text-slate-900 truncate">{vehicle ? `${vehicle.make} ${vehicle.model}` : 'Neznámý vůz'}</p>
              <p className="text-[9px] font-mono font-bold text-blue-600 uppercase">{vehicle?.licensePlate || '---'}</p>
            </div>
          </div>
          <div className="flex items-center gap-3 text-slate-600">
            <div className="p-2 bg-slate-50 rounded-lg"><User className="w-4 h-4" /></div>
            <span className="text-xs font-bold text-slate-700 truncate">
              {customer ? (customer.companyName || `${customer.firstName} ${customer.lastName}`) : 'Bez zákazníka'}
            </span>
          </div>
          <div className="flex items-start gap-3 text-slate-600 pt-2">
            <div className="p-2 bg-slate-50 rounded-lg"><FileText className="w-4 h-4 shrink-0" /></div>
            <p className="text-xs font-medium text-slate-500 italic line-clamp-2 leading-relaxed">
              {order.description || 'Bez popisu...'}
            </p>
          </div>
        </div>

        <div className="mt-6 flex items-center justify-between bg-slate-50 p-3 rounded-2xl">
          <div className="flex flex-col">
            <span className="text-[8px] font-black text-slate-400 uppercase">Celkem s DPH</span>
            <span className="text-sm font-black text-slate-900">{Math.round(order.cost * 1.21).toLocaleString()} Kč</span>
          </div>
          <div className="flex items-center gap-2">
            <span className={`text-[9px] font-black uppercase px-2.5 py-1 rounded-full border ${
              order.status === 'hotovo' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' :
              order.status === 'probíhá' ? 'bg-amber-50 text-amber-600 border-amber-100' :
              'bg-blue-50 text-blue-600 border-blue-100'
            }`}>
              {order.status}
            </span>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">

      <div className="hidden print:block">
        <PrintTemplate 
          order={{...formData, id: editingOrderId || 'NÁVRH', cost: calculatedCost}} 
          company={companyInfo} 
          vehicles={vehicles} 
          customers={customers} 
          hourlyRate={hourlyRate} 
        />
      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 print:hidden">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Přehled zakázek</h2>
          <p className="text-slate-500 font-medium">Správa zakázkových listů a plánování.</p>
        </div>
        <button 
          onClick={handleAddNew}
          className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg shadow-blue-200"
        >
          <Plus className="w-5 h-5" />
          Nová zakázka
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3 print:hidden">
        <Search className="w-5 h-5 text-slate-400" />
        <input 
          type="text" 
          placeholder="Hledat zakázku (ID, SPZ, Zákazník)..." 
          className="flex-1 text-sm font-medium outline-none bg-transparent"
          value={search}
          onChange={(e) => onSearchChange(e.target.value)}
        />
        {search && (
