      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 print:hidden">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Přehled zakázek</h2>
          <p className="text-slate-500 font-medium">Správa zakázkových listů a plánování.</p>
        </div>
        <button 
          onClick={handleAddNew}
          className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg shadow-blue-200"
        >
          <Plus className="w-5 h-5" />
          Nová zakázka
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3 print:hidden">
        <Search className="w-5 h-5 text-slate-400" />
        <input 
          type="text" 
          placeholder="Hledat zakázku (ID, SPZ, Zákazník)..." 
          className="flex-1 text-sm font-medium outline-none bg-transparent"
          value={search}
          onChange={(e) => onSearchChange(e.target.value)}
        />
        {search && (
          <button onClick={() => onSearchChange('')} className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all">Zrušit filtr</button>
        )}
      </div>

      {/* Kanban Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8 pb-12 print:hidden min-h-[600px]">

        {/* Column 1: Waiting */}
        <div className="space-y-6">
          <div className="flex items-center justify-between px-2">
            <div className="flex items-center gap-3">
              <div className="w-2.5 h-2.5 rounded-full bg-blue-600"></div>
              <h3 className="text-sm font-black text-slate-600 uppercase tracking-widest">K VYŘÍZENÍ</h3>
            </div>
            <span className="bg-slate-100 px-2.5 py-1 rounded-full text-[10px] font-black text-slate-500">{columns.waiting.length}</span>
          </div>
          <div className="space-y-4">
            {columns.waiting.map(renderOrderCard)}
            {columns.waiting.length === 0 && (
              <div className="py-20 text-center bg-slate-50/50 rounded-[2.5rem] border-2 border-dashed border-slate-200/50">
                <Clock className="w-10 h-10 text-slate-200 mx-auto mb-3" />
                <p className="text-xs font-bold text-slate-400 italic">Žádné čekající zakázky.</p>
              </div>
            )}
          </div>
        </div>

        {/* Column 2: Active */}
        <div className="space-y-6">
          <div className="flex items-center justify-between px-2">
            <div className="flex items-center gap-3">
              <div className="w-2.5 h-2.5 rounded-full bg-amber-500 animate-pulse"></div>
              <h3 className="text-sm font-black text-amber-700 uppercase tracking-widest">PROBÍHÁ</h3>
            </div>
            <span className="bg-amber-100 px-2.5 py-1 rounded-full text-[10px] font-black text-amber-600">{columns.active.length}</span>
          </div>
          <div className="space-y-4">
            {columns.active.map(renderOrderCard)}
            {columns.active.length === 0 && (
              <div className="py-20 text-center bg-amber-50/20 rounded-[2.5rem] border-2 border-dashed border-amber-200/30">
                <Timer className="w-10 h-10 text-amber-100 mx-auto mb-3" />
                <p className="text-xs font-bold text-amber-400 italic">Žádná aktivní práce.</p>
              </div>
            )}
          </div>
        </div>

        {/* Column 3: Done */}
        <div className="space-y-6">
          <div className="flex items-center justify-between px-2">
            <div className="flex items-center gap-3">
              <div className="w-2.5 h-2.5 rounded-full bg-emerald-500"></div>
              <h3 className="text-sm font-black text-emerald-700 uppercase tracking-widest">HOTOVO / UZAVŘENO</h3>
            </div>
            <span className="bg-emerald-100 px-2.5 py-1 rounded-full text-[10px] font-black text-emerald-600">{columns.done.length}</span>
          </div>
          <div className="space-y-4">
            {columns.done.map(renderOrderCard)}
            {columns.done.length === 0 && (
              <div className="py-20 text-center bg-emerald-50/20 rounded-[2.5rem] border-2 border-dashed border-emerald-200/30">
                <CheckCircle2 className="w-10 h-10 text-emerald-100 mx-auto mb-3" />
                <p className="text-xs font-bold text-emerald-400 italic">Dnes ještě není nic hotovo.</p>
              </div>
            )}
          </div>
        </div>

      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 print:hidden">
          <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md" onClick={() => setIsModalOpen(false)}></div>

          <div className="bg-white w-full max-w-[1100px] h-[95vh] rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden flex flex-col animate-in zoom-in-95 duration-300">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50 shrink-0">
              <div className="flex items-center gap-4">
                <div className="bg-blue-600 p-2 rounded-xl text-white"><FileText className="w-6 h-6" /></div>
                <h3 className="text-xl font-black tracking-tight uppercase">Editace Zakázkového Listu</h3>
              </div>
              <div className="flex gap-4">
                <button 
                  type="button"
                  onClick={() => window.print()}
                  className="bg-slate-100 text-slate-700 px-6 py-3 rounded-xl font-black text-sm flex items-center gap-2 hover:bg-slate-200"
                >
                  <Printer className="w-5 h-5" /> TISKNOUT
                </button>
                <button 
                  onClick={handleSubmit}
                  className="bg-blue-600 text-white px-8 py-3 rounded-xl font-black text-sm flex items-center gap-2 shadow-lg shadow-blue-200 hover:bg-blue-700"
                >
                  <Check className="w-5 h-5" /> ULOŽIT ZAKÁZKU
                </button>
                <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-slate-100 rounded-xl">
                  <X className="w-6 h-6 text-slate-400" />
                </button>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-12 bg-slate-200/50 flex justify-center custom-scrollbar">

              <div className="bg-white shadow-2xl p-10 font-sans text-black border-[1px] border-slate-300 w-full max-w-[250mm] min-h-[297mm] h-fit" style={{ fontSize: '12px' }}>

                <div className="grid grid-cols-12 border-2 border-black">

                  <div className="col-span-4 border-r-2 border-b-2 border-black p-3 bg-slate-50/50">
                    <p className="text-[8px] font-black uppercase mb-1">Opravna - DIČ</p>
                    <p className="font-black text-sm uppercase leading-tight">{companyInfo.name}</p>
                    <p className="font-bold text-[10px] mt-1">{companyInfo.address}</p>
                    <p className="text-[8px] mt-1">IČO: {companyInfo.ico} | DIČ: {companyInfo.dic}</p>
                  </div>

                  <div className="col-span-4 border-r-2 border-b-2 border-black p-3">
                    <p className="text-[8px] font-black uppercase mb-1">Zákazník</p>
                    <div className="font-black text-xs">
                       {currentCustomer ? (
                         <>
                           <p className="text-blue-700 uppercase">{currentCustomer.companyName || `${currentCustomer.firstName} ${currentCustomer.lastName}`}</p>
                           <p className="text-[10px] font-bold mt-1">{currentCustomer.address}</p>
                           <p className="text-[9px] mt-1">Tel: {currentCustomer.phone}</p>
                         </>
                       ) : (
                         <p className="text-slate-300 italic">Vozidlo neurčeno...</p>
                       )}
                    </div>
                  </div>

                  <div className="col-span-4 border-b-2 border-black p-4 flex flex-col justify-between items-center bg-slate-100">
                    <h1 className="text-xl font-black uppercase tracking-widest text-center">ZAKÁZKOVÝ LIST</h1>
                    <div className="flex items-center w-full gap-2 mt-2">
                       <span className="font-black text-lg">č.</span>
                       <input 
                        type="text"
                        disabled
                        className="bg-transparent border-b-2 border-black flex-1 text-center font-black text-xl outline-none"
                        value={editingOrderId || 'NÁVRH'}
                       />
                    </div>
                  </div>

                  <div className="col-span-8 border-r-2 border-black grid grid-cols-4 bg-white">

                    {[
                      { key: 'rezerva', label: 'Rezerva' },
                      { key: 'trojuhelnik', label: 'Trojúhelník' },
                      { key: 'zvedak', label: 'Zvedák' },
                      { key: 'lekarna', label: 'Lékárna' },
                      { key: 'klic', label: 'Klíč kol.' },
                      { key: 'radio', label: 'Radio' },
                      { key: 'naradi', label: 'Nářadí' },
                      { key: 'reflektory', label: 'Reflektory' },
                      { key: 'hustilka', label: 'Hustilka' },
                      { key: 'nosic', label: 'Nosič' },
                    ].map((item) => (
                      <div 
