            <div className="mt-auto border-t-[1.5pt] border-black bg-gray-50 p-4 space-y-1.5">
               <div className="flex justify-between font-black text-[9px]">
                 <span className="opacity-60 uppercase">Mechanik: {order.technician}</span>
               </div>
               <div className="flex justify-between font-black text-[9px]">
                 <span className="opacity-60 uppercase">Práce ({order.laborHours || 0} h x {hourlyRate} Kč)</span>
                 <span>{( (order.laborHours || 0) * hourlyRate).toLocaleString()} Kč</span>
               </div>
               <div className="flex justify-between font-black text-[9px] border-b border-black pb-1.5">
                 <span className="uppercase">Celkem bez DPH</span>
                 <span>{order.cost.toLocaleString()} Kč</span>
               </div>
               <div className="flex flex-col items-center pt-2">
                 <p className="text-[7.5px] font-black uppercase tracking-[0.2em] opacity-60 mb-0.5">Celkem k úhradě vč. DPH 21%</p>
                 <p className="text-[20px] font-black leading-none">{((order.cost || 0) * 1.21).toLocaleString(undefined, {maximumFractionDigits:0})} Kč</p>
               </div>
            </div>
          </div>
        </div>
      </div>

      <div className="mt-auto pt-16 flex justify-between px-16 mb-8">
         <div className="text-center w-72">
           <div className="border-t-[1.5pt] border-black pt-2 mb-1">
             <p className="text-[9px] font-black uppercase tracking-widest">Za AutoServis (Razítko a podpis)</p>
           </div>
           <p className="text-[8px] font-bold text-gray-300">Převzal dne {new Date().toLocaleDateString()}</p>
         </div>
         <div className="text-center w-72">
           <div className="border-t-[1.5pt] border-black pt-2 mb-1">
             <p className="text-[9px] font-black uppercase tracking-widest">Za Zákazníka (Podpis)</p>
           </div>
           <p className="text-[8px] font-bold text-gray-300">Souhlasím s převzetím a cenou</p>
         </div>
      </div>

      <div className="pt-4 flex justify-between text-[6px] font-black text-gray-400 border-t border-gray-100 uppercase tracking-widest">
         <span>ZAKÁZKA ID: {order.id}</span>
         <span>DOKUMENT GENEROVÁN: {new Date().toLocaleString()}</span>
         <span>SYSTÉM: AUTOSERVICE PRO DB v2.5</span>
      </div>
    </div>
  );
};

export default OrderManager;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Search, 
  Plus, 
  Mail, 
  Phone, 
  MapPin, 
  MoreHorizontal, 
  UserPlus, 
  X, 
  Check, 
  Car, 
  Calendar,
  ChevronRight,
  User as UserIcon,
  Edit3,
  Trash2,
  AlertCircle,
  Building2,
  Briefcase
} from 'lucide-react';
import { Customer, Vehicle } from '../types';

interface CustomerProps {
  customers: Customer[];
  vehicles: Vehicle[];
  setCustomers: React.Dispatch<React.SetStateAction<Customer[]>>;
  onAddCustomer: (customer: Customer) => void;
  onUpdateCustomer?: (customer: Customer) => void;
  onDeleteCustomer?: (id: string) => void;
  onNavigateToVehicle?: (vehicleId: string) => void;
  initialCustomerId?: string | null;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  search: string;
  onSearchChange: (value: string) => void;
}

const CustomerManager: React.FC<CustomerProps> = ({ 
  customers, 
  vehicles, 
  onAddCustomer, 
  onUpdateCustomer, 
  onDeleteCustomer,
  onNavigateToVehicle,
  initialCustomerId,
  autoOpen,
  onModalOpened,
  search,
  onSearchChange
}) => {
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);
  const [deletingCustomer, setDeletingCustomer] = useState<Customer | null>(null);
  const [selectedDetailCustomer, setSelectedDetailCustomer] = useState<Customer | null>(null);
  const [selectedVehiclesCustomer, setSelectedVehiclesCustomer] = useState<Customer | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const initialFormData = {
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    address: '',
    companyName: '',
    companyAddress: '',
    ico: '',
    dic: ''
  };

  const [formData, setFormData] = useState(initialFormData);

  useEffect(() => {
    if (autoOpen) {
      handleOpenAdd();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const filtered = customers
    .filter(c => 
      `${c.firstName} ${c.lastName}`.toLowerCase().includes(search.toLowerCase()) ||
      c.email.toLowerCase().includes(search.toLowerCase()) ||
      (c.companyName && c.companyName.toLowerCase().includes(search.toLowerCase())) ||
      c.phone.includes(search)
    )
    .sort((a, b) => (a.lastName || '').localeCompare(b.lastName || '', 'cs'));

  const handleOpenAdd = () => {
    setEditingCustomer(null);
    setFormData(initialFormData);
    setIsAddModalOpen(true);
  };

  const handleOpenEdit = (customer: Customer) => {
    setEditingCustomer(customer);
    setFormData({
      firstName: customer.firstName,
      lastName: customer.lastName,
      email: customer.email,
      phone: customer.phone,
      address: customer.address,
      companyName: customer.companyName || '',
      companyAddress: customer.companyAddress || '',
      ico: customer.ico || '',
      dic: customer.dic || ''
    });
    setIsAddModalOpen(true);
    setOpenMenuId(null);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Clean up empty optional fields
    const submissionData = {
      ...formData,
      companyName: formData.companyName.trim() || undefined,
      companyAddress: formData.companyAddress.trim() || undefined,
      ico: formData.ico.trim() || undefined,
      dic: formData.dic.trim() || undefined
    };

    if (editingCustomer) {
      if (onUpdateCustomer) {
        onUpdateCustomer({
          ...editingCustomer,
          ...submissionData
        });
      }
    } else {
      const newCustomer: Customer = {
        ...submissionData,
        id: `c${Date.now()}`,
        createdAt: new Date().toISOString().split('T')[0]
      };
      onAddCustomer(newCustomer);
    }
    setIsAddModalOpen(false);
    setFormData(initialFormData);
  };

  const confirmDelete = () => {
    if (deletingCustomer && onDeleteCustomer) {
      onDeleteCustomer(deletingCustomer.id);
      setDeletingCustomer(null);
    }
  };

  const handleViewVehicle = (vehicleId: string) => {
    if (onNavigateToVehicle) {
      onNavigateToVehicle(vehicleId);
      setSelectedVehiclesCustomer(null);
    }
  };

  const customerVehicles = selectedVehiclesCustomer 
    ? vehicles.filter(v => v.customerId === selectedVehiclesCustomer.id)
    : [];

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Zákazníci</h2>
          <p className="text-slate-500 font-medium">Správa kontaktů a klientských karet.</p>
        </div>
        <button 
          onClick={handleOpenAdd}
          className="bg-slate-900 text-white px-6 py-3 rounded-2xl font-bold hover:bg-slate-800 transition-all flex items-center gap-2 shadow-lg shadow-slate-200"
        >
          <UserPlus className="w-5 h-5" />
          Nový zákazník
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
        <Search className="w-5 h-5 text-slate-400" />
        <input 
          type="text" 
          placeholder="Hledat podle jména, emailu, firmy nebo telefonu..." 
          className="flex-1 text-sm font-medium outline-none bg-transparent"
          value={search}
          onChange={(e) => onSearchChange(e.target.value)}
        />
        {search && (
          <button 
            onClick={() => onSearchChange('')}
            className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all"
          >
            Zrušit filtr
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filtered.map(c => (
          <div key={c.id} className="bg-white rounded-3xl border border-slate-100 p-6 shadow-sm hover:shadow-xl transition-all group relative overflow-visible">
            <div className="absolute top-0 right-0 p-4">
              <div className="relative">
                <button 
                  onClick={() => setOpenMenuId(openMenuId === c.id ? null : c.id)}
                  className={`p-2 rounded-xl transition-all ${openMenuId === c.id ? 'bg-slate-100 text-slate-900' : 'text-slate-300 hover:text-slate-900'}`}
                >
                  <MoreHorizontal className="w-6 h-6" />
                </button>

                {openMenuId === c.id && (
                  <div 
                    ref={menuRef}
                    className="absolute top-12 right-0 w-48 bg-white rounded-2xl shadow-2xl border border-slate-100 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200"
                  >
                    <button 
                      onClick={() => handleOpenEdit(c)}
                      className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-sm font-bold"
                    >
                      <Edit3 className="w-4 h-4 text-slate-400" />
                      Upravit kartu
                    </button>
                    <button 
                      onClick={() => { setDeletingCustomer(c); setOpenMenuId(null); }}
                      className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold"
                    >
                      <Trash2 className="w-4 h-4" />
                      Smazat kartu
                    </button>
                  </div>
                )}
              </div>
            </div>

            <div className="flex items-center gap-5 mb-6">
              <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-white font-black text-xl shadow-lg transition-transform group-hover:scale-105 ${c.companyName ? 'bg-slate-900 shadow-slate-900/20' : 'bg-blue-600 shadow-blue-600/20'}`}>
                {c.companyName ? <Building2 className="w-8 h-8" /> : <>{c.firstName[0]}{c.lastName[0]}</>}
              </div>
              <div>
                <h3 className="text-lg font-black text-slate-900 leading-tight">
                  {c.companyName || `${c.firstName} ${c.lastName}`}
                </h3>
                {c.companyName && (
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter mt-0.5">
                    Kontakt: {c.firstName} {c.lastName}
                  </p>
                )}
                <p className="text-xs font-bold text-slate-400 uppercase tracking-tighter mt-0.5">Klient od {c.createdAt}</p>
              </div>
            </div>

            <div className="space-y-3 pt-4 border-t border-slate-50">
              <div className="flex items-center gap-3 text-slate-600">
                <div className="p-2 bg-slate-50 rounded-lg"><Mail className="w-4 h-4" /></div>
                <span className="text-sm font-semibold truncate">{c.email || 'Bez e-mailu'}</span>
              </div>
              <div className="flex items-center gap-3 text-slate-600">
                <div className="p-2 bg-slate-50 rounded-lg"><Phone className="w-4 h-4" /></div>
                <span className="text-sm font-semibold">{c.phone}</span>
              </div>
              <div className="flex items-center gap-3 text-slate-600">
                <div className="p-2 bg-slate-50 rounded-lg"><MapPin className="w-4 h-4" /></div>
                <span className="text-sm font-semibold truncate">{c.address || 'Bez adresy'}</span>
              </div>
            </div>

            <div className="mt-6 flex gap-2">
              <button 
                onClick={() => setSelectedDetailCustomer(c)}
                className="flex-1 py-3 bg-slate-100 text-slate-900 rounded-xl font-bold text-xs hover:bg-slate-200 transition-colors uppercase tracking-wider"
              >
                Detail
              </button>
              <button 
                onClick={() => setSelectedVehiclesCustomer(c)}
                className="flex-1 py-3 bg-blue-50 text-blue-600 rounded-xl font-bold text-xs hover:bg-blue-100 transition-colors uppercase tracking-wider"
              >
                Vozidla
              </button>
            </div>
          </div>
        ))}
      </div>

      {/* Delete Confirmation Modal */}
      {deletingCustomer && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setDeletingCustomer(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6">
                <AlertCircle className="w-10 h-10" />
              </div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-2">Opravdu smazat?</h3>
              <p className="text-slate-500 font-medium mb-8 leading-relaxed">
                Opravdu chcete smazat kartu zákazníka <span className="font-bold text-slate-900">{deletingCustomer.companyName || `${deletingCustomer.firstName} ${deletingCustomer.lastName}`}</span>? Tato akce je nevratná.
              </p>
              <div className="flex gap-3">
                <button 
                  onClick={() => setDeletingCustomer(null)}
                  className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm hover:bg-slate-200 transition-all"
                >
                  ZRUŠIT
                </button>
                <button 
                  onClick={confirmDelete}
                  className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm hover:bg-red-700 transition-all shadow-lg shadow-red-600/20"
                >
                  SMAZAT
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Detail Modal */}
      {selectedDetailCustomer && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setSelectedDetailCustomer(null)}></div>
          <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-slate-900 p-8 text-white flex justify-between items-center">
              <div className="flex items-center gap-4">
                <div className={`w-12 h-12 rounded-xl flex items-center justify-center font-black ${selectedDetailCustomer.companyName ? 'bg-slate-700' : 'bg-blue-600'}`}>
                  {selectedDetailCustomer.companyName ? <Building2 className="w-6 h-6" /> : <>{selectedDetailCustomer.firstName[0]}{selectedDetailCustomer.lastName[0]}</>}
                </div>
                <div>
                  <h3 className="text-xl font-black tracking-tight">
                    {selectedDetailCustomer.companyName || `${selectedDetailCustomer.firstName} ${selectedDetailCustomer.lastName}`}
                  </h3>
                  <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mt-1">Kompletní karta zákazníka</p>
                </div>
              </div>
              <button onClick={() => setSelectedDetailCustomer(null)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>
            <div className="p-8 space-y-6">
              {/* Business Info Section if exists */}
              {selectedDetailCustomer.companyName && (
                <div className="bg-slate-50 p-6 rounded-2xl border border-slate-100">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <Briefcase className="w-3 h-3" /> Firemní údaje
                  </h4>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Název firmy</p>
                      <p className="text-sm font-bold text-slate-900">{selectedDetailCustomer.companyName}</p>
                    </div>
                    <div className="space-y-1">
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">IČO</p>
                      <p className="text-sm font-bold text-slate-900">{selectedDetailCustomer.ico || 'N/A'}</p>
                    </div>
                    {selectedDetailCustomer.companyAddress && (
                      <div className="col-span-2 space-y-1">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Sídlo firmy</p>
                        <p className="text-sm font-bold text-slate-900">{selectedDetailCustomer.companyAddress}</p>
                      </div>
                    )}
                    {selectedDetailCustomer.dic && (
                      <div className="space-y-1">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">DIČ</p>
                        <p className="text-sm font-bold text-slate-900">{selectedDetailCustomer.dic}</p>
                      </div>
                    )}
                  </div>
                </div>
              )}

              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Kontakt</p>
                  <p className="text-sm font-bold text-slate-900">{selectedDetailCustomer.firstName} {selectedDetailCustomer.lastName}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Email</p>
                  <p className="text-sm font-bold text-slate-900">{selectedDetailCustomer.email || 'Neuvedeno'}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Telefon</p>
                  <p className="text-sm font-bold text-slate-900">{selectedDetailCustomer.phone}</p>
                </div>
                <div className="col-span-2 space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Adresa</p>
                  <p className="text-sm font-bold text-slate-900">{selectedDetailCustomer.address || 'Neuvedeno'}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Registrován</p>
                  <p className="text-sm font-bold text-slate-900">{selectedDetailCustomer.createdAt}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">ID Zákazníka</p>
                  <p className="text-sm font-mono font-bold text-blue-600">{selectedDetailCustomer.id}</p>
                </div>
              </div>
              <button 
                onClick={() => setSelectedDetailCustomer(null)}
                className="w-full bg-slate-900 text-white font-black py-4 rounded-2xl transition-all"
              >
                ZAVŘÍT
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Vehicles Modal */}
      {selectedVehiclesCustomer && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setSelectedVehiclesCustomer(null)}></div>
          <div className="bg-white w-full max-w-xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-blue-600 p-8 text-white flex justify-between items-center">
              <div>
                <h3 className="text-xl font-black tracking-tight">Vozidla zákazníka</h3>
                <p className="text-blue-100 text-[10px] font-black uppercase tracking-widest mt-1">
                  {selectedVehiclesCustomer.companyName || `${selectedVehiclesCustomer.firstName} ${selectedVehiclesCustomer.lastName}`}
                </p>
              </div>
              <button onClick={() => setSelectedVehiclesCustomer(null)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>
            <div className="p-8 space-y-4 max-h-[60vh] overflow-y-auto">
              {customerVehicles.length > 0 ? (
                customerVehicles.map(v => (
                  <div 
                    key={v.id} 
                    onClick={() => handleViewVehicle(v.id)}
                    className="bg-slate-50 p-5 rounded-2xl border border-slate-100 flex items-center justify-between group hover:bg-white hover:shadow-lg hover:border-blue-200 transition-all cursor-pointer"
                  >
                    <div className="flex items-center gap-5">
                      <div className="w-12 h-12 bg-white rounded-xl shadow-sm flex items-center justify-center">
                        <Car className="w-6 h-6 text-slate-400 group-hover:text-blue-600 transition-colors" />
                      </div>
                      <div>
                        <p className="text-sm font-black text-slate-900">{v.make} {v.model}</p>
                        <p className="text-[10px] font-bold text-blue-600 font-mono tracking-wider">{v.licensePlate}</p>
                      </div>
                    </div>
                    <div className="text-right flex items-center gap-4">
                      <div className="hidden sm:block">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Přejít na kartu</p>
                        <p className="text-xs font-bold text-slate-900">{v.stkExpirationDate}</p>
                      </div>
                      <ChevronRight className="w-5 h-5 text-slate-300 group-hover:text-blue-600 group-hover:translate-x-1 transition-all" />
                    </div>
                  </div>
                ))
              ) : (
                <div className="text-center py-10">
                  <Car className="w-12 h-12 text-slate-200 mx-auto mb-4" />
                  <p className="text-slate-400 font-bold italic">Tento zákazník nemá v evidenci žádná vozidla.</p>
                </div>
              )}
            </div>
            <div className="p-8 border-t border-slate-50">
               <button 
                onClick={() => setSelectedVehiclesCustomer(null)}
                className="w-full bg-slate-100 hover:bg-slate-200 text-slate-900 font-black py-4 rounded-2xl transition-all"
              >
                ZAVŘÍT
              </button>
            </div>
          </div>
        </div>
      )}

      {/* New / Edit Customer Modal */}
      {isAddModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-slate-900 p-8 text-white flex justify-between items-center">
              <div>
                <h3 className="text-2xl font-black tracking-tight">{editingCustomer ? 'Upravit zákazníka' : 'Nový zákazník'}</h3>
                <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">
                  {editingCustomer ? `Editace ID ${editingCustomer.id}` : 'Registrace do systému'}
                </p>
              </div>
              <button onClick={() => setIsAddModalOpen(false)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-8 space-y-6 max-h-[80vh] overflow-y-auto custom-scrollbar">
              <div className="space-y-4">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] border-b pb-2">Osobní údaje</h4>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Jméno *</label>
                    <input 
                      required
                      type="text" 
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold"
                      value={formData.firstName}
                      onChange={e => setFormData({...formData, firstName: e.target.value})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Příjmení *</label>
                    <input 
                      required
                      type="text" 
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold"
                      value={formData.lastName}
                      onChange={e => setFormData({...formData, lastName: e.target.value})}
                    />
                  </div>
                </div>
              </div>

              <div className="space-y-4">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] border-b pb-2">Firemní údaje (volitelné)</h4>
                <div className="space-y-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Název firmy</label>
                    <input 
                      type="text" 
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-4 py-3 outline-none transition-all font-bold"
                      value={formData.companyName}
                      onChange={e => setFormData({...formData, companyName: e.target.value})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Sídlo firmy (adresa)</label>
                    <input 
                      type="text" 
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-4 py-3 outline-none transition-all font-bold"
                      value={formData.companyAddress}
                      onChange={e => setFormData({...formData, companyAddress: e.target.value})}
                    />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">IČO</label>
                      <input 
                        type="text" 
                        className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-4 py-3 outline-none transition-all font-bold"
                        value={formData.ico}
                        onChange={e => setFormData({...formData, ico: e.target.value})}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">DIČ</label>
                      <input 
                        type="text" 
                        className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-4 py-3 outline-none transition-all font-bold"
                        value={formData.dic}
                        onChange={e => setFormData({...formData, dic: e.target.value})}
                      />
                    </div>
                  </div>
                </div>
              </div>

              <div className="space-y-4">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] border-b pb-2">Kontaktní údaje</h4>
                <div className="space-y-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Email</label>
                    <input 
                      type="email" 
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold"
                      value={formData.email}
                      onChange={e => setFormData({...formData, email: e.target.value})}
                    />
                  </div>

                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Telefon *</label>
                    <input 
                      required
                      type="tel" 
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold"
                      value={formData.phone}
                      onChange={e => setFormData({...formData, phone: e.target.value})}
                    />
                  </div>

                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Adresa bydliště</label>
                    <input 
                      type="text" 
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold"
                      value={formData.address}
                      onChange={e => setFormData({...formData, address: e.target.value})}
                    />
                  </div>
                </div>
              </div>

              <button 
                type="submit"
                className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-600/20 transition-all flex items-center justify-center gap-2 mt-4"
              >
                <Check className="w-5 h-5" />
                {editingCustomer ? 'ULOŽIT ZMĚNY' : 'ULOŽIT ZÁKAZNÍKA'}
              </button>
            </form>
          </div>
        </div>
      )}

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: #f1f5f9;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #cbd5e1;
          border-radius: 10px;
        }
      `}</style>
    </div>
  );
};

