export interface PartItem {
  id: string;
  description: string;
  quantity: number;
  unit: string;
  unitPrice: number;
}

export interface FixedService {
  id: string;
  name: string;
  price: number;
}

export interface PredefinedTask {
  id: string;
  label: string;
  description: string;
}

export interface Invoice {
  id: string;
  orderId: string;
  issueDate: string;
  dueDate: string;
  customerId: string;
  vehicleInfo: string;
  items: PartItem[];
  totalExclDph: number;
  totalInclDph: number;
