  id: string;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  address: string;
  createdAt: string;
  // Firemní údaje
  companyName?: string;
  companyAddress?: string;
  ico?: string;
  dic?: string;
}

export interface Vehicle {
  id: string;
  customerId: string;
  make: string;
  model: string;
  year: number;
  vin: string;
  licensePlate: string;
  mileage: number;
  engineCode: string;
  color: string;
  lastServiceDate: string;
  stkExpirationDate: string;
  nextServiceDate: string;
  serviceIntervalKm?: number;
  serviceIntervalMonths?: number;
  notes?: string;
}

export interface VehicleChecklist {
  rezerva: boolean;
  zvedak: boolean;
  klic: boolean;
  naradi: boolean;
  hustilka: boolean;
  trojuhelnik: boolean;
  lekarna: boolean;
  radio: boolean;
  reflektory: boolean;
  nosic: boolean;
}

export interface ServiceRecord {
  id: string;
  vehicleId: string;
  date: string;
  endDate?: string;
  deliveryDate?: string;
  description: string;
  parts?: PartItem[];
  laborHours?: number;
  cost: number;
  status: 'naplánováno' | 'probíhá' | 'hotovo' | 'zrušeno';
  technician: string;
  fuelLevel?: '1/4' | '1/2' | '3/4' | 'Full' | 'Rezerva';
  checklist?: VehicleChecklist;
  mileageAtEntry?: number;
  estimatedPrice?: number;
  paymentType?: 'Hotovost' | 'Faktura' | 'Pojišťovna';
}

export interface CompanyInfo {
  name: string;
  address: string;
  ico: string;
  dic: string;
  phone: string;
  email: string;
}

export interface NotificationSettings {
  stkThresholdDays: number;
  serviceThresholdDays: number;
}

export interface AutoBackupSettings {
  enabled: boolean;
  hour: number;
  lastBackupDate: string | null;
  folderName: string | null;
}

export interface UserSettings {
  enabled: boolean;
  username: string;
  password: string;
}

