                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Calendar className="w-3 h-3" /> Rok výroby</p>
                  <p className="text-sm font-bold text-slate-900">{selectedDetailVehicle.year}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Cpu className="w-3 h-3" /> Kód motoru</p>
                  <p className="text-sm font-bold text-slate-900">{selectedDetailVehicle.engineCode}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Plus className="w-3 h-3" /> Pohon</p>
