            onClick={() => onSelect(inv)}
            className="p-2.5 bg-slate-900 text-white rounded-xl hover:bg-blue-600 transition-all shadow-lg shadow-slate-900/10"
           >
             <Printer className="w-4 h-4" />
           </button>
           <button 
            onClick={() => onDelete(inv)}
            className="p-2.5 bg-red-50 text-red-500 rounded-xl hover:bg-red-100 transition-all"
           >
             <Trash2 className="w-4 h-4" />
           </button>
        </div>
      </div>
    </div>
  );
};

const InvoicePrintTemplate: React.FC<{ invoice: Invoice, company: CompanyInfo, customers: Customer[] }> = ({ invoice, company, customers }) => {
  const customer = customers.find(c => c.id === invoice.customerId);
  const baseTotal = invoice.items.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
  const discountAmount = invoice.discount ? (baseTotal * (invoice.discount / 100)) : 0;
  const discountedBaseTotal = baseTotal - discountAmount;
