    return saved ? JSON.parse(saved) : INITIAL_PREDEFINED_TASKS;
  });
  const [discountLevels, setDiscountLevels] = useState<number[]>(() => {
    const saved = localStorage.getItem('discountLevels');
    return saved ? JSON.parse(saved) : [0, 5, 10, 15, 20, 25, 50];
  });
  const [technicians, setTechnicians] = useState<string[]>(() => {
    const saved = localStorage.getItem('technicians');
    return saved ? JSON.parse(saved) : ['Jan Mechanik', 'Petr Rychlý', 'Marek Šikovný', 'Tomáš Pečlivý'];
  });
  const [companyInfo, setCompanyInfo] = useState<CompanyInfo>(() => {
    const saved = localStorage.getItem('companyInfo');
    return saved ? JSON.parse(saved) : {
      name: 'AutoService Pro Praha',
      address: 'Průmyslová 1024/12, 102 00 Praha 10',
      ico: '12345678',
      dic: 'CZ12345678',
      phone: '+420 222 333 444',
      email: 'servis@autoservice.pro'
    };
  });
  const [notifSettings, setNotifSettings] = useState<NotificationSettings>(() => {
    const saved = localStorage.getItem('notifSettings');
    return saved ? JSON.parse(saved) : {
      stkThresholdDays: 30,
      serviceThresholdDays: 15
    };
  });
  const [selectedPrinter, setSelectedPrinter] = useState<string>(() => {
    const saved = localStorage.getItem('selectedPrinter');
    return saved ? JSON.parse(saved) : 'HP LaserJet Pro M404dn (Kancelář)';
  });

  // Security State
  const [userSettings, setUserSettings] = useState<UserSettings>(() => {
    const saved = localStorage.getItem('userSettings');
    return saved ? JSON.parse(saved) : { enabled: false, username: 'admin', password: '' };
  });
  const [isAuthenticated, setIsAuthenticated] = useState(!userSettings.enabled);

  const [autoBackupSettings, setAutoBackupSettings] = useState<AutoBackupSettings>(() => {
    const saved = localStorage.getItem('autoBackupSettings');
    return saved ? JSON.parse(saved) : { enabled: false, hour: 20, lastBackupDate: null, folderName: null };
  });

  // Effects for Persisting State
  useEffect(() => { localStorage.setItem('customers', JSON.stringify(customers)); }, [customers]);
  useEffect(() => { localStorage.setItem('vehicles', JSON.stringify(vehicles)); }, [vehicles]);
  useEffect(() => { localStorage.setItem('services', JSON.stringify(services)); }, [services]);
  useEffect(() => { localStorage.setItem('invoices', JSON.stringify(invoices)); }, [invoices]);
  useEffect(() => { localStorage.setItem('hourlyRate', JSON.stringify(hourlyRate)); }, [hourlyRate]);
  useEffect(() => { localStorage.setItem('fixedServices', JSON.stringify(fixedServices)); }, [fixedServices]);
  useEffect(() => { localStorage.setItem('predefinedTasks', JSON.stringify(predefinedTasks)); }, [predefinedTasks]);
  useEffect(() => { localStorage.setItem('discountLevels', JSON.stringify(discountLevels)); }, [discountLevels]);
  useEffect(() => { localStorage.setItem('technicians', JSON.stringify(technicians)); }, [technicians]);
  useEffect(() => { localStorage.setItem('companyInfo', JSON.stringify(companyInfo)); }, [companyInfo]);
  useEffect(() => { localStorage.setItem('notifSettings', JSON.stringify(notifSettings)); }, [notifSettings]);
  useEffect(() => { localStorage.setItem('selectedPrinter', JSON.stringify(selectedPrinter)); }, [selectedPrinter]);
  useEffect(() => { 
    localStorage.setItem('userSettings', JSON.stringify(userSettings));
    if (!userSettings.enabled) {
      setIsAuthenticated(true);
    }
  }, [userSettings]);

  // Logic for Directory handles etc
  const [directoryHandle, setDirectoryHandle] = useState<FileSystemDirectoryHandle | null>(null);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [targetVehicleId, setTargetVehicleId] = useState<string | null>(null);
  const [targetOrderId, setTargetOrderId] = useState<string | null>(null);
  const [targetCustomerId, setTargetCustomerId] = useState<string | null>(null);
  const [shouldOpenModal, setShouldOpenModal] = useState(false);

  // Sync Mileage Function
  const syncVehicleMileage = useCallback((vehicleId: string, mileageAtEntry?: number) => {
    if (mileageAtEntry === undefined || mileageAtEntry === null || mileageAtEntry === 0) return;
    setVehicles(prevVehicles => prevVehicles.map(v => {
      if (v.id === vehicleId && mileageAtEntry > v.mileage) {
        return { ...v, mileage: mileageAtEntry };
      }
      return v;
    }));
  }, []);

  // Sync Dates Function (STK and Service)
  const syncVehicleDates = useCallback((service: ServiceRecord) => {
    if (service.status !== 'hotovo') return;

    const parts = service.parts || [];
    const hasSTK = parts.some(p => p.description.toLowerCase().includes('stk'));
    const hasOil = parts.some(p => 
      p.description.toLowerCase().includes('motorovy olej') || 
      p.description.toLowerCase().includes('motorový olej')
    );

    if (!hasSTK && !hasOil) return;

    const baseDateStr = service.deliveryDate || service.date;
    const baseDate = new Date(baseDateStr);
    if (isNaN(baseDate.getTime())) return;

    setVehicles(prevVehicles => prevVehicles.map(v => {
      if (v.id === service.vehicleId) {
        let updates: Partial<Vehicle> = {};

        if (hasSTK) {
          // Standard STK validity is 2 years
          const nextSTK = new Date(baseDate);
          nextSTK.setFullYear(nextSTK.getFullYear() + 2);
          updates.stkExpirationDate = nextSTK.toISOString().split('T')[0];
        }

        if (hasOil) {
          // Add service interval months to completion date
          const nextService = new Date(baseDate);
          const intervalMonths = v.serviceIntervalMonths || 12;
          nextService.setMonth(nextService.getMonth() + intervalMonths);
          updates.nextServiceDate = nextService.toISOString().split('T')[0];
        }

        return { ...v, ...updates };
      }
      return v;
    }));
  }, []);

  const handleAddService = (service: ServiceRecord) => {
    setServices([service, ...services]);
    syncVehicleMileage(service.vehicleId, service.mileageAtEntry);
    syncVehicleDates(service);
  };

  const handleUpdateService = (service: ServiceRecord) => {
    setServices(prev => prev.map(item => item.id === service.id ? service : item));
    syncVehicleMileage(service.vehicleId, service.mileageAtEntry);
    syncVehicleDates(service);
  };

  const handleUpdateInvoice = (updatedInvoice: Invoice) => {
    setInvoices(prev => prev.map(inv => inv.id === updatedInvoice.id ? updatedInvoice : inv));
  };

  const handleCreateInvoiceFromOrder = (orderId: string) => {
    const order = services.find(s => s.id === orderId);
    if (!order) return;

    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    if (!vehicle) return;

    const existingInvoice = invoices.find(inv => inv.orderId === orderId);
    if (existingInvoice) {
      setActiveView('invoices');
      return;
    }

    const items: PartItem[] = [
      ...(order.parts || []),
      { 
        id: `labor-${Date.now()}`, 
        description: `Servisní práce (${order.laborHours || 0} h)`, 
        quantity: order.laborHours || 0, 
        unit: 'h', 
        unitPrice: hourlyRate 
      }
    ];

    const issueDate = new Date();
    const year = issueDate.getFullYear().toString().slice(-2);
    const month = (issueDate.getMonth() + 1).toString().padStart(2, '0');
    const prefix = `${year}/${month}/`;
    const monthlyInvoices = invoices.filter(inv => inv.id.startsWith(prefix));
    const nextSequence = (monthlyInvoices.length + 1).toString().padStart(3, '0');
    const invoiceId = `${prefix}${nextSequence}`;

    const dueDate = new Date();
    dueDate.setDate(issueDate.getDate() + 14);

    const newInvoice: Invoice = {
      id: invoiceId,
      orderId: order.id,
      issueDate: issueDate.toISOString().split('T')[0],
      dueDate: dueDate.toISOString().split('T')[0],
      customerId: vehicle.customerId,
      vehicleInfo: `${vehicle.make} ${vehicle.model} (${vehicle.licensePlate})`,
      items: items,
      totalExclDph: order.cost,
      totalInclDph: Math.round(order.cost * 1.21),
      paymentType: 'Převodem',
      status: 'neuhrazeno',
      discount: 0
    };

    setInvoices([newInvoice, ...invoices]);
    // When creating invoice, we reset search and go to invoices
    setCustomerSearch('');
    setVehicleSearch('');
    setOrderSearch('');
    setInvoiceSearch('');
    setActiveView('invoices');
  };

  const resetAllSearches = () => {
    setCustomerSearch('');
    setVehicleSearch('');
    setOrderSearch('');
    setInvoiceSearch('');
  };

  const handleNavigate = (view: AppView, autoOpen: boolean = false) => {
    // RESET SEARCHES and Targets on manual tab switch
    resetAllSearches();
    setTargetVehicleId(null);
    setTargetOrderId(null);
    setTargetCustomerId(null);
    setActiveView(view);
    setShouldOpenModal(autoOpen);
  };

  const handleRestoreData = (fullState: any) => {
    if (fullState.customers) setCustomers(fullState.customers);
    if (fullState.vehicles) setVehicles(fullState.vehicles);
    if (fullState.services) setServices(fullState.services);
    if (fullState.invoices) setInvoices(fullState.invoices);

    if (fullState.settings) {
      if (fullState.settings.hourlyRate !== undefined) setHourlyRate(fullState.settings.hourlyRate);
      if (fullState.settings.fixedServices) setFixedServices(fullState.settings.fixedServices);
      if (fullState.settings.predefinedTasks) setPredefinedTasks(fullState.settings.predefinedTasks);
      if (fullState.settings.technicians) setTechnicians(fullState.settings.technicians);
      if (fullState.settings.discountLevels) setDiscountLevels(fullState.settings.discountLevels);
    }
  };

  const handleNavigateToVehicle = (vId: string) => { 
    resetAllSearches();
    const v = vehicles.find(item => item.id === vId);
    if (v) setVehicleSearch(v.licensePlate);
    setTargetVehicleId(vId); 
    setActiveView('vehicles'); 
  };

  const handleNavigateToOrder = (oId: string) => { 
    resetAllSearches();
    const o = services.find(item => item.id === oId);
    if (o) setOrderSearch(o.id);
    setTargetOrderId(oId); 
    setActiveView('orders'); 
  };

  const handleNavigateToCustomer = (cId: string) => { 
    resetAllSearches();
    const c = customers.find(item => item.id === cId);
    if (c) setCustomerSearch(c.lastName || c.companyName || '');
    setTargetCustomerId(cId); 
    setActiveView('customers'); 
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setIsMobileMenuOpen(false);
  };

  if (userSettings.enabled && !isAuthenticated) {
    return <Login settings={userSettings} onLogin={() => setIsAuthenticated(true)} />;
  }

  return (
    <div className="flex flex-col h-screen bg-slate-50 overflow-hidden text-slate-900">
      <header className="bg-white border-b border-slate-200 shrink-0 sticky top-0 z-40 shadow-sm print:hidden">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-8">
            <div className="flex items-center gap-3 group cursor-pointer" onClick={() => handleNavigate('dashboard')}>
              <div className="bg-blue-600 p-2 rounded-xl shadow-lg shadow-blue-900/20 group-hover:scale-110 transition-transform">
                <Wrench className="w-5 h-5 text-white" />
              </div>
              <h1 className="text-xl font-bold tracking-tight hidden sm:block">{companyInfo.name.split(' ')[0]} <span className="text-blue-600 font-black">{companyInfo.name.split(' ').slice(1).join(' ')}</span></h1>
            </div>
            <nav className="hidden lg:flex items-center gap-1">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => handleNavigate(item.id as AppView)}
                  className={`flex items-center gap-2 px-4 py-2.5 rounded-xl transition-all duration-200 text-sm font-bold ${
                    activeView === item.id 
                      ? 'bg-blue-50 text-blue-600' 
                      : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'
                  }`}
                >
                  <item.icon className="w-4 h-4" />
                  {item.label}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4">
            {userSettings.enabled && (
              <button 
                onClick={handleLogout}
                className="hidden lg:flex items-center gap-2 px-4 py-2.5 text-slate-500 hover:text-red-600 font-bold text-sm transition-colors"
              >
                <LogOut className="w-4 h-4" />
                Odhlásit
              </button>
            )}
            <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="lg:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-xl">
              {isMobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
            </button>
          </div>
        </div>

        {isMobileMenuOpen && (
          <div className="lg:hidden border-t border-slate-100 bg-white p-4 animate-in slide-in-from-top-4 duration-200 shadow-xl">
            <nav className="flex flex-col gap-2">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => { handleNavigate(item.id as AppView); setIsMobileMenuOpen(false); }}
                  className={`flex items-center gap-3 px-5 py-4 rounded-2xl transition-all ${
                    activeView === item.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' : 'text-slate-500 hover:bg-slate-50'
                  }`}
                >
                  <item.icon className="w-5 h-5" />
                  <span className="font-bold">{item.label}</span>
                </button>
              ))}
              {userSettings.enabled && (
                <>
                  <div className="h-px bg-slate-100 my-2"></div>
                  <button 
                    onClick={handleLogout}
                    className="flex items-center gap-3 px-5 py-4 text-red-500 font-bold"
                  >
                    <LogOut className="w-5 h-5" />
                    Odhlásit se
                  </button>
                </>
              )}
            </nav>
          </div>
        )}
      </header>

      <main className="flex-1 overflow-y-auto p-6 md:p-10 print:p-0">
        <div className="max-w-7xl mx-auto pb-10 print:max-w-none">
          {activeView === 'dashboard' && <Dashboard customers={customers} vehicles={vehicles} services={services} onNavigate={handleNavigate} onViewVehicle={handleNavigateToVehicle} onViewOrder={handleNavigateToOrder} notifSettings={notifSettings} />}
          {activeView === 'orders' && <OrderManager services={services} vehicles={vehicles} customers={customers} technicians={technicians} predefinedTasks={predefinedTasks} hourlyRate={hourlyRate} fixedServices={fixedServices} companyInfo={companyInfo} onAddService={handleAddService} onUpdateService={handleUpdateService} onDeleteService={(id) => setServices(prev => prev.filter(item => item.id !== id))} autoOpen={shouldOpenModal} onModalOpened={() => { setShouldOpenModal(false); setTargetOrderId(null); }} initialOrderId={targetOrderId} selectedPrinter={selectedPrinter} onCreateInvoice={handleCreateInvoiceFromOrder} search={orderSearch} onSearchChange={setOrderSearch} />}
          {activeView === 'invoices' && <InvoiceManager invoices={invoices} customers={customers} companyInfo={companyInfo} discountLevels={discountLevels} onDeleteInvoice={(id) => setInvoices(prev => prev.filter(inv => inv.id !== id))} onUpdateInvoiceStatus={(id, status) => setInvoices(prev => prev.map(inv => inv.id === id ? {...inv, status} : inv))} onUpdateInvoice={handleUpdateInvoice} search={invoiceSearch} onSearchChange={setInvoiceSearch} />}
          {activeView === 'customers' && <CustomerManager customers={customers} vehicles={vehicles} setCustomers={setCustomers} onAddCustomer={(c) => setCustomers([c, ...customers])} onUpdateCustomer={(c) => setCustomers(prev => prev.map(item => item.id === c.id ? c : item))} onDeleteCustomer={(id) => setCustomers(prev => prev.filter(item => item.id !== id))} onNavigateToVehicle={handleNavigateToVehicle} initialCustomerId={targetCustomerId} autoOpen={shouldOpenModal} onModalOpened={() => { setShouldOpenModal(false); setTargetCustomerId(null); }} search={customerSearch} onSearchChange={setCustomerSearch} />}
          {activeView === 'vehicles' && <VehicleManager vehicles={vehicles} customers={customers} services={services} onAddVehicle={(v) => setVehicles([v, ...vehicles])} onUpdateVehicle={(v) => setVehicles(prev => prev.map(item => item.id === v.id ? v : item))} onDeleteVehicle={(id) => setVehicles(prev => prev.filter(item => item.id !== id))} onNavigateToCustomer={handleNavigateToCustomer} onNavigateToOrder={handleNavigateToOrder} initialVehicleId={targetVehicleId} autoOpen={shouldOpenModal} onModalOpened={() => { setShouldOpenModal(false); setTargetVehicleId(null); }} search={vehicleSearch} onSearchChange={setVehicleSearch} />}
          {activeView === 'settings' && <Settings technicians={technicians} onTechniciansChange={setTechnicians} predefinedTasks={predefinedTasks} onPredefinedTasksChange={setPredefinedTasks} discountLevels={discountLevels} onDiscountLevelsChange={setDiscountLevels} hourlyRate={hourlyRate} onRateChange={setHourlyRate} fixedServices={fixedServices} onFixedServicesChange={setFixedServices} selectedPrinter={selectedPrinter} onPrinterChange={setSelectedPrinter} companyInfo={companyInfo} onCompanyChange={setCompanyInfo} notifSettings={notifSettings} onNotifSettingsChange={setNotifSettings} customers={customers} vehicles={vehicles} services={services} invoices={invoices} onRestoreData={handleRestoreData} autoBackupSettings={autoBackupSettings} onAutoBackupSettingsChange={(s) => { setAutoBackupSettings(s); localStorage.setItem('autoBackupSettings', JSON.stringify(s)); }} setDirectoryHandle={setDirectoryHandle} directoryHandle={directoryHandle} userSettings={userSettings} onUserSettingsChange={setUserSettings} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  ClipboardList, Plus, User, Car, ArrowRight, X, Check, 
  Search, Package, Printer, Trash2, Tag, FileText, AlertCircle, Eye, CheckSquare, Square, Receipt,
  MoreHorizontal, Edit3, Clock, Timer, CheckCircle2, ChevronRight
} from 'lucide-react';
import { ServiceRecord, Vehicle, Customer, PartItem, CompanyInfo, FixedService, VehicleChecklist, PredefinedTask } from '../types';

interface OrderManagerProps {
  services: ServiceRecord[];
  vehicles: Vehicle[];
  customers: Customer[];
  technicians: string[];
  predefinedTasks: PredefinedTask[];
  hourlyRate: number;
  fixedServices: FixedService[];
  companyInfo: CompanyInfo;
  onAddService: (service: ServiceRecord) => void;
  onUpdateService: (service: ServiceRecord) => void;
  onDeleteService: (orderId: string) => void;
  onCreateInvoice?: (orderId: string) => void;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  initialOrderId?: string | null;
  selectedPrinter?: string;
  search: string;
  onSearchChange: (value: string) => void;
}

const formatDate = (dateStr: string) => {
  if (!dateStr) return '---';
  const parts = dateStr.split('T')[0].split('-');
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}.${parts[1]}.${parts[0]}`;
};

const OrderManager: React.FC<OrderManagerProps> = ({ 
  services, 
  vehicles, 
  customers, 
  technicians,
  predefinedTasks,
  hourlyRate,
  fixedServices,
  companyInfo,
  onAddService,
  onUpdateService,
  onDeleteService,
  onCreateInvoice,
  autoOpen, 
  onModalOpened, 
  initialOrderId,
  search,
  onSearchChange
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrderId, setEditingOrderId] = useState<string | null>(null);
  const [isPriceListPickerOpen, setIsPriceListPickerOpen] = useState(false);
  const [isTemplatePickerOpen, setIsTemplatePickerOpen] = useState(false);
  const [deletingOrder, setDeletingOrder] = useState<ServiceRecord | null>(null);
  const [showInvoicePrompt, setShowInvoicePrompt] = useState<string | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const [formData, setFormData] = useState({
    id: '',
    vehicleId: '',
    description: '',
    parts: [] as PartItem[],
    date: new Date().toISOString().split('T')[0],
    deliveryDate: '',
    endDate: '',
    technician: technicians[0] || '',
    laborHours: 0,
    status: 'naplánováno' as ServiceRecord['status'],
    fuelLevel: '1/2' as ServiceRecord['fuelLevel'],
    mileageAtEntry: 0,
    estimatedPrice: 0,
    paymentType: 'Hotovost' as ServiceRecord['paymentType'],
    checklist: {
      rezerva: false, zvedak: false, klic: false, naradi: false, hustilka: false,
      trojuhelnik: false, lekarna: false, radio: false, reflektory: false, nosic: false
    } as VehicleChecklist
  });

  const materialCost = useMemo(() => {
    return formData.parts.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
  }, [formData.parts]);

  const calculatedCost = useMemo(() => {
    return (formData.laborHours * hourlyRate) + materialCost;
  }, [formData.laborHours, materialCost, hourlyRate]);

  useEffect(() => {
    if (autoOpen) {
      handleAddNew();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen, onModalOpened]);

  useEffect(() => {
    if (initialOrderId) {
      const order = services.find(s => s.id === initialOrderId);
      if (order) {
        handleEdit(order);
        if (onModalOpened) onModalOpened();
      }
    }
  }, [initialOrderId, services, onModalOpened]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleAddNew = () => {
    resetForm();
    setEditingOrderId(null);
    setIsModalOpen(true);
  };

  const handleEdit = (order: ServiceRecord) => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    setEditingOrderId(order.id);
    setFormData({
      id: order.id,
      vehicleId: order.vehicleId,
      description: order.description,
      parts: order.parts || [],
      date: order.date,
      deliveryDate: order.deliveryDate || '',
      endDate: order.endDate || '',
      technician: order.technician,
      laborHours: order.laborHours || 0,
      status: order.status,
      fuelLevel: order.fuelLevel || '1/2',
      mileageAtEntry: order.mileageAtEntry || (vehicle?.mileage || 0),
      estimatedPrice: order.estimatedPrice || 0,
      paymentType: order.paymentType || 'Hotovost',
      checklist: order.checklist || {
        rezerva: false, zvedak: false, klic: false, naradi: false, hustilka: false,
        trojuhelnik: false, lekarna: false, radio: false, reflektory: false, nosic: false
      }
    });
    setIsModalOpen(true);
    setOpenMenuId(null);
  };

  const generateNewId = () => {
    const now = new Date();
    const year = now.getFullYear().toString().slice(-2);
    const month = (now.getMonth() + 1).toString().padStart(2, '0');
    const prefix = `${year}/${month}/`;
    const monthlyOrders = services.filter(s => s.id.startsWith(prefix));
    const nextSequence = (monthlyOrders.length + 1).toString().padStart(3, '0');
    return `${prefix}${nextSequence}`;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalId = editingOrderId || generateNewId();
    const serviceData: ServiceRecord = {
      ...formData,
      id: finalId,
      cost: calculatedCost
    };
    if (editingOrderId) onUpdateService(serviceData);
    else onAddService(serviceData);

    setIsModalOpen(false);

    if (serviceData.status === 'hotovo' && !editingOrderId) {
      setShowInvoicePrompt(finalId);
    }

    resetForm();
  };

  const resetForm = () => {
    setFormData({
      id: '',
      vehicleId: '',
      description: '',
      parts: [],
      date: new Date().toISOString().split('T')[0],
      deliveryDate: '',
      endDate: '',
      technician: technicians[0] || '',
      laborHours: 0,
      status: 'naplánováno',
      fuelLevel: '1/2',
      mileageAtEntry: 0,
      estimatedPrice: 0,
      paymentType: 'Hotovost',
      checklist: {
        rezerva: false, zvedak: false, klic: false, naradi: false, hustilka: false,
        trojuhelnik: false, lekarna: false, radio: false, reflektory: false, nosic: false
      }
    });
  };

  const addPart = () => {
    setFormData({
      ...formData,
      parts: [...formData.parts, { id: Date.now().toString(), description: '', quantity: 1, unit: 'ks', unitPrice: 0 }]
    });
  };

  const removePart = (id: string) => {
