const PrintTemplate: React.FC<{ order: ServiceRecord, company: CompanyInfo, vehicles: Vehicle[], customers: Customer[], hourlyRate: number }> = ({ order, company, vehicles, customers, hourlyRate }) => {
  const vehicle = vehicles.find(v => v.id === order.vehicleId);
  const customer = vehicle ? customers.find(c => c.id === vehicle.customerId) : null;

  const safeName = (c: Customer | null) => {
    if (!c) return "---";
    if (c.companyName) return c.companyName.toUpperCase();
    return `${c.firstName || ''} ${c.lastName || ''}`.trim().toUpperCase() || "---";
  };

  const maxParts = 18;
  const currentPartsCount = order.parts?.length || 0;
  const fillerRowsCount = Math.max(0, maxParts - currentPartsCount);

  return (
    <div className="print-block">
      <div className="flex-1 border-[1.5pt] border-black flex flex-col">
        <div className="flex border-b-[1.5pt] border-black h-28">
          <div className="w-1/3 border-r-[1.5pt] border-black p-3">
            <p className="text-[7px] font-black uppercase mb-1">Opravna - DIČ</p>
            <p className="font-black text-[11px] uppercase leading-tight mb-1">{company.name}</p>
            <p className="font-bold text-[9px]">{company.address}</p>
            <p className="text-[7px] mt-1 font-bold">IČO: {company.ico} | DIČ: {company.dic}</p>
