export default InvoiceManager;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  ClipboardList, Plus, User, Car, ArrowRight, X, Check, 
  Search, Package, Printer, Trash2, Tag, FileText, AlertCircle, Eye, CheckSquare, Square, Receipt,
  MoreHorizontal, Edit3, Clock, Timer, CheckCircle2, ChevronRight, ChevronDown
} from 'lucide-react';
import { ServiceRecord, Vehicle, Customer, PartItem, CompanyInfo, FixedService, VehicleChecklist, PredefinedTask } from '../types';

interface OrderManagerProps {
  services: ServiceRecord[];
  vehicles: Vehicle[];
  customers: Customer[];
  technicians: string[];
  predefinedTasks: PredefinedTask[];
  hourlyRate: number;
  fixedServices: FixedService[];
  companyInfo: CompanyInfo;
  onAddService: (service: ServiceRecord) => void;
  onUpdateService: (service: ServiceRecord) => void;
  onDeleteService: (orderId: string) => void;
  onCreateInvoice?: (orderId: string) => void;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  initialOrderId?: string | null;
  selectedPrinter?: string;
  search: string;
  onSearchChange: (value: string) => void;
}

const formatDate = (dateStr: string) => {
  if (!dateStr) return '---';
  const parts = dateStr.split('T')[0].split('-');
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}.${parts[1]}.${parts[0]}`;
};

const OrderManager: React.FC<OrderManagerProps> = ({ 
  services, 
  vehicles, 
  customers, 
  technicians,
  predefinedTasks,
  hourlyRate,
  fixedServices,
  companyInfo,
  onAddService,
  onUpdateService,
  onDeleteService,
  onCreateInvoice,
  autoOpen, 
  onModalOpened, 
  initialOrderId,
  search,
  onSearchChange
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrderId, setEditingOrderId] = useState<string | null>(null);
  const [isPriceListPickerOpen, setIsPriceListPickerOpen] = useState(false);
  const [isTemplatePickerOpen, setIsTemplatePickerOpen] = useState(false);
  const [deletingOrder, setDeletingOrder] = useState<ServiceRecord | null>(null);
  const [showInvoicePrompt, setShowInvoicePrompt] = useState<string | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  // States for searchable vehicle select
  const [isVehicleDropdownOpen, setIsVehicleDropdownOpen] = useState(false);
  const [vehicleSelectSearch, setVehicleSelectSearch] = useState('');
  const vehicleDropdownRef = useRef<HTMLDivElement>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const [formData, setFormData] = useState({
    id: '',
    vehicleId: '',
    description: '',
    parts: [] as PartItem[],
    date: new Date().toISOString().split('T')[0],
    deliveryDate: '',
    endDate: '',
    technician: technicians[0] || '',
    laborHours: 0,
    status: 'naplánováno' as ServiceRecord['status'],
    fuelLevel: '1/2' as ServiceRecord['fuelLevel'],
    mileageAtEntry: 0,
    estimatedPrice: 0,
    paymentType: 'Hotovost' as ServiceRecord['paymentType'],
    checklist: {
      rezerva: false, zvedak: false, klic: false, naradi: false, hustilka: false,
      trojuhelnik: false, lekarna: false, radio: false, reflektory: false, nosic: false
    } as VehicleChecklist
  });

  const materialCost = useMemo(() => {
    return formData.parts.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
  }, [formData.parts]);

  const calculatedCost = useMemo(() => {
    return (formData.laborHours * hourlyRate) + materialCost;
  }, [formData.laborHours, materialCost, hourlyRate]);

  useEffect(() => {
    if (autoOpen) {
      handleAddNew();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen, onModalOpened]);

  useEffect(() => {
    if (initialOrderId) {
      const order = services.find(s => s.id === initialOrderId);
      if (order) {
        handleEdit(order);
        if (onModalOpened) onModalOpened();
      }
    }
  }, [initialOrderId, services, onModalOpened]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
      if (vehicleDropdownRef.current && !vehicleDropdownRef.current.contains(event.target as Node)) {
        setIsVehicleDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleAddNew = () => {
    resetForm();
    setEditingOrderId(null);
    setIsModalOpen(true);
  };

  const handleEdit = (order: ServiceRecord) => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    setEditingOrderId(order.id);
    setFormData({
      id: order.id,
      vehicleId: order.vehicleId,
      description: order.description,
      parts: order.parts || [],
      date: order.date,
      deliveryDate: order.deliveryDate || '',
      endDate: order.endDate || '',
      technician: order.technician,
      laborHours: order.laborHours || 0,
      status: order.status,
      fuelLevel: order.fuelLevel || '1/2',
      mileageAtEntry: order.mileageAtEntry || (vehicle?.mileage || 0),
      estimatedPrice: order.estimatedPrice || 0,
      paymentType: order.paymentType || 'Hotovost',
      checklist: order.checklist || {
        rezerva: false, zvedak: false, klic: false, naradi: false, hustilka: false,
        trojuhelnik: false, lekarna: false, radio: false, reflektory: false, nosic: false
      }
    });
    setIsModalOpen(true);
    setOpenMenuId(null);
  };

  const generateNewId = () => {
    const now = new Date();
    const year = now.getFullYear().toString().slice(-2);
    const month = (now.getMonth() + 1).toString().padStart(2, '0');
    const prefix = `${year}/${month}/`;
    const monthlyOrders = services.filter(s => s.id.startsWith(prefix));
    const nextSequence = (monthlyOrders.length + 1).toString().padStart(3, '0');
    return `${prefix}${nextSequence}`;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalId = editingOrderId || generateNewId();
    const serviceData: ServiceRecord = {
      ...formData,
      id: finalId,
      cost: calculatedCost
    };
    if (editingOrderId) onUpdateService(serviceData);
    else onAddService(serviceData);

    setIsModalOpen(false);

    // Nyní zobrazujeme dotaz na fakturu vždy, když je stav 'hotovo'
    if (serviceData.status === 'hotovo') {
      setShowInvoicePrompt(finalId);
    }

    resetForm();
  };

  const resetForm = () => {
    setFormData({
      id: '',
      vehicleId: '',
      description: '',
      parts: [],
      date: new Date().toISOString().split('T')[0],
      deliveryDate: '',
      endDate: '',
      technician: technicians[0] || '',
      laborHours: 0,
      status: 'naplánováno',
      fuelLevel: '1/2',
      mileageAtEntry: 0,
      estimatedPrice: 0,
      paymentType: 'Hotovost',
      checklist: {
        rezerva: false, zvedak: false, klic: false, naradi: false, hustilka: false,
        trojuhelnik: false, lekarna: false, radio: false, reflektory: false, nosic: false
      }
    });
    setVehicleSelectSearch('');
    setIsVehicleDropdownOpen(false);
  };

  const addPart = () => {
    setFormData({
      ...formData,
      parts: [...formData.parts, { id: Date.now().toString(), description: '', quantity: 1, unit: 'ks', unitPrice: 0 }]
    });
  };

  const removePart = (id: string) => {
    setFormData({ ...formData, parts: formData.parts.filter(p => p.id !== id) });
  };

  const updatePart = (id: string, field: keyof PartItem, value: any) => {
    setFormData({
      ...formData,
      parts: formData.parts.map(p => p.id === id ? { ...p, [field]: value } : p)
    });
  };

  const addFromPriceList = (item: FixedService) => {
    setFormData({
      ...formData,
      parts: [...formData.parts, { id: Date.now().toString(), description: item.name, quantity: 1, unit: 'úkon', unitPrice: item.price }]
    });
    setIsPriceListPickerOpen(false);
  };

  const addFromTemplates = (item: PredefinedTask) => {
    const currentDesc = formData.description;
    const separator = currentDesc.trim() ? '\n\n' : '';
    setFormData({
      ...formData,
      description: `${currentDesc}${separator}${item.description}`
    });
    setIsTemplatePickerOpen(false);
  };

  const toggleChecklist = (key: keyof VehicleChecklist) => {
    setFormData({
      ...formData,
      checklist: { ...formData.checklist, [key]: !formData.checklist[key] }
    });
  };

  const filteredOrders = useMemo(() => {
    return services.filter(order => {
      const vehicle = vehicles.find(v => v.id === order.vehicleId);
      const owner = customers.find(c => c.id === vehicle?.customerId);
      if (!search) return true;
      return (
        order.id.toLowerCase().includes(search.toLowerCase()) ||
        order.description.toLowerCase().includes(search.toLowerCase()) ||
        vehicle?.licensePlate.toLowerCase().includes(search.toLowerCase()) ||
        owner?.lastName.toLowerCase().includes(search.toLowerCase()) ||
        owner?.companyName?.toLowerCase().includes(search.toLowerCase())
      );
    });
  }, [services, vehicles, customers, search]);

  const filteredVehiclesForSelect = useMemo(() => {
    if (!vehicleSelectSearch) return vehicles;
    const s = vehicleSelectSearch.toLowerCase();
    return vehicles.filter(v => 
      v.licensePlate.toLowerCase().includes(s) ||
      v.make.toLowerCase().includes(s) ||
      v.model.toLowerCase().includes(s)
    );
  }, [vehicles, vehicleSelectSearch]);

  const columns = useMemo(() => ({
    waiting: filteredOrders.filter(o => o.status === 'naplánováno').sort((a, b) => a.date.localeCompare(b.date)),
    active: filteredOrders.filter(o => o.status === 'probíhá').sort((a, b) => a.date.localeCompare(b.date)),
    done: filteredOrders.filter(o => o.status === 'hotovo' || o.status === 'zrušeno').sort((a, b) => b.date.localeCompare(a.date)),
  }), [filteredOrders]);

  const currentVehicle = vehicles.find(v => v.id === formData.vehicleId);
  const currentCustomer = currentVehicle ? customers.find(c => c.id === currentVehicle.customerId) : null;

  const renderOrderCard = (order: ServiceRecord) => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    const customer = customers.find(c => c.id === vehicle?.customerId);

    return (
