}

const formatDate = (dateStr: string) => {
  if (!dateStr) return '---';
  const parts = dateStr.split('T')[0].split('-');
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}.${parts[1]}.${parts[0]}`;
};

const InvoiceManager: React.FC<InvoiceManagerProps> = ({ invoices, customers, companyInfo, discountLevels, onDeleteInvoice, onUpdateInvoiceStatus, onUpdateInvoice, search, onSearchChange }) => {
  const [selectedInvoice, setSelectedInvoice] = useState<Invoice | null>(null);
  const [deletingInvoice, setDeletingInvoice] = useState<Invoice | null>(null);

  const today = new Date().toISOString().split('T')[0];

  const filteredInvoices = useMemo(() => {
    return invoices.filter(inv => {
      const customer = customers.find(c => c.id === inv.customerId);
      const searchLower = search.toLowerCase();
      return (
        inv.id.toLowerCase().includes(searchLower) ||
        (customer?.lastName || '').toLowerCase().includes(searchLower) ||
        (customer?.companyName || '').toLowerCase().includes(searchLower) ||
        inv.vehicleInfo.toLowerCase().includes(searchLower)
      );
    });
  }, [invoices, customers, search]);

  const { unpaidInvoices, paidInvoices, totalUnpaid, totalPaid } = useMemo(() => {
    const unpaid = filteredInvoices.filter(inv => inv.status === 'neuhrazeno');
    const paid = filteredInvoices.filter(inv => inv.status === 'uhrazeno');

    return {
      unpaidInvoices: unpaid,
      paidInvoices: paid,
      totalUnpaid: unpaid.reduce((sum, inv) => sum + inv.totalInclDph, 0),
      totalPaid: paid.reduce((sum, inv) => sum + inv.totalInclDph, 0)
    };
  }, [filteredInvoices]);

  const handlePrint = () => {
    window.print();
  };

  const handleUpdateActiveInvoice = (field: keyof Invoice, value: any) => {
    if (!selectedInvoice) return;

    let updated = { ...selectedInvoice, [field]: value };

    if (field === 'paymentType') {
      if (value === 'Hotově') {
        updated.dueDate = updated.issueDate;
      } else {
        const date = new Date(updated.issueDate);
        date.setDate(date.getDate() + 14);
        updated.dueDate = date.toISOString().split('T')[0];
      }
    }

    if (field === 'discount') {
      const baseTotal = updated.items.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
      const discountedBase = baseTotal * (1 - (value / 100));
      updated.totalExclDph = discountedBase;
      updated.totalInclDph = Math.round(discountedBase * 1.21);
    }

    setSelectedInvoice(updated);
    onUpdateInvoice(updated);
  };

  const handleUpdateDueDays = (days: number) => {
    if (!selectedInvoice) return;
    const date = new Date(selectedInvoice.issueDate);
    date.setDate(date.getDate() + days);
    const updated = { ...selectedInvoice, dueDate: date.toISOString().split('T')[0] };
    setSelectedInvoice(updated);
    onUpdateInvoice(updated);
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">

      {/* Hidden Print Area - Only visible during print */}
      <div className="hidden print:block">
        {selectedInvoice && <InvoicePrintTemplate invoice={selectedInvoice} company={companyInfo} customers={customers} />}
      </div>

      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 print:hidden">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Fakturační systém</h2>
          <p className="text-slate-500 font-medium">Správa vydaných faktur a sledování plateb.</p>
        </div>

        <div className="bg-white p-4 rounded-[2rem] border border-slate-200 shadow-sm flex items-center gap-8 px-8">
          <div className="flex flex-col">
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">K úhradě celkem</span>
            <span className="text-xl font-black text-blue-600">{totalUnpaid.toLocaleString()} Kč</span>
          </div>
          <div className="w-px h-10 bg-slate-100"></div>
          <div className="flex flex-col">
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Uhrazeno celkem</span>
            <span className="text-xl font-black text-emerald-600">{totalPaid.toLocaleString()} Kč</span>
          </div>
        </div>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3 print:hidden">
        <Search className="w-5 h-5 text-slate-400" />
        <input 
          type="text" 
          placeholder="Hledat fakturu (ID, Zákazník, Vozidlo)..." 
          className="flex-1 text-sm font-medium outline-none bg-transparent"
          value={search}
          onChange={(e) => onSearchChange(e.target.value)}
        />
        {search && (
          <button onClick={() => onSearchChange('')} className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all">Zrušit filtr</button>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-0 lg:divide-x divide-slate-200 print:hidden pb-12">

        <div className="lg:pr-8 space-y-6">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
              <AlertOctagon className="w-4 h-4 text-blue-500" />
              K úhradě ({unpaidInvoices.length})
            </h3>
          </div>
          <div className="grid grid-cols-1 gap-6">
            {unpaidInvoices.map(inv => (
              <InvoiceCard 
                key={inv.id} 
                inv={inv} 
                customers={customers} 
                today={today}
                onSelect={setSelectedInvoice}
                onDelete={setDeletingInvoice}
              />
            ))}
            {unpaidInvoices.length === 0 && (
              <div className="py-12 text-center bg-slate-50/50 rounded-[2rem] border-2 border-dashed border-slate-200">
                <p className="text-slate-400 font-bold italic">Žádné faktury k úhradě.</p>
              </div>
            )}
          </div>
        </div>

        <div className="lg:pl-8 space-y-6 mt-12 lg:mt-0">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
              <CheckCircle className="w-4 h-4 text-emerald-500" />
              Uhrazeno ({paidInvoices.length})
            </h3>
          </div>
          <div className="grid grid-cols-1 gap-6">
            {paidInvoices.map(inv => (
              <InvoiceCard 
                key={inv.id} 
                inv={inv} 
                customers={customers} 
                today={today}
                onSelect={setSelectedInvoice}
                onDelete={setDeletingInvoice}
              />
            ))}
            {paidInvoices.length === 0 && (
              <div className="py-12 text-center bg-slate-50/50 rounded-[2rem] border-2 border-dashed border-slate-200">
                <p className="text-slate-400 font-bold italic">Žádné uhrazené faktury.</p>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Invoice Viewer Modal */}
      {selectedInvoice && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 print:hidden">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setSelectedInvoice(null)}></div>
          <div className="bg-white w-full max-w-6xl h-[95vh] rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden flex flex-col animate-in zoom-in-95 duration-300">
            <div className="p-6 border-b flex flex-col gap-4 bg-slate-50">
              <div className="flex justify-between items-center">
                <div className="flex items-center gap-4">
                  <FileText className="w-6 h-6 text-blue-600" />
                  <h3 className="text-xl font-black uppercase">Faktura {selectedInvoice.id}</h3>
                </div>
                <div className="flex gap-4">
                  <button 
                    onClick={() => onUpdateInvoiceStatus(selectedInvoice.id, selectedInvoice.status === 'uhrazeno' ? 'neuhrazeno' : 'uhrazeno')}
                    className={`px-6 py-3 rounded-xl font-black text-xs flex items-center gap-2 ${selectedInvoice.status === 'uhrazeno' ? 'bg-amber-100 text-amber-700' : 'bg-emerald-100 text-emerald-700'}`}
                  >
                    {selectedInvoice.status === 'uhrazeno' ? <XCircle className="w-4 h-4" /> : <CheckCircle className="w-4 h-4" />}
                    {selectedInvoice.status === 'uhrazeno' ? 'OZNAČIT JAKO NEUHRAZENO' : 'OZNAČIT JAKO UHRAZENO'}
                  </button>
                  <button 
                    onClick={handlePrint}
                    className="bg-blue-600 text-white px-8 py-3 rounded-xl font-black text-xs flex items-center gap-2 shadow-lg shadow-blue-200"
                  >
                    <Printer className="w-4 h-4" /> TISK / PDF
                  </button>
                  <button onClick={() => setSelectedInvoice(null)} className="p-2 hover:bg-slate-100 rounded-xl"><X className="w-6 h-6 text-slate-400" /></button>
                </div>
              </div>

              <div className="flex flex-wrap items-center gap-6 p-4 bg-white rounded-[2rem] border border-slate-200 shadow-sm">
                <div className="flex items-center gap-3">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Úhrada:</span>
                  <div className="flex bg-slate-100 p-1 rounded-xl">
                    <button 
                      onClick={() => handleUpdateActiveInvoice('paymentType', 'Hotově')}
                      className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${selectedInvoice.paymentType === 'Hotově' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500 hover:text-slate-700'}`}
                    >
                      <Wallet className="w-3.5 h-3.5" /> Hotově
                    </button>
                    <button 
                      onClick={() => handleUpdateActiveInvoice('paymentType', 'Převodem')}
                      className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${selectedInvoice.paymentType === 'Převodem' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500 hover:text-slate-700'}`}
                    >
                      <CreditCard className="w-3.5 h-3.5" /> Převodem
                    </button>
                  </div>
                </div>

                {selectedInvoice.paymentType === 'Převodem' && (
                  <div className="flex items-center gap-3">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Splatnost:</span>
                    <div className="flex bg-slate-100 p-1 rounded-xl">
                      {[7, 14, 31].map(days => (
                        <button 
                          key={days}
                          onClick={() => handleUpdateDueDays(days)}
                          className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${
                            Math.round((new Date(selectedInvoice.dueDate).getTime() - new Date(selectedInvoice.issueDate).getTime()) / (1000 * 3600 * 24)) === days 
                            ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500 hover:text-slate-700'
                          }`}
                        >
                          {days} d
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                <div className="flex items-center gap-3">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Sleva:</span>
                  <select 
                    value={selectedInvoice.discount || 0}
                    onChange={(e) => handleUpdateActiveInvoice('discount', parseInt(e.target.value))}
                    className="bg-slate-100 border-none rounded-xl px-4 py-2 text-xs font-bold outline-none cursor-pointer hover:bg-slate-200 transition-colors"
                  >
                    {discountLevels.map(level => (
                      <option key={level} value={level}>{level}% sleva</option>
                    ))}
                  </select>
                </div>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-12 bg-slate-100 flex justify-center custom-scrollbar">
               {/* Digital Preview of the A4 Assembly */}
               <InvoicePrintTemplate invoice={selectedInvoice} company={companyInfo} customers={customers} />
            </div>
          </div>
        </div>
      )}

      {deletingInvoice && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setDeletingInvoice(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-10 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6"><AlertCircle className="w-10 h-10" /></div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-2">Smazat fakturu?</h3>
              <p className="text-slate-500 font-medium mb-8 leading-relaxed">
                Opravdu chcete nenávratně odstranit fakturu <span className="font-bold text-slate-900">{deletingInvoice.id}</span>?
              </p>
              <div className="flex gap-3">
                <button onClick={() => setDeletingInvoice(null)} className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm uppercase">Zrušit</button>
                <button 
                  onClick={() => { onDeleteInvoice(deletingInvoice.id); setDeletingInvoice(null); }}
                  className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm uppercase shadow-lg shadow-red-600/20"
                >
                  Smazat
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      <style>{`
        @media print {
          @page {
            size: A4 portrait;
            margin: 0;
          }
          html, body {
            height: 100%;
            margin: 0 !important;
            padding: 0 !important;
            overflow: visible !important;
            background: white !important;
          }
          #root {
            display: none !important;
          }
          .print-block-invoice {
            display: block !important;
            visibility: visible !important;
            position: absolute !important;
            left: 0 !important;
