import React, { useState, useMemo } from 'react';
import { Search, Archive, ClipboardCheck, Receipt, Car, User, Clock, ChevronRight, Filter } from 'lucide-react';
import { ServiceRecord, Invoice, Vehicle, Customer } from '../types';

interface ArchiveManagerProps {
  services: ServiceRecord[];
  invoices: Invoice[];
  vehicles: Vehicle[];
  customers: Customer[];
  search: string;
  onSearchChange: (value: string) => void;
  onNavigateToOrder: (id: string) => void;
}

const formatDate = (dateStr: string) => {
  if (!dateStr) return '---';
  const parts = dateStr.split('T')[0].split('-');
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}.${parts[1]}.${parts[0]}`;
};

const ArchiveManager: React.FC<ArchiveManagerProps> = ({ 
  services, 
  invoices, 
  vehicles, 
  customers, 
  search, 
  onSearchChange,
  onNavigateToOrder 
}) => {
  const [filterType, setFilterType] = useState<'all' | 'orders' | 'invoices'>('all');

  const archivedOrders = useMemo(() => {
    return services.filter(s => s.status === 'hotovo' || s.status === 'zrušeno');
  }, [services]);

  const archivedInvoices = useMemo(() => {
    return invoices.filter(inv => inv.status === 'uhrazeno');
  }, [invoices]);

  const filteredArchive = useMemo(() => {
    let combined: any[] = [];

    if (filterType === 'all' || filterType === 'orders') {
      combined = [...combined, ...archivedOrders.map(o => ({ ...o, archiveType: 'order' }))];
    }

    if (filterType === 'all' || filterType === 'invoices') {
      combined = [...combined, ...archivedInvoices.map(inv => ({ ...inv, archiveType: 'invoice' }))];
    }

    // Sort by date descending
    combined.sort((a, b) => {
      const dateA = a.archiveType === 'order' ? a.date : a.issueDate;
      const dateB = b.archiveType === 'order' ? b.date : b.issueDate;
      return dateB.localeCompare(dateA);
    });

    if (!search) return combined;

    const s = search.toLowerCase();
    return combined.filter(item => {
      if (item.archiveType === 'order') {
        const vehicle = vehicles.find(v => v.id === item.vehicleId);
        const owner = customers.find(c => c.id === vehicle?.customerId);
        return (
          item.id.toLowerCase().includes(s) ||
          item.description.toLowerCase().includes(s) ||
          vehicle?.licensePlate.toLowerCase().includes(s) ||
          owner?.lastName.toLowerCase().includes(s) ||
          owner?.companyName?.toLowerCase().includes(s)
        );
      } else {
        const customer = customers.find(c => c.id === item.customerId);
        return (
          item.id.toLowerCase().includes(s) ||
          item.vehicleInfo.toLowerCase().includes(s) ||
          customer?.lastName.toLowerCase().includes(s) ||
          customer?.companyName?.toLowerCase().includes(s)
        );
      }
    });
  }, [archivedOrders, archivedInvoices, filterType, search, vehicles, customers]);

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div>
        <h2 className="text-2xl font-black text-slate-900 tracking-tight">Archiv historie</h2>
        <p className="text-slate-500 font-medium">Přehled dokončených zakázek a uhrazených faktur.</p>
      </div>

      <div className="flex flex-col md:flex-row gap-4 items-center">
        <div className="flex-1 w-full bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
          <Search className="w-5 h-5 text-slate-400" />
          <input 
            type="text" 
            placeholder="Hledat v archivu (ID, SPZ, Zákazník)..." 
            className="flex-1 text-sm font-medium outline-none bg-transparent"
            value={search}
            onChange={(e) => onSearchChange(e.target.value)}
          />
          {search && (
            <button onClick={() => onSearchChange('')} className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all">Zrušit filtr</button>
          )}
        </div>

        <div className="flex bg-slate-200/50 p-1.5 rounded-2xl shrink-0">
          <button 
            onClick={() => setFilterType('all')}
            className={`px-4 py-2 rounded-xl text-xs font-black transition-all ${filterType === 'all' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500'}`}
          >
            VŠE
          </button>
          <button 
            onClick={() => setFilterType('orders')}
            className={`px-4 py-2 rounded-xl text-xs font-black transition-all ${filterType === 'orders' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}
          >
            ZAKÁZKY
          </button>
          <button 
            onClick={() => setFilterType('invoices')}
            className={`px-4 py-2 rounded-xl text-xs font-black transition-all ${filterType === 'invoices' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-500'}`}
          >
            FAKTURY
          </button>
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Typ / Datum</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Identifikace</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Zákazník / Vozidlo</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Status</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Částka</th>
                <th className="px-8 py-5"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredArchive.map((item, idx) => {
                const isOrder = item.archiveType === 'order';
                const vehicle = isOrder ? vehicles.find(v => v.id === item.vehicleId) : null;
                const customer = isOrder 
                  ? (vehicle ? customers.find(c => c.id === vehicle.customerId) : null)
                  : customers.find(c => c.id === item.customerId);

                return (
                  <tr key={`${item.archiveType}-${item.id}`} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-3">
                        <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-sm ${isOrder ? 'bg-blue-50 text-blue-600' : 'bg-emerald-50 text-emerald-600'}`}>
                          {isOrder ? <ClipboardCheck className="w-5 h-5" /> : <Receipt className="w-5 h-5" />}
                        </div>
                        <div>
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{isOrder ? 'Zakázka' : 'Faktura'}</p>
                          <p className="text-xs font-bold text-slate-900">{formatDate(isOrder ? item.date : item.issueDate)}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-8 py-6">
                      <p className="text-sm font-black text-slate-900 leading-none mb-1">#{item.id}</p>
                      <p className="text-[10px] font-bold text-slate-400 font-mono tracking-tighter truncate max-w-[150px]">
                        {isOrder ? item.description : item.vehicleInfo}
                      </p>
                    </td>
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-lg bg-slate-100 flex items-center justify-center">
                           <User className="w-4 h-4 text-slate-400" />
                        </div>
                        <div>
                          <p className="text-sm font-bold text-slate-900 truncate max-w-[180px]">
                            {customer ? (customer.companyName || `${customer.firstName} ${customer.lastName}`) : '---'}
                          </p>
                          <p className="text-[9px] font-black text-blue-600 uppercase tracking-widest">
                            {isOrder ? vehicle?.licensePlate : 'Platba přijata'}
                          </p>
                        </div>
                      </div>
                    </td>
                    <td className="px-8 py-6">
                      <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest ${
                        item.status === 'hotovo' || item.status === 'uhrazeno' ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'
                      }`}>
                        <Clock className="w-3 h-3" />
                        {item.status}
                      </span>
                    </td>
                    <td className="px-8 py-6 text-right">
                      <p className="text-base font-black text-slate-900">
                        {(isOrder ? item.cost * 1.21 : item.totalInclDph).toLocaleString()} Kč
                      </p>
                      <p className="text-[8px] font-black text-slate-400 uppercase">vč. DPH</p>
                    </td>
                    <td className="px-8 py-6 text-right">
                      {isOrder && (
                        <button 
                          onClick={() => onNavigateToOrder(item.id)}
                          className="p-2.5 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all opacity-0 group-hover:opacity-100"
                        >
                          <ChevronRight className="w-5 h-5" />
                        </button>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
          {filteredArchive.length === 0 && (
            <div className="py-20 text-center flex flex-col items-center">
              <Archive className="w-16 h-16 text-slate-200 mb-4" />
              <p className="text-slate-400 font-bold italic">Žádné záznamy k zobrazení v archivu.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ArchiveManager;

