                    ))}

                    <div className="col-span-2 p-1 border-b border-black flex flex-col bg-slate-50 relative" ref={vehicleDropdownRef}>
                       <span className="text-[7px] font-black uppercase">Vozidlo (Výběr s hledáním)</span>
                       <div 
                        onClick={() => setIsVehicleDropdownOpen(!isVehicleDropdownOpen)}
                        className="bg-transparent font-black text-xs outline-none cursor-pointer text-blue-800 flex items-center justify-between pr-2 min-h-[1.25rem]"
                       >
                         <span className="truncate">{currentVehicle ? `${currentVehicle.licensePlate} - ${currentVehicle.make} ${currentVehicle.model}` : 'Vyberte vozidlo...'}</span>
                         <ChevronDown className="w-3 h-3 text-slate-400 shrink-0" />
                       </div>

                       {isVehicleDropdownOpen && (
                         <div className="absolute top-full left-0 right-0 bg-white border border-black z-[130] shadow-xl mt-1 rounded-lg overflow-hidden flex flex-col max-h-64 animate-in fade-in slide-in-from-top-2 duration-200">
                           <div className="p-2 border-b border-slate-100 bg-slate-50 flex items-center gap-2">
                             <Search className="w-3.5 h-3.5 text-slate-400" />
                             <input 
