                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Nájezd</p>
                  <p className="text-sm font-bold text-slate-900">{selectedVehicle.mileage.toLocaleString()} km</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">STK Expirace</p>
                  <p className="text-sm font-bold text-slate-900">{formatDate(selectedVehicle.stkExpirationDate)}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Příští servis</p>
                  <p className="text-sm font-bold text-slate-900">{formatDate(selectedVehicle.nextServiceDate)}</p>
                </div>
                <div className="col-span-2 space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Vlastník</p>
                  <p 
                    className="text-sm font-bold text-blue-600 cursor-pointer hover:underline"
                    onClick={() => { onNavigateToCustomer(selectedVehicle.customerId); setSelectedVehicle(null); }}
                  >
                    {customers.find(c => c.id === selectedVehicle.customerId)?.companyName || 
                     `${customers.find(c => c.id === selectedVehicle.customerId)?.firstName} ${customers.find(c => c.id === selectedVehicle.customerId)?.lastName}`}
                  </p>
                </div>
              </div>
              <button 
                onClick={() => setSelectedVehicle(null)}
                className="w-full bg-slate-900 text-white font-black py-4 rounded-2xl transition-all"
              >
                ZAVŘÍT
              </button>
            </div>
          </div>
        </div>
      )}

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: #f1f5f9;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #cbd5e1;
          border-radius: 10px;
        }
      `}</style>
    </div>
  );
};

