const INITIAL_PREDEFINED_TASKS: PredefinedTask[] = [
  { id: 'pt1', label: 'Výměna oleje', description: 'Výměna motorového oleje a olejového filtru.' },
  { id: 'pt2', label: 'Kontrola brzd', description: 'Kontrola stavu brzdových destiček, kotoučů a brzdové kapaliny.' },
  { id: 'pt3', label: 'Diagnostika motoru', description: 'Kompletní diagnostika elektronických systémů motoru.' },
