import React, { useState, useMemo } from 'react';
import { Search, Archive, ClipboardCheck, Receipt, Car, User, Clock, ChevronRight, Filter, Calendar, Eye, X, Printer } from 'lucide-react';
import { ServiceRecord, Invoice, Vehicle, Customer, CompanyInfo } from '../types';
import { PrintTemplate } from './OrderManager';
import { InvoicePrintTemplate } from './InvoiceManager';

interface ArchiveManagerProps {
  services: ServiceRecord[];
  invoices: Invoice[];
  vehicles: Vehicle[];
  customers: Customer[];
  companyInfo: CompanyInfo;
  hourlyRate: number;
  search: string;
  onSearchChange: (value: string) => void;
  onNavigateToOrder: (id: string) => void;
}

const MONTHS = [
  'Leden', 'Únor', 'Březen', 'Duben', 'Květen', 'Červen',
  'Červenec', 'Srpen', 'Září', 'Říjen', 'Listopad', 'Prosinec'
];

const formatDate = (dateStr: string) => {
  if (!dateStr) return '---';
  const parts = dateStr.split('T')[0].split('-');
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}.${parts[1]}.${parts[0]}`;
};

const ArchiveManager: React.FC<ArchiveManagerProps> = ({ 
  services, 
  invoices, 
  vehicles, 
  customers, 
  companyInfo,
  hourlyRate,
  search, 
  onSearchChange,
  onNavigateToOrder 
}) => {
  const [filterType, setFilterType] = useState<'all' | 'orders' | 'invoices'>('all');
  const [selectedYear, setSelectedYear] = useState<number | null>(new Date().getFullYear());
  const [selectedMonth, setSelectedMonth] = useState<number | null>(null); // 0-11, null for all
  const [previewOrder, setPreviewOrder] = useState<ServiceRecord | null>(null);
  const [previewInvoice, setPreviewInvoice] = useState<Invoice | null>(null);

  const archivedOrders = useMemo(() => {
    return services.filter(s => s.status === 'hotovo' || s.status === 'zrušeno');
  }, [services]);

  const archivedInvoices = useMemo(() => {
    return invoices.filter(inv => inv.archived === true);
  }, [invoices]);

  // Dynamically get available years from data
  const availableYears = useMemo(() => {
    const years = new Set<number>();
    years.add(new Date().getFullYear());
    archivedOrders.forEach(o => years.add(new Date(o.date).getFullYear()));
    archivedInvoices.forEach(i => years.add(new Date(i.issueDate).getFullYear()));
    return Array.from(years).sort((a, b) => b - a);
  }, [archivedOrders, archivedInvoices]);

  const filteredArchive = useMemo(() => {
    let combined: any[] = [];

    if (filterType === 'all' || filterType === 'orders') {
      combined = [...combined, ...archivedOrders.map(o => ({ ...o, archiveType: 'order' }))];
    }

    if (filterType === 'all' || filterType === 'invoices') {
      combined = [...combined, ...archivedInvoices.map(inv => ({ ...inv, archiveType: 'invoice' }))];
    }

    // Date filtering logic
    combined = combined.filter(item => {
      const dateStr = item.archiveType === 'order' ? item.date : item.issueDate;
      const d = new Date(dateStr);
      const yearMatch = selectedYear === null || d.getFullYear() === selectedYear;
      const monthMatch = selectedMonth === null || d.getMonth() === selectedMonth;
      return yearMatch && monthMatch;
    });

    // Sort by date descending
    combined.sort((a, b) => {
      const dateA = a.archiveType === 'order' ? a.date : a.issueDate;
      const dateB = b.archiveType === 'order' ? b.date : b.issueDate;
      return dateB.localeCompare(dateA);
    });

    if (!search) return combined;

    const s = search.toLowerCase();
    return combined.filter(item => {
      if (item.archiveType === 'order') {
        const vehicle = vehicles.find(v => v.id === item.vehicleId);
        const owner = customers.find(c => c.id === vehicle?.customerId);
        return (
          item.id.toLowerCase().includes(s) ||
          item.description.toLowerCase().includes(s) ||
          vehicle?.licensePlate.toLowerCase().includes(s) ||
          owner?.lastName.toLowerCase().includes(s) ||
          owner?.companyName?.toLowerCase().includes(s)
        );
      } else {
        const customer = customers.find(c => c.id === item.customerId);
        return (
          item.id.toLowerCase().includes(s) ||
          item.vehicleInfo.toLowerCase().includes(s) ||
          customer?.lastName.toLowerCase().includes(s) ||
          customer?.companyName?.toLowerCase().includes(s)
        );
      }
    });
  }, [archivedOrders, archivedInvoices, filterType, search, vehicles, customers, selectedYear, selectedMonth]);

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">

      {/* Hidden print templates for Archive */}
      <div className="hidden print:block">
        {previewOrder && <PrintTemplate order={previewOrder} company={companyInfo} vehicles={vehicles} customers={customers} hourlyRate={hourlyRate} />}
        {previewInvoice && <InvoicePrintTemplate invoice={previewInvoice} company={companyInfo} customers={customers} />}
      </div>

      <div className="print:hidden">
        <h2 className="text-2xl font-black text-slate-900 tracking-tight">Archiv historie</h2>
        <p className="text-slate-500 font-medium">Přehled dokončených zakázek a archivovaných dokladů.</p>
      </div>

      {/* Time Filtering Bar */}
      <div className="bg-white p-4 rounded-[2rem] border border-slate-200 shadow-sm space-y-4 print:hidden">
        <div className="flex items-center gap-4">
          <div className="w-10 h-10 rounded-xl bg-blue-50 flex items-center justify-center shrink-0">
            <Calendar className="w-5 h-5 text-blue-600" />
          </div>
          <div className="flex-1 overflow-x-auto custom-scrollbar-h">
            {/* Year Row */}
            <div className="flex gap-2 pb-2">
              <button 
                onClick={() => setSelectedYear(null)}
                className={`px-4 py-1.5 rounded-lg text-xs font-black transition-all shrink-0 ${selectedYear === null ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'bg-slate-50 text-slate-500 hover:bg-slate-100'}`}
              >
                VŠE
              </button>
              {availableYears.map(year => (
                <button 
                  key={year}
                  onClick={() => setSelectedYear(year)}
                  className={`px-4 py-1.5 rounded-lg text-xs font-black transition-all shrink-0 ${selectedYear === year ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'bg-slate-50 text-slate-500 hover:bg-slate-100'}`}
                >
                  {year}
                </button>
              ))}
            </div>
            {/* Month Row */}
            <div className="flex gap-2">
              <button 
                onClick={() => setSelectedMonth(null)}
                className={`px-4 py-1.5 rounded-lg text-xs font-black transition-all shrink-0 ${selectedMonth === null ? 'bg-slate-900 text-white shadow-lg' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}
              >
                CELÝ ROK
              </button>
              {MONTHS.map((month, idx) => (
                <button 
                  key={month}
                  onClick={() => setSelectedMonth(idx)}
                  className={`px-4 py-1.5 rounded-lg text-xs font-black transition-all shrink-0 ${selectedMonth === idx ? 'bg-blue-500 text-white shadow-lg shadow-blue-100' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}
                >
                  {month.toUpperCase()}
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>

      <div className="flex flex-col md:flex-row gap-4 items-center print:hidden">
        <div className="flex-1 w-full bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
          <Search className="w-5 h-5 text-slate-400" />
          <input 
            type="text" 
            placeholder="Hledat v archivu (ID, SPZ, Zákazník)..." 
            className="flex-1 text-sm font-medium outline-none bg-transparent"
            value={search}
            onChange={(e) => onSearchChange(e.target.value)}
          />
          {search && (
            <button onClick={() => onSearchChange('')} className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all">Zrušit filtr</button>
          )}
        </div>

        <div className="flex bg-slate-200/50 p-1.5 rounded-2xl shrink-0">
          <button 
            onClick={() => setFilterType('all')}
            className={`px-4 py-2 rounded-xl text-xs font-black transition-all ${filterType === 'all' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500'}`}
          >
            VŠE
          </button>
          <button 
            onClick={() => setFilterType('orders')}
            className={`px-4 py-2 rounded-xl text-xs font-black transition-all ${filterType === 'orders' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}
          >
            ZAKÁZKY
          </button>
          <button 
            onClick={() => setFilterType('invoices')}
            className={`px-4 py-2 rounded-xl text-xs font-black transition-all ${filterType === 'invoices' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-500'}`}
          >
            FAKTURY
          </button>
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden print:hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Typ / Datum</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Identifikace</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Zákazník / Vozidlo</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Status</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Částka</th>
                <th className="px-8 py-5"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredArchive.map((item, idx) => {
                const isOrder = item.archiveType === 'order';
                const vehicle = isOrder ? vehicles.find(v => v.id === item.vehicleId) : null;
                const customer = isOrder 
                  ? (vehicle ? customers.find(c => c.id === vehicle.customerId) : null)
                  : customers.find(c => c.id === item.customerId);

                return (
                  <tr key={`${item.archiveType}-${item.id}`} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-3">
                        <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-sm ${isOrder ? 'bg-blue-50 text-blue-600' : 'bg-emerald-50 text-emerald-600'}`}>
                          {isOrder ? <ClipboardCheck className="w-5 h-5" /> : <Receipt className="w-5 h-5" />}
                        </div>
                        <div>
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{isOrder ? 'Zakázka' : 'Faktura'}</p>
                          <p className="text-xs font-bold text-slate-900">{formatDate(isOrder ? item.date : item.issueDate)}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-8 py-6">
                      <p className="text-sm font-black text-slate-900 leading-none mb-1">#{item.id}</p>
                      <p className="text-[10px] font-bold text-slate-400 font-mono tracking-tighter truncate max-w-[150px]">
                        {isOrder ? item.description : item.vehicleInfo}
                      </p>
                    </td>
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-lg bg-slate-100 flex items-center justify-center">
                           <User className="w-4 h-4 text-slate-400" />
                        </div>
                        <div>
                          <p className="text-sm font-bold text-slate-900 truncate max-w-[180px]">
                            {customer ? (customer.companyName || `${customer.firstName} ${customer.lastName}`) : '---'}
                          </p>
                          <p className="text-[9px] font-black text-blue-600 uppercase tracking-widest">
                            {isOrder ? vehicle?.licensePlate : 'Platba přijata'}
                          </p>
                        </div>
                      </div>
                    </td>
                    <td className="px-8 py-6">
                      <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest ${
                        item.status === 'hotovo' || item.status === 'uhrazeno' ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'
                      }`}>
                        <Clock className="w-3 h-3" />
                        {item.status}
                      </span>
                    </td>
                    <td className="px-8 py-6 text-right">
                      <p className="text-base font-black text-slate-900">
                        {(isOrder ? item.cost * 1.21 : item.totalInclDph).toLocaleString()} Kč
                      </p>
                      <p className="text-[8px] font-black text-slate-400 uppercase">vč. DPH</p>
                    </td>
                    <td className="px-8 py-6 text-right">
                      <div className="flex items-center justify-end gap-2">
                        <button 
                          onClick={() => {
                            if (isOrder) setPreviewOrder(item);
                            else setPreviewInvoice(item);
                          }}
                          className="p-2.5 text-slate-400 hover:text-slate-900 hover:bg-slate-100 rounded-xl transition-all"
                          title="Náhled dokumentu"
                        >
                          <Eye className="w-5 h-5" />
                        </button>
                        {isOrder && (
                          <button 
                            onClick={() => onNavigateToOrder(item.id)}
                            className="p-2.5 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all"
                            title="Upravit / Detail"
                          >
                            <ChevronRight className="w-5 h-5" />
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
          {filteredArchive.length === 0 && (
            <div className="py-20 text-center flex flex-col items-center">
              <Archive className="w-16 h-16 text-slate-200 mb-4" />
              <p className="text-slate-400 font-bold italic">Žádné záznamy k zobrazení v archivu.</p>
            </div>
          )}
        </div>
      </div>

      {/* Preview Modals */}
      {(previewOrder || previewInvoice) && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 print:hidden">
          <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md" onClick={() => { setPreviewOrder(null); setPreviewInvoice(null); }}></div>
          <div className="bg-white w-full max-w-5xl h-[90vh] rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden flex flex-col animate-in zoom-in-95 duration-300">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50 shrink-0">
               <div className="flex items-center gap-4">
                  <div className="bg-blue-600 p-2 rounded-xl text-white">
                    {previewOrder ? <ClipboardCheck className="w-6 h-6" /> : <Receipt className="w-6 h-6" />}
                  </div>
                  <div>
                    <h3 className="text-xl font-black uppercase tracking-tight">Náhled dokumentu</h3>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-0.5">#{previewOrder?.id || previewInvoice?.id}</p>
                  </div>
               </div>
               <div className="flex gap-4">
                  <button onClick={handlePrint} className="bg-slate-900 text-white px-6 py-3 rounded-xl font-black text-sm flex items-center gap-2 hover:bg-slate-800">
                    <Printer className="w-5 h-5" /> TISK / PDF
                  </button>
                  <button onClick={() => { setPreviewOrder(null); setPreviewInvoice(null); }} className="p-2 hover:bg-slate-200 rounded-xl">
                    <X className="w-6 h-6 text-slate-400" />
