          >
            Zrušit filtr
          </button>
        )}
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8 pb-12 print:hidden min-h-[600px]">
        <div className="space-y-6">
          <h3 className="text-sm font-black text-slate-600 uppercase tracking-widest px-2">K VYŘÍZENÍ</h3>
          <div className="space-y-4">{columns.waiting.map(renderOrderCard)}</div>
        </div>
        <div className="space-y-6">
          <h3 className="text-sm font-black text-amber-700 uppercase tracking-widest px-2">PROBÍHÁ</h3>
          <div className="space-y-4">{columns.active.map(renderOrderCard)}</div>
        </div>
        <div className="space-y-6">
          <h3 className="text-sm font-black text-emerald-700 uppercase tracking-widest px-2">HOTOVO</h3>
          <div className="space-y-4">{columns.done.map(renderOrderCard)}</div>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 print:hidden">
          <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white w-full max-w-[1100px] h-[95vh] rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50 shrink-0">
              <div className="flex items-center gap-4">
                <div className="bg-blue-600 p-2 rounded-xl text-white"><FileText className="w-6 h-6" /></div>
                <h3 className="text-xl font-black tracking-tight uppercase">Editace Zakázkového Listu</h3>
              </div>
              <div className="flex gap-4">
                <button type="button" onClick={() => window.print()} className="bg-slate-100 text-slate-700 px-6 py-3 rounded-xl font-black text-sm flex items-center gap-2 hover:bg-slate-200"><Printer className="w-5 h-5" /> TISKNOUT</button>
                <button onClick={handleSubmit} className="bg-blue-600 text-white px-8 py-3 rounded-xl font-black text-sm flex items-center gap-2 shadow-lg hover:bg-blue-700"><Check className="w-5 h-5" /> ULOŽIT ZAKÁZKU</button>
                <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-slate-100 rounded-xl"><X className="w-6 h-6 text-slate-400" /></button>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto p-12 bg-slate-200/50 flex justify-center custom-scrollbar">
              <div className="bg-white shadow-2xl p-10 font-sans text-black border-[1px] border-slate-300 w-full max-w-[250mm] min-h-[297mm] h-fit">
                <PrintTemplate 
                  order={{...formData, id: editingOrderId || 'NÁVRH', cost: calculatedCost}} 
                  company={companyInfo} 
                  vehicles={vehicles} 
                  customers={customers} 
                  hourlyRate={hourlyRate}
                  isEditable={true}
                  onUpdatePart={updatePart}
                  onRemovePart={removePart}
                  onAddPart={addPart}
                  onUpdateOrder={updateOrderField}
                  onOpenPriceList={() => setIsPriceListPickerOpen(true)}
                  onOpenTemplates={() => setIsTemplatePickerOpen(true)}
                  fixedServices={fixedServices}
                  onAddFromPriceList={addFromPriceList}
                />
              </div>
            </div>
          </div>
        </div>
      )}

      {isPriceListPickerOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsPriceListPickerOpen(false)}></div>
          <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-blue-600 p-6 text-white flex justify-between items-center">
              <h3 className="text-xl font-black uppercase">Vybrat z ceníku</h3>
              <button onClick={() => setIsPriceListPickerOpen(false)} className="p-2 hover:bg-white/10 rounded-xl"><X className="w-5 h-5" /></button>
            </div>
            <div className="p-6 max-h-[60vh] overflow-y-auto custom-scrollbar space-y-2">
              {fixedServices.map(item => (
                <button key={item.id} onClick={() => addFromPriceList(item)} className="w-full text-left p-4 rounded-xl border border-slate-100 hover:bg-blue-50 transition-colors group flex justify-between items-center">
