          <div className="text-[10px] font-bold uppercase leading-tight">
            {company.name}
            <br />
            {company.address}
            <br />
            DIČ: {company.dic}
          </div>
        </div>
        <div className="flex flex-col items-center justify-center bg-gray-100 p-2 min-h-[120px]">
