             Termín dokončení: 
             {isEditable ? (
               <input 
                 type="date" 
                 className="ml-1 bg-blue-50/50 outline-none font-bold text-[10px] px-1 rounded" 
                 value={order.deliveryDate} 
                 onChange={(e) => onUpdateOrder?.('deliveryDate', e.target.value)} 
               />
             ) : (
               <span className="font-bold">{formatDate(order.deliveryDate || '')}</span>
             )}
          </div>
          <div className="p-1.5 flex-1"></div>
        </div>
