            {isEditable && (
              <button 
                type="button" 
                onClick={onOpenTemplates} 
                title="Přidat šablonu" 
                className="absolute right-1 p-0.5 bg-blue-600 text-white rounded hover:bg-blue-700 print:hidden"
              >
                <Layout className="w-3 h-3" />
              </button>
            )}
