        </div>
      </div>

      <div className="mt-4 flex justify-between text-[7px] font-bold uppercase opacity-50">
        <span>71 00 033</span>
        <span>{new Date().toLocaleDateString('cs-CZ')}</span>
        <span>TYPOS KLATOVY 0738 C</span>
      </div>
    </div>
  );
};

export default OrderManager;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  ClipboardList, Plus, User, Car, ArrowRight, X, Check, 
  Search, Package, Printer, Trash2, Tag, FileText, AlertCircle, Eye, CheckSquare, Square, Receipt,
  MoreHorizontal, Edit3, Clock, Timer, CheckCircle2, ChevronRight, ChevronDown, ListPlus, Calculator, Layout
} from 'lucide-react';
import { ServiceRecord, Vehicle, Customer, PartItem, CompanyInfo, FixedService, VehicleChecklist, PredefinedTask, Invoice } from '../types';

interface OrderManagerProps {
  services: ServiceRecord[];
  vehicles: Vehicle[];
  customers: Customer[];
  invoices: Invoice[];
  technicians: string[];
  predefinedTasks: PredefinedTask[];
  hourlyRate: number;
  fixedServices: FixedService[];
  companyInfo: CompanyInfo;
  onAddService: (service: ServiceRecord) => void;
  onUpdateService: (service: ServiceRecord) => void;
  onDeleteService: (orderId: string) => void;
  onCreateInvoice?: (orderId: string) => void;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  initialOrderId?: string | null;
  selectedPrinter?: string;
  search: string;
  onSearchChange: (value: string) => void;
}

const formatDate = (dateStr: string) => {
  if (!dateStr) return '---';
  const parts = dateStr.split('T')[0].split('-');
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}.${parts[1]}.${parts[0]}`;
};

const OrderManager: React.FC<OrderManagerProps> = ({ 
  services, 
  vehicles, 
  customers,
  invoices,
  technicians,
  predefinedTasks,
  hourlyRate,
  fixedServices,
  companyInfo,
  onAddService,
  onUpdateService,
  onDeleteService,
  onCreateInvoice,
  autoOpen, 
  onModalOpened, 
  initialOrderId,
  search,
  onSearchChange
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrderId, setEditingOrderId] = useState<string | null>(null);
  const [isPriceListPickerOpen, setIsPriceListPickerOpen] = useState(false);
  const [isTemplatePickerOpen, setIsTemplatePickerOpen] = useState(false);
  const [deletingOrder, setDeletingOrder] = useState<ServiceRecord | null>(null);
  const [showInvoicePrompt, setShowInvoicePrompt] = useState<string | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const [formData, setFormData] = useState({
    id: '',
    vehicleId: '',
    description: '',
    parts: [] as PartItem[],
    date: new Date().toISOString().split('T')[0],
    deliveryDate: '',
    endDate: '',
    technician: technicians[0] || '',
    laborHours: 0,
    status: 'naplánováno' as ServiceRecord['status'],
    fuelLevel: '1/2' as ServiceRecord['fuelLevel'],
    mileageAtEntry: 0,
    estimatedPrice: 0,
    paymentType: 'Hotovost' as ServiceRecord['paymentType'],
    checklist: {
      rezerva: false, zvedak: false, klic: false, bezp_klic: false,
      trojuhelnik: false, lekarna: false, lepeni: false
    } as VehicleChecklist
  });

  const materialCost = useMemo(() => {
    return formData.parts.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
  }, [formData.parts]);

  const calculatedCost = useMemo(() => {
    return (formData.laborHours * hourlyRate) + materialCost;
  }, [formData.laborHours, materialCost, hourlyRate]);

  useEffect(() => {
    if (autoOpen) {
      handleAddNew();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen, onModalOpened]);

  useEffect(() => {
    if (initialOrderId) {
      const order = services.find(s => s.id === initialOrderId);
      if (order) {
        handleEdit(order);
        if (onModalOpened) onModalOpened();
      }
    }
  }, [initialOrderId, services, onModalOpened]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleAddNew = () => {
    resetForm();
    setEditingOrderId(null);
    setIsModalOpen(true);
  };

  const handleEdit = (order: ServiceRecord) => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    setEditingOrderId(order.id);
    setFormData({
      id: order.id,
      vehicleId: order.vehicleId,
      description: order.description,
      parts: order.parts || [],
      date: order.date,
      deliveryDate: order.deliveryDate || '',
      endDate: order.endDate || '',
      technician: order.technician,
      laborHours: order.laborHours || 0,
      status: order.status,
      fuelLevel: order.fuelLevel || '1/2',
      mileageAtEntry: order.mileageAtEntry || (vehicle?.mileage || 0),
      estimatedPrice: order.estimatedPrice || 0,
      paymentType: order.paymentType || 'Hotovost',
      checklist: order.checklist || {
        rezerva: false, zvedak: false, klic: false, bezp_klic: false,
        trojuhelnik: false, lekarna: false, lepeni: false
      }
    });
    setIsModalOpen(true);
    setOpenMenuId(null);
  };

  const generateNewId = () => {
    const now = new Date();
    const year = now.getFullYear().toString().slice(-2);
    const month = (now.getMonth() + 1).toString().padStart(2, '0');
    const prefix = `${year}/${month}/`;
    const monthlyOrders = services.filter(s => s.id.startsWith(prefix));
    const nextSequence = (monthlyOrders.length + 1).toString().padStart(3, '0');
    return `${prefix}${nextSequence}`;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalId = editingOrderId || generateNewId();
    const serviceData: ServiceRecord = {
      ...formData,
      id: finalId,
      cost: calculatedCost
    };
    if (editingOrderId) onUpdateService(serviceData);
    else onAddService(serviceData);
    setIsModalOpen(false);
    if (serviceData.status === 'hotovo') setShowInvoicePrompt(finalId);
    resetForm();
  };

  const resetForm = () => {
    setFormData({
      id: '', vehicleId: '', description: '', parts: [],
      date: new Date().toISOString().split('T')[0], deliveryDate: '', endDate: '',
      technician: technicians[0] || '', laborHours: 0, status: 'naplánováno',
      fuelLevel: '1/2', mileageAtEntry: 0, estimatedPrice: 0, paymentType: 'Hotovost',
      checklist: {
        rezerva: false, zvedak: false, klic: false, bezp_klic: false,
        trojuhelnik: false, lekarna: false, lepeni: false
      }
    });
  };

  const addPart = () => {
    setFormData({
      ...formData,
      parts: [...formData.parts, { id: Date.now().toString(), description: '', quantity: 1, unit: 'ks', unitPrice: 0 }]
    });
  };

  const removePart = (id: string) => {
    setFormData({ ...formData, parts: formData.parts.filter(p => p.id !== id) });
  };

  const updatePart = (id: string, field: keyof PartItem, value: any) => {
    setFormData({
      ...formData,
      parts: formData.parts.map(p => p.id === id ? { ...p, [field]: value } : p)
    });
  };

  const updateOrderField = (field: string, value: any) => {
    if (field === 'vehicleId') {
      const selectedVeh = vehicles.find(v => v.id === value);
      setFormData({
        ...formData,
        vehicleId: value,
        mileageAtEntry: selectedVeh ? selectedVeh.mileage : formData.mileageAtEntry
      });
    } else {
      setFormData({ ...formData, [field]: value });
    }
  };

  const addFromPriceList = (item: FixedService) => {
    setFormData({
      ...formData,
      parts: [...formData.parts, { id: Date.now().toString(), description: item.name, quantity: 1, unit: 'ks', unitPrice: item.price }]
    });
    setIsPriceListPickerOpen(false);
  };

  const addFromTemplates = (item: PredefinedTask) => {
    const currentDesc = formData.description;
    const separator = currentDesc.trim() ? '\n\n' : '';
    setFormData({ ...formData, description: `${currentDesc}${separator}${item.description}` });
    setIsTemplatePickerOpen(false);
  };

  const filteredOrders = useMemo(() => {
    return services.filter(order => {
      const relatedInvoice = invoices.find(inv => inv.orderId === order.id);
      if (relatedInvoice?.status === 'uhrazeno' && (order.status === 'hotovo' || order.status === 'zrušeno')) {
        return false;
      }
      const vehicle = vehicles.find(v => v.id === order.vehicleId);
      const owner = customers.find(c => c.id === vehicle?.customerId);
      if (!search) return true;
      return (
        order.id.toLowerCase().includes(search.toLowerCase()) ||
        order.description.toLowerCase().includes(search.toLowerCase()) ||
        vehicle?.licensePlate.toLowerCase().includes(search.toLowerCase()) ||
        owner?.lastName.toLowerCase().includes(search.toLowerCase()) ||
        owner?.companyName?.toLowerCase().includes(search.toLowerCase())
      );
    });
  }, [services, vehicles, customers, invoices, search]);

  const columns = useMemo(() => ({
    waiting: filteredOrders.filter(o => o.status === 'naplánováno').sort((a, b) => a.date.localeCompare(b.date)),
    active: filteredOrders.filter(o => o.status === 'probíhá').sort((a, b) => a.date.localeCompare(b.date)),
    done: filteredOrders.filter(o => o.status === 'hotovo' || o.status === 'zrušeno').sort((a, b) => b.date.localeCompare(a.date)),
  }), [filteredOrders]);

  const renderOrderCard = (order: ServiceRecord) => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    const customer = customers.find(c => c.id === vehicle?.customerId);
    return (
      <div key={order.id} className="bg-white rounded-3xl border border-slate-100 p-6 shadow-sm hover:shadow-xl transition-all group relative animate-in fade-in zoom-in-95 duration-300">
        <div className="absolute top-0 right-0 p-4">
          <div className="relative">
            <button 
              onClick={() => setOpenMenuId(openMenuId === order.id ? null : order.id)}
              className={`p-2 rounded-xl transition-all ${openMenuId === order.id ? 'bg-slate-100 text-slate-900' : 'text-slate-300 hover:text-slate-900'}`}
            >
              <MoreHorizontal className="w-6 h-6" />
            </button>
            {openMenuId === order.id && (
              <div ref={menuRef} className="absolute top-12 right-0 w-48 bg-white rounded-2xl shadow-2xl border border-slate-100 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200">
                <button onClick={() => handleEdit(order)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-sm font-bold">
                  <Edit3 className="w-4 h-4 text-slate-400" /> Upravit kartu
                </button>
                {order.status === 'hotovo' && onCreateInvoice && (
                  <button onClick={() => { onCreateInvoice(order.id); setOpenMenuId(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-blue-50 text-blue-600 transition-colors text-sm font-bold">
                    <Receipt className="w-4 h-4" /> Vystavit fakturu
                  </button>
                )}
                <button onClick={() => { setDeletingOrder(order); setOpenMenuId(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold">
                  <Trash2 className="w-4 h-4" /> Smazat zakázku
                </button>
              </div>
            )}
          </div>
        </div>
        <div className="flex items-center gap-5 mb-5">
          <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-white shadow-lg transition-transform group-hover:scale-105 ${
            order.status === 'hotovo' ? 'bg-emerald-500 shadow-emerald-500/20' : 
            order.status === 'probíhá' ? 'bg-amber-500 shadow-amber-500/20' : 
            'bg-blue-600 shadow-blue-600/20'
          }`}>
            <ClipboardList className="w-7 h-7" />
          </div>
          <div>
            <h3 className="text-base font-black text-slate-900 leading-tight">#{order.id}</h3>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">{formatDate(order.date)}</p>
          </div>
        </div>
        <div className="space-y-3 pt-4 border-t border-slate-50">
          <div className="flex items-center gap-3 text-slate-600">
            <div className="p-2 bg-slate-50 rounded-lg"><Car className="w-4 h-4" /></div>
            <div className="min-w-0">
              <p className="text-xs font-bold text-slate-900 truncate">{vehicle ? `${vehicle.make} ${vehicle.model}` : 'Neznámý vůz'}</p>
              <p className="text-[9px] font-mono font-bold text-blue-600 uppercase">{vehicle?.licensePlate || '---'}</p>
            </div>
          </div>
          <div className="flex items-center gap-3 text-slate-600">
            <div className="p-2 bg-slate-50 rounded-lg"><User className="w-4 h-4" /></div>
            <span className="text-xs font-bold text-slate-700 truncate">
              {customer ? (customer.companyName || `${customer.firstName} ${customer.lastName}`) : 'Bez zákazníka'}
            </span>
          </div>
        </div>
        <div className="mt-6 space-y-3">
          <div className="flex items-center justify-between bg-slate-50 p-3 rounded-2xl">
            <div className="flex flex-col">
              <span className="text-[8px] font-black text-slate-400 uppercase">Celkem s DPH</span>
              <span className="text-sm font-black text-slate-900">{Math.round(order.cost * 1.21).toLocaleString()} Kč</span>
            </div>
            <select 
              value={order.status}
              onChange={(e) => onUpdateService({ ...order, status: e.target.value as any })}
              className={`text-[9px] font-black uppercase px-3 py-1 rounded-lg border outline-none cursor-pointer transition-all appearance-none text-center min-w-[100px] hover:scale-105 active:scale-95 ${
                order.status === 'hotovo' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' :
                order.status === 'probíhá' ? 'bg-amber-50 text-amber-600 border-amber-100' :
                order.status === 'zrušeno' ? 'bg-red-50 text-red-600 border-red-100' :
                'bg-blue-50 text-blue-600 border-blue-100'
              }`}
            >
              <option value="naplánováno">Naplánováno</option>
              <option value="probíhá">Probíhá</option>
              <option value="hotovo">Hotovo</option>
              <option value="zrušeno">Zrušeno</option>
            </select>
          </div>
          <button onClick={() => handleEdit(order)} className="w-full py-3 bg-slate-100 text-slate-900 rounded-xl font-bold text-[10px] hover:bg-slate-200 transition-all uppercase tracking-widest flex items-center justify-center gap-2 group/btn">
            <Eye className="w-3.5 h-3.5" /> Detail zakázky <ChevronRight className="w-3 h-3 text-slate-400 group-hover/btn:translate-x-1 transition-transform" />
          </button>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="hidden print:block">
        <PrintTemplate order={{...formData, id: editingOrderId || 'NÁVRH', cost: calculatedCost}} company={companyInfo} vehicles={vehicles} customers={customers} hourlyRate={hourlyRate} />
      </div>
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 print:hidden">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Přehled zakázek</h2>
          <p className="text-slate-500 font-medium">Správa zakázkových listů a plánování.</p>
        </div>
        <button onClick={handleAddNew} className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg shadow-blue-200">
          <Plus className="w-5 h-5" /> Nová zakázka
        </button>
      </div>
      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3 print:hidden">
        <Search className="w-5 h-5 text-slate-400" />
        <input type="text" placeholder="Hledat zakázku (ID, SPZ, Zákazník)..." className="flex-1 text-sm font-medium outline-none bg-transparent" value={search} onChange={(e) => onSearchChange(e.target.value)} />
        {search && (
          <button 
            onClick={() => onSearchChange('')}
            className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all"
          >
            Zrušit filtr
          </button>
        )}
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8 pb-12 print:hidden min-h-[600px]">
        <div className="space-y-6">
          <h3 className="text-sm font-black text-slate-600 uppercase tracking-widest px-2">K VYŘÍZENÍ</h3>
          <div className="space-y-4">{columns.waiting.map(renderOrderCard)}</div>
        </div>
        <div className="space-y-6">
          <h3 className="text-sm font-black text-amber-700 uppercase tracking-widest px-2">PROBÍHÁ</h3>
          <div className="space-y-4">{columns.active.map(renderOrderCard)}</div>
        </div>
        <div className="space-y-6">
          <h3 className="text-sm font-black text-emerald-700 uppercase tracking-widest px-2">HOTOVO</h3>
          <div className="space-y-4">{columns.done.map(renderOrderCard)}</div>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 print:hidden">
          <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white w-full max-w-[1100px] h-[95vh] rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50 shrink-0">
              <div className="flex items-center gap-4">
                <div className="bg-blue-600 p-2 rounded-xl text-white"><FileText className="w-6 h-6" /></div>
                <h3 className="text-xl font-black tracking-tight uppercase">Editace Zakázkového Listu</h3>
              </div>
              <div className="flex gap-4">
                <button type="button" onClick={() => window.print()} className="bg-slate-100 text-slate-700 px-6 py-3 rounded-xl font-black text-sm flex items-center gap-2 hover:bg-slate-200"><Printer className="w-5 h-5" /> TISKNOUT</button>
                <button onClick={handleSubmit} className="bg-blue-600 text-white px-8 py-3 rounded-xl font-black text-sm flex items-center gap-2 shadow-lg hover:bg-blue-700"><Check className="w-5 h-5" /> ULOŽIT ZAKÁZKU</button>
                <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-slate-100 rounded-xl"><X className="w-6 h-6 text-slate-400" /></button>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto p-12 bg-slate-200/50 flex justify-center custom-scrollbar">
              <div className="bg-white shadow-2xl p-10 font-sans text-black border-[1px] border-slate-300 w-full max-w-[250mm] min-h-[297mm] h-fit">
                <PrintTemplate 
                  order={{...formData, id: editingOrderId || 'NÁVRH', cost: calculatedCost}} 
                  company={companyInfo} 
                  vehicles={vehicles} 
                  customers={customers} 
                  hourlyRate={hourlyRate}
                  isEditable={true}
                  onUpdatePart={updatePart}
                  onRemovePart={removePart}
                  onAddPart={addPart}
                  onUpdateOrder={updateOrderField}
                  onOpenPriceList={() => setIsPriceListPickerOpen(true)}
                  onOpenTemplates={() => setIsTemplatePickerOpen(true)}
                  fixedServices={fixedServices}
                  onAddFromPriceList={addFromPriceList}
                />
              </div>
            </div>
          </div>
        </div>
      )}

      {isPriceListPickerOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsPriceListPickerOpen(false)}></div>
          <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-blue-600 p-6 text-white flex justify-between items-center">
              <h3 className="text-xl font-black uppercase">Vybrat z ceníku</h3>
              <button onClick={() => setIsPriceListPickerOpen(false)} className="p-2 hover:bg-white/10 rounded-xl"><X className="w-5 h-5" /></button>
            </div>
            <div className="p-6 max-h-[60vh] overflow-y-auto custom-scrollbar space-y-2">
              {fixedServices.map(item => (
                <button key={item.id} onClick={() => addFromPriceList(item)} className="w-full text-left p-4 rounded-xl border border-slate-100 hover:bg-blue-50 transition-colors group flex justify-between items-center">
                  <span className="font-bold text-slate-700">{item.name}</span>
                  <span className="font-black text-blue-600">{item.price.toLocaleString()} Kč</span>
                </button>
              ))}
              {fixedServices.length === 0 && <p className="text-center py-10 text-slate-400 font-bold italic">Ceník je prázdný. Nastavte jej v Nastavení.</p>}
            </div>
          </div>
        </div>
      )}

      {isTemplatePickerOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsTemplatePickerOpen(false)}></div>
          <div className="bg-white w-full max-w-xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-blue-600 p-6 text-white flex justify-between items-center">
              <h3 className="text-xl font-black uppercase">Vybrat šablonu</h3>
              <button onClick={() => setIsTemplatePickerOpen(false)} className="p-2 hover:bg-white/10 rounded-xl"><X className="w-5 h-5" /></button>
            </div>
            <div className="p-6 max-h-[60vh] overflow-y-auto custom-scrollbar space-y-2">
              {predefinedTasks.map(item => (
                <button key={item.id} onClick={() => addFromTemplates(item)} className="w-full text-left p-4 rounded-xl border border-slate-100 hover:bg-blue-50 transition-all group">
                  <p className="font-black text-slate-900 group-hover:text-blue-600 mb-1 uppercase tracking-tight text-sm">{item.label}</p>
                  <p className="text-xs text-slate-500 line-clamp-2 italic">{item.description}</p>
                </button>
              ))}
              {predefinedTasks.length === 0 && <p className="text-center py-10 text-slate-400 font-bold italic">Šablony nejsou definovány. Nastavte je v Nastavení.</p>}
            </div>
          </div>
        </div>
      )}

      <style>{`
        @media print {
          @page { size: A4 portrait; margin: 0; }
          html, body { height: 100%; margin: 0 !important; padding: 0 !important; overflow: visible !important; background: white !important; }
          #root { display: none !important; }
          .print-block { display: block !important; visibility: visible !important; position: absolute !important; left: 0 !important; top: 0 !important; width: 210mm !important; min-height: 297mm !important; background: white !important; color: black !important; font-family: sans-serif !important; padding: 10mm !important; box-sizing: border-box !important; }
          .print-block * { visibility: visible !important; }
        }
      `}</style>
    </div>
  );
};

export const PrintTemplate: React.FC<{ 
  order: ServiceRecord, 
  company: CompanyInfo, 
  vehicles: Vehicle[], 
  customers: Customer[], 
  hourlyRate: number,
  isEditable?: boolean,
  onUpdatePart?: (id: string, field: keyof PartItem, value: any) => void,
  onRemovePart?: (id: string) => void,
  onAddPart?: () => void,
  onUpdateOrder?: (field: string, value: any) => void,
  onOpenPriceList?: () => void,
