}> = ({ order, company, vehicles, customers, hourlyRate, isEditable, onUpdatePart, onRemovePart, onAddPart, onUpdateOrder, onOpenPriceList, onOpenTemplates }) => {
  const vehicle = vehicles.find(v => v.id === order.vehicleId);
