          <div className="flex-1 p-4 text-[11px] leading-relaxed whitespace-pre-wrap italic font-medium underline decoration-gray-300 underline-offset-4 relative">
            {isEditable ? (
              <textarea 
                className="w-full h-full bg-transparent outline-none resize-none border-none leading-relaxed italic"
