              )}
            </div>

            <div className="p-8 border-t bg-slate-50 shrink-0">
              <button 
                onClick={() => setHistoryVehicle(null)}
                className="w-full bg-slate-900 text-white font-black py-4 rounded-2xl transition-all"
              >
                ZAVŘÍT OKNO
              </button>
            </div>
          </div>
        </div>
      )}

