      {/* AI Import Modal (Excel & PDF) */}
      {isAiImportOpen && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md" onClick={() => !aiLoading && setIsAiImportOpen(false)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[80vh]">
            <div className="bg-emerald-600 p-6 text-white flex justify-between items-center shrink-0">
               <div className="flex items-center gap-4">
                  <div className="bg-white/20 p-2 rounded-xl"><FileSearch className="w-6 h-6" /></div>
                  <div>
                    <h3 className="text-xl font-black uppercase tracking-tight">AI Import ze souboru</h3>
                    <p className="text-emerald-100 text-[10px] font-black uppercase mt-0.5">Analýza položek pomocí Gemini</p>
                  </div>
               </div>
               {!aiLoading && <button onClick={() => setIsAiImportOpen(false)} className="p-2 hover:bg-white/10 rounded-xl transition-colors"><X className="w-5 h-5" /></button>}
            </div>

            <div className="flex-1 overflow-y-auto p-8 custom-scrollbar">
              {aiLoading ? (
                <div className="flex flex-col items-center justify-center py-20 gap-4">
                  <Loader2 className="w-12 h-12 text-emerald-600 animate-spin" />
                  <div className="text-center">
                    <p className="font-black text-slate-900 uppercase">Analyzuji soubor...</p>
                    <p className="text-sm text-slate-500 font-medium italic mt-1">Gemini AI čte dokument a extrahuje položky</p>
                  </div>
                </div>
              ) : (
                <div className="space-y-6">
                  <div className="bg-blue-50 border border-blue-100 p-4 rounded-2xl flex items-start gap-3">
                    <AlertCircle className="w-5 h-5 text-blue-600 mt-0.5" />
                    <p className="text-xs text-blue-800 font-medium leading-relaxed">Vyberte položky, které chcete vložit do zakázkového listu. AI automaticky rozpoznala názvy, množství a ceny z dokumentu.</p>
                  </div>

                  <div className="border border-slate-100 rounded-2xl overflow-hidden">
                    <table className="w-full text-left">
                      <thead className="bg-slate-50 border-b border-slate-100">
                        <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                          <th className="p-4 w-12 text-center">
                             <input 
                              type="checkbox" 
                              checked={selectedAiIndices.size === aiImportItems.length}
                              onChange={() => {
                                if (selectedAiIndices.size === aiImportItems.length) setSelectedAiIndices(new Set());
                                else setSelectedAiIndices(new Set(aiImportItems.map((_, i) => i)));
                              }}
                              className="w-4 h-4 rounded border-slate-300 text-emerald-600 focus:ring-emerald-500"
                             />
                          </th>
                          <th className="p-4">Popis dílu</th>
                          <th className="p-4 text-center">Mn.</th>
                          <th className="p-4 text-right">Cena/j.</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {aiImportItems.map((item, idx) => (
                          <tr 
                            key={idx} 
                            className={`hover:bg-slate-50 transition-colors cursor-pointer ${selectedAiIndices.has(idx) ? 'bg-emerald-50/30' : ''}`}
                            onClick={() => toggleAiItem(idx)}
                          >
                            <td className="p-4 text-center">
                               <input 
                                type="checkbox" 
                                checked={selectedAiIndices.has(idx)}
                                readOnly
                                className="w-4 h-4 rounded border-slate-300 text-emerald-600 focus:ring-emerald-500"
                               />
                            </td>
                            <td className="p-4 text-sm font-bold text-slate-900">{item.description}</td>
                            <td className="p-4 text-sm font-black text-slate-900 text-center">{item.quantity}</td>
                            <td className="p-4 text-sm font-black text-blue-600 text-right">{item.unitPrice?.toLocaleString()} Kč</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>

                  {aiImportItems.length === 0 && (
                    <div className="text-center py-10 bg-slate-50 rounded-2xl border-2 border-dashed border-slate-200">
                      <p className="text-slate-400 font-bold italic">Nebyly nalezeny žádné rozpoznatelné položky dílů.</p>
                    </div>
                  )}
                </div>
              )}
            </div>

            {!aiLoading && (
              <div className="p-6 border-t border-slate-50 bg-slate-50/50 flex gap-4 shrink-0">
                <button 
                  onClick={() => setIsAiImportOpen(false)}
                  className="flex-1 py-4 bg-white border border-slate-200 text-slate-600 rounded-2xl font-black text-xs uppercase hover:bg-slate-100 transition-all"
