                  Zrušit
                </button>
                <button 
                  onClick={confirmAiImport}
                  disabled={selectedAiIndices.size === 0}
                  className="flex-[2] py-4 bg-emerald-600 text-white rounded-2xl font-black text-xs uppercase shadow-xl shadow-emerald-600/20 hover:bg-emerald-700 disabled:opacity-50 transition-all flex items-center justify-center gap-2"
                >
                  <Check className="w-5 h-5" /> VLOŽIT VYBRANÉ ({selectedAiIndices.size})
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {deletingOrder && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setDeletingOrder(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6">
                <AlertCircle className="w-10 h-10" />
              </div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-2">Opravdu smazat?</h3>
              <p className="text-slate-500 font-medium mb-8 leading-relaxed">
                Opravdu chcete smazat zakázku č. <span className="font-bold text-slate-900">{deletingOrder.id}</span>? Tato akce je nevratná.
              </p>
              <div className="flex gap-3">
                <button 
                  onClick={() => setDeletingOrder(null)}
                  className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm hover:bg-slate-200 transition-all"
                >
                  ZRUŠIT
                </button>
                <button 
                  onClick={() => { onDeleteService(deletingOrder.id); setDeletingOrder(null); }}
                  className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm hover:bg-red-700 transition-all shadow-lg shadow-red-600/20"
                >
                  SMAZAT
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ... stávající modální okna ... */}

      <style>{`
        @media print {
          @page { size: A4 portrait; margin: 0; }
          html, body { height: 100%; margin: 0 !important; padding: 0 !important; overflow: visible !important; background: white !important; }
          #root { display: none !important; }
          .print-block { display: block !important; visibility: visible !important; position: absolute !important; left: 0 !important; top: 0 !important; width: 210mm !important; min-height: 297mm !important; background: white !important; color: black !important; font-family: sans-serif !important; padding: 10mm !important; box-sizing: border-box !important; }
          .print-block * { visibility: visible !important; }
          .no-print { display: none !important; }
        }
      `}</style>
    </div>
  );
};

export const PrintTemplate: React.FC<{ 
  order: ServiceRecord, 
  company: CompanyInfo, 
  vehicles: Vehicle[], 
  customers: Customer[], 
  hourlyRate: number,
  isEditable?: boolean,
  onUpdatePart?: (id: string, field: keyof PartItem, value: any) => void,
  onRemovePart?: (id: string) => void,
  onAddPart?: () => void,
  onUpdateOrder?: (field: string, value: any) => void,
  onOpenPriceList?: () => void,
  onOpenTemplates?: () => void,
  fixedServices?: FixedService[],
  onAddFromPriceList?: (item: FixedService) => void,
  onFileUpload?: (e: React.ChangeEvent<HTMLInputElement>) => void,
  onDeleteAttachment?: (id: string) => void,
  onOpenAttachment?: (att: VehicleAttachment) => void
