             <div className="flex flex-col gap-1 overflow-y-auto max-h-[80px]">
                {order.attachments?.slice(0, 4).map(att => (
                   <div key={att.id} className="flex items-center justify-between bg-slate-50 p-1 rounded border border-slate-200 group">
                      <div className="flex items-center gap-1.5 truncate max-w-[120px]">
                         {att.type.includes('pdf') ? <FileText className="w-2.5 h-2.5 text-red-500" /> : 
