                {order.checklist?.[item.key as keyof VehicleChecklist] && <Check className="w-3 h-3 text-black stroke-[4]" />}
              </div>
            </div>
          ))}
          <div className="flex-1 min-h-[80px] border-b border-black p-2">
            {/* Blank space of the blue area */}
          </div>
        </div>
