                   <span className="text-[10px] leading-tight text-slate-700 font-bold">
                     {vehicle.make} {vehicle.model}<br />
                     <span className="font-mono text-[11px] font-black">VIN: {vehicle.vin}</span>
                   </span>
                 )}
               </div>
             ) : (
               <div className="mt-1">
                 <p className="font-bold text-[11px] leading-tight">{vehicle?.make} {vehicle?.model}</p>
                 <p className="text-[11px] font-mono font-black text-slate-800 tracking-tighter mt-0.5">VIN: {vehicle?.vin}</p>
               </div>
             )}
