                </tbody>
             </table>
          </div>
          <div className="mt-auto border-t-2 border-black flex flex-col bg-gray-50">
             <div className="flex justify-between p-1.5 border-b-2 border-black font-bold bg-gray-100">
               <span className="flex items-center gap-1"><Calculator className="w-3 h-3 opacity-50" /> SOUČET (BEZ DPH)</span>
               <span>{order.cost.toLocaleString()} Kč</span>
             </div>
             <div className="flex justify-between p-1.5 border-b border-black"><span>DPH 21%</span><span>{Math.round(order.cost * 0.21).toLocaleString()} Kč</span></div>
             <div className="flex flex-col p-3 bg-white min-h-[70px] justify-center border-b border-black">
                <span className="text-[8px] font-bold uppercase text-slate-400">Cena opravy celkem (zaokrouhleno)</span>
                <span className="text-[20px] font-black text-center mt-1">{Math.round(order.cost * 1.21).toLocaleString()} Kč</span>
             </div>
             <div className="p-1 h-20 bg-gray-100"></div>
          </div>
        </div>
      </div>

      <div className="mt-4 flex justify-between text-[7px] font-bold uppercase opacity-50">
        <span>71 00 033</span>
        <span>{new Date().toLocaleDateString('cs-CZ')}</span>
        <span>TYPOS KLATOVY 0738 C</span>
      </div>
    </div>
  );
};

export default OrderManager;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  ClipboardList, Plus, User, Car, ArrowRight, X, Check, 
  Search, Package, Printer, Trash2, Tag, FileText, AlertCircle, Eye, CheckSquare, Square, Receipt,
  MoreHorizontal, Edit3, Clock, Timer, CheckCircle2, ChevronRight, ChevronDown, ListPlus, Calculator, Layout,
  Paperclip, FilePlus, Image as ImageIcon, Loader2, Table, FileSearch
} from 'lucide-react';
import { ServiceRecord, Vehicle, Customer, PartItem, CompanyInfo, FixedService, VehicleChecklist, PredefinedTask, Invoice, VehicleAttachment } from '../types';
import * as XLSX from 'xlsx';
import { analyzeExcelParts, analyzePdfParts } from '../services/geminiService';

interface OrderManagerProps {
  services: ServiceRecord[];
  vehicles: Vehicle[];
  customers: Customer[];
  invoices: Invoice[];
  technicians: string[];
  predefinedTasks: PredefinedTask[];
  hourlyRate: number;
  fixedServices: FixedService[];
  companyInfo: CompanyInfo;
  onAddService: (service: ServiceRecord) => void;
  onUpdateService: (service: ServiceRecord) => void;
  onDeleteService: (orderId: string) => void;
  onCreateInvoice?: (orderId: string) => void;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  initialOrderId?: string | null;
  selectedPrinter?: string;
  search: string;
  onSearchChange: (value: string) => void;
}

const formatDate = (dateStr: string) => {
  if (!dateStr) return '---';
  const parts = dateStr.split('T')[0].split('-');
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}.${parts[1]}.${parts[0]}`;
};

const OrderManager: React.FC<OrderManagerProps> = ({ 
  services, 
  vehicles, 
  customers,
  invoices,
  technicians,
  predefinedTasks,
  hourlyRate,
  fixedServices,
  companyInfo,
  onAddService,
  onUpdateService,
  onDeleteService,
  onCreateInvoice,
  autoOpen, 
  onModalOpened, 
  initialOrderId,
  search,
  onSearchChange
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrderId, setEditingOrderId] = useState<string | null>(null);
  const [isPriceListPickerOpen, setIsPriceListPickerOpen] = useState(false);
  const [isTemplatePickerOpen, setIsTemplatePickerOpen] = useState(false);

  // AI Import States (Excel & PDF)
  const [isAiImportOpen, setIsAiImportOpen] = useState(false);
  const [aiLoading, setAiLoading] = useState(false);
  const [aiImportItems, setAiImportItems] = useState<Partial<PartItem>[]>([]);
  const [selectedAiIndices, setSelectedAiIndices] = useState<Set<number>>(new Set());

  const [deletingOrder, setDeletingOrder] = useState<ServiceRecord | null>(null);
  const [showInvoicePrompt, setShowInvoicePrompt] = useState<string | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    id: '',
    vehicleId: '',
    description: '',
    parts: [] as PartItem[],
    date: new Date().toISOString().split('T')[0],
    deliveryDate: '',
    endDate: '',
    technician: technicians[0] || '',
    laborHours: 0,
    status: 'naplánováno' as ServiceRecord['status'],
    fuelLevel: '50%' as ServiceRecord['fuelLevel'],
    mileageAtEntry: 0,
    estimatedPrice: 0,
    paymentType: 'Hotovost' as ServiceRecord['paymentType'],
    checklist: {
      rezerva: false, zvedak: false, klic: false, bezp_klic: false,
      trojuhelnik: false, lekarna: false, lepeni: false
    } as VehicleChecklist,
    attachments: [] as VehicleAttachment[]
  });

  const materialCost = useMemo(() => {
    return formData.parts.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
  }, [formData.parts]);

  const calculatedCost = useMemo(() => {
    return (formData.laborHours * hourlyRate) + materialCost;
  }, [formData.laborHours, materialCost, hourlyRate]);

  useEffect(() => {
    if (autoOpen) {
      handleAddNew();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen, onModalOpened]);

  useEffect(() => {
    if (initialOrderId) {
      const order = services.find(s => s.id === initialOrderId);
      if (order) {
        handleEdit(order);
        if (onModalOpened) onModalOpened();
      }
    }
  }, [initialOrderId, services, onModalOpened]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleAddNew = () => {
    resetForm();
    setEditingOrderId(null);
    setIsModalOpen(true);
  };

  const handleEdit = (order: ServiceRecord) => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    setEditingOrderId(order.id);
    setFormData({
      id: order.id,
      vehicleId: order.vehicleId,
      description: order.description,
      parts: order.parts || [],
      date: order.date,
      deliveryDate: order.deliveryDate || '',
      endDate: order.endDate || '',
      technician: order.technician,
      laborHours: order.laborHours || 0,
      status: order.status,
      fuelLevel: order.fuelLevel || '50%',
      mileageAtEntry: order.mileageAtEntry || (vehicle?.mileage || 0),
      estimatedPrice: order.estimatedPrice || 0,
      paymentType: order.paymentType || 'Hotovost',
      checklist: order.checklist || {
        rezerva: false, zvedak: false, klic: false, bezp_klic: false,
        trojuhelnik: false, lekarna: false, lepeni: false
      },
      attachments: order.attachments || []
    });
    setIsModalOpen(true);
    setOpenMenuId(null);
  };

  const generateNewId = () => {
    const now = new Date();
    const year = now.getFullYear().toString().slice(-2);
    const month = (now.getMonth() + 1).toString().padStart(2, '0');
    const prefix = `${year}/${month}/`;
    const monthlyOrders = services.filter(s => s.id.startsWith(prefix));
    const nextSequence = (monthlyOrders.length + 1).toString().padStart(3, '0');
    return `${prefix}${nextSequence}`;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalId = editingOrderId || generateNewId();
    const serviceData: ServiceRecord = {
      ...formData,
      id: finalId,
      cost: calculatedCost
    };
    if (editingOrderId) onUpdateService(serviceData);
    else onAddService(serviceData);
    setIsModalOpen(false);
    if (serviceData.status === 'hotovo') setShowInvoicePrompt(finalId);
    resetForm();
  };

  const resetForm = () => {
    setFormData({
      id: '', vehicleId: '', description: '', parts: [],
      date: new Date().toISOString().split('T')[0], deliveryDate: '', endDate: '',
      technician: technicians[0] || '', laborHours: 0, status: 'naplánováno',
      fuelLevel: '50%', mileageAtEntry: 0, estimatedPrice: 0, paymentType: 'Hotovost',
      checklist: {
        rezerva: false, zvedak: false, klic: false, bezp_klic: false,
        trojuhelnik: false, lekarna: false, lepeni: false
      },
      attachments: []
    });
  };

  const addPart = () => {
    setFormData({
      ...formData,
      parts: [...formData.parts, { id: Date.now().toString(), description: '', quantity: 1, unit: 'ks', unitPrice: 0 }]
    });
  };

  const removePart = (id: string) => {
    setFormData({ ...formData, parts: formData.parts.filter(p => p.id !== id) });
  };

  const updatePart = (id: string, field: keyof PartItem, value: any) => {
    setFormData({
      ...formData,
      parts: formData.parts.map(p => p.id === id ? { ...p, [field]: value } : p)
    });
  };

  const updateOrderField = (field: string, value: any) => {
    if (field === 'vehicleId') {
      const selectedVeh = vehicles.find(v => v.id === value);
      setFormData({
        ...formData,
        vehicleId: value,
        mileageAtEntry: selectedVeh ? selectedVeh.mileage : formData.mileageAtEntry
      });
    } else {
      setFormData({ ...formData, [field]: value });
    }
  };

  const addFromPriceList = (item: FixedService) => {
    setFormData({
      ...formData,
      parts: [...formData.parts, { id: Date.now().toString(), description: item.name, quantity: 1, unit: 'ks', unitPrice: item.price }]
    });
    setIsPriceListPickerOpen(false);
  };

  const addFromTemplates = (item: PredefinedTask) => {
    const currentDesc = formData.description;
    const separator = currentDesc.trim() ? '\n\n' : '';
    setFormData({ ...formData, description: `${currentDesc}${separator}${item.description}` });
    setIsTemplatePickerOpen(false);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    const file = files[0];
    const isExcel = file.name.endsWith('.xlsx') || file.name.endsWith('.xls');
    const isPdf = file.type === 'application/pdf';

    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64Data = reader.result as string;

      if (isExcel || isPdf) {
        setAiLoading(true);
        setIsAiImportOpen(true);
        try {
          let parts: Partial<PartItem>[] = [];
          if (isExcel) {
            const buffer = await file.arrayBuffer();
            const workbook = XLSX.read(buffer, { type: 'buffer' });
            const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
            const jsonData = XLSX.utils.sheet_to_json(firstSheet);
            parts = await analyzeExcelParts(jsonData);
          } else if (isPdf) {
            const base64Clean = base64Data.split(',')[1];
            parts = await analyzePdfParts(base64Clean);
          }

          setAiImportItems(parts);
          setSelectedAiIndices(new Set(parts.map((_, i) => i))); 
        } catch (err) {
          console.error("Analysis failed", err);
          alert("Nepodařilo se analyzovat soubor.");
        } finally {
          setAiLoading(false);
        }
      }

      const newAttachment: VehicleAttachment = {
        id: `att-${Date.now()}`,
        name: file.name,
        type: file.type || (isExcel ? 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' : 'application/octet-stream'),
        data: base64Data,
        size: file.size
      };

      setFormData(prev => ({
        ...prev,
        attachments: [...prev.attachments, newAttachment]
      }));
    };

    reader.readAsDataURL(file);
    e.target.value = '';
  };

  const confirmAiImport = () => {
    const itemsToAdd: PartItem[] = aiImportItems
      .filter((_, idx) => selectedAiIndices.has(idx))
      .map(item => ({
        id: `ai-${Math.random().toString(36).substr(2, 9)}`,
        description: item.description || 'Díl ze souboru',
        quantity: item.quantity || 1,
        unit: 'ks',
        unitPrice: item.unitPrice || 0
      }));

    setFormData(prev => ({
      ...prev,
      parts: [...prev.parts, ...itemsToAdd]
    }));
    setIsAiImportOpen(false);
    setAiImportItems([]);
  };

  const toggleAiItem = (index: number) => {
    const newIndices = new Set(selectedAiIndices);
    if (newIndices.has(index)) newIndices.delete(index);
    else newIndices.add(index);
    setSelectedAiIndices(newIndices);
  };

  const handleDeleteAttachment = (attachmentId: string) => {
    setFormData(prev => ({
      ...prev,
      attachments: prev.attachments.filter(a => a.id !== attachmentId)
    }));
  };

  const openAttachment = (attachment: VehicleAttachment) => {
    try {
      const base64Parts = attachment.data.split(',');
      const contentType = base64Parts[0].split(':')[1].split(';')[0];
      const byteCharacters = atob(base64Parts[1]);
      const byteArrays = [];

      for (let offset = 0; offset < byteCharacters.length; offset += 512) {
        const slice = byteCharacters.slice(offset, offset + 512);
        const byteNumbers = new Array(slice.length);
        for (let i = 0; i < slice.length; i++) {
          byteNumbers[i] = slice.charCodeAt(i);
        }
        const byteArray = new Uint8Array(byteNumbers);
        byteArrays.push(byteArray);
      }

      const blob = new Blob(byteArrays, { type: contentType });
      const blobUrl = URL.createObjectURL(blob);
      const newWindow = window.open(blobUrl, '_blank');
      if (!newWindow) alert('Povolte prosím vyskakovací okna.');
      setTimeout(() => URL.revokeObjectURL(blobUrl), 60000);
    } catch (error) {
      alert('Soubor se nepodařilo otevřít.');
    }
  };

  const filteredOrders = useMemo(() => {
    return services.filter(order => {
      const relatedInvoice = invoices.find(inv => inv.orderId === order.id);
      if (relatedInvoice?.status === 'uhrazeno' && (order.status === 'hotovo' || order.status === 'zrušeno')) {
        return false;
      }
      const vehicle = vehicles.find(v => v.id === order.vehicleId);
      const owner = customers.find(c => c.id === vehicle?.customerId);
      if (!search) return true;
      return (
        order.id.toLowerCase().includes(search.toLowerCase()) ||
        order.description.toLowerCase().includes(search.toLowerCase()) ||
        vehicle?.licensePlate.toLowerCase().includes(search.toLowerCase()) ||
        owner?.lastName.toLowerCase().includes(search.toLowerCase()) ||
        owner?.companyName?.toLowerCase().includes(search.toLowerCase())
      );
    });
  }, [services, vehicles, customers, invoices, search]);

  const columns = useMemo(() => ({
    waiting: filteredOrders.filter(o => o.status === 'naplánováno').sort((a, b) => a.date.localeCompare(b.date)),
    active: filteredOrders.filter(o => o.status === 'probíhá').sort((a, b) => a.date.localeCompare(b.date)),
    done: filteredOrders.filter(o => o.status === 'hotovo' || o.status === 'zrušeno').sort((a, b) => b.date.localeCompare(a.date)),
  }), [filteredOrders]);

  const renderOrderCard = (order: ServiceRecord) => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    const customer = customers.find(c => c.id === vehicle?.customerId);
    return (
      <div key={order.id} className="bg-white rounded-3xl border border-slate-100 p-6 shadow-sm hover:shadow-xl transition-all group relative animate-in fade-in zoom-in-95 duration-300">
        <div className="absolute top-0 right-0 p-4">
          <div className="relative">
            <button 
              onClick={() => setOpenMenuId(openMenuId === order.id ? null : order.id)}
              className={`p-2 rounded-xl transition-all ${openMenuId === order.id ? 'bg-slate-100 text-slate-900' : 'text-slate-300 hover:text-slate-900'}`}
            >
              <MoreHorizontal className="w-6 h-6" />
            </button>
            {openMenuId === order.id && (
