                      <div className="flex gap-1 no-print">
                        <button type="button" onClick={() => onOpenAttachment?.(att)} className="text-blue-500 hover:text-blue-700"><Eye className="w-2.5 h-2.5" /></button>
                        {isEditable && <button type="button" onClick={() => onDeleteAttachment?.(att.id)} className="text-red-400 hover:text-red-600"><X className="w-2.5 h-2.5" /></button>}
                      </div>
                   </div>
                ))}
                {(!order.attachments || order.attachments.length === 0) && (
                  <span className="text-[8px] italic text-slate-400 text-center mt-2">Žádné soubory</span>
                )}
             </div>
          </div>
        </div>
        {/* Column 2: Equipment items 2 */}
        <div className="col-span-2 border-r border-black flex flex-col">
          {labels.slice(4, 7).map((item, idx) => (
