              ) : (
                <div className="space-y-6">
                  <div className="bg-blue-50 border border-blue-100 p-4 rounded-2xl flex items-start gap-3">
                    <AlertCircle className="w-5 h-5 text-blue-600 mt-0.5" />
                    <p className="text-xs text-blue-800 font-medium leading-relaxed">Vyberte položky, které chcete vložit do zakázkového listu. AI automaticky rozpoznala názvy, množství a ceny z dokumentu.</p>
                  </div>

                  <div className="border border-slate-100 rounded-2xl overflow-hidden">
                    <table className="w-full text-left">
                      <thead className="bg-slate-50 border-b border-slate-100">
                        <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                          <th className="p-4 w-12 text-center">
                             <input 
                              type="checkbox" 
                              checked={selectedAiIndices.size === aiImportItems.length}
                              onChange={() => {
                                if (selectedAiIndices.size === aiImportItems.length) setSelectedAiIndices(new Set());
                                else setSelectedAiIndices(new Set(aiImportItems.map((_, i) => i)));
                              }}
                              className="w-4 h-4 rounded border-slate-300 text-emerald-600 focus:ring-emerald-500"
                             />
                          </th>
                          <th className="p-4">Popis dílu</th>
                          <th className="p-4 text-center">Mn.</th>
                          <th className="p-4 text-right">Cena/j.</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {aiImportItems.map((item, idx) => (
                          <tr 
                            key={idx} 
                            className={`hover:bg-slate-50 transition-colors cursor-pointer ${selectedAiIndices.has(idx) ? 'bg-emerald-50/30' : ''}`}
                            onClick={() => toggleAiItem(idx)}
                          >
                            <td className="p-4 text-center">
                               <input 
                                type="checkbox" 
                                checked={selectedAiIndices.has(idx)}
                                readOnly
                                className="w-4 h-4 rounded border-slate-300 text-emerald-600 focus:ring-emerald-500"
                               />
                            </td>
                            <td className="p-4 text-sm font-bold text-slate-900">{item.description}</td>
                            <td className="p-4 text-sm font-black text-slate-900 text-center">{item.quantity}</td>
                            <td className="p-4 text-sm font-black text-blue-600 text-right">{item.unitPrice?.toLocaleString()} Kč</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>

                  {aiImportItems.length === 0 && (
                    <div className="text-center py-10 bg-slate-50 rounded-2xl border-2 border-dashed border-slate-200">
                      <p className="text-slate-400 font-bold italic">Nebyly nalezeny žádné rozpoznatelné položky dílů.</p>
                    </div>
                  )}
                </div>
              )}
            </div>

            {!aiLoading && (
              <div className="p-6 border-t border-slate-50 bg-slate-50/50 flex gap-4 shrink-0">
                <button 
                  onClick={() => setIsAiImportOpen(false)}
                  className="flex-1 py-4 bg-white border border-slate-200 text-slate-600 rounded-2xl font-black text-xs uppercase hover:bg-slate-100 transition-all"
                >
                  Zrušit
                </button>
                <button 
                  onClick={confirmAiImport}
                  disabled={selectedAiIndices.size === 0}
                  className="flex-[2] py-4 bg-emerald-600 text-white rounded-2xl font-black text-xs uppercase shadow-xl shadow-emerald-600/20 hover:bg-emerald-700 disabled:opacity-50 transition-all flex items-center justify-center gap-2"
                >
                  <Check className="w-5 h-5" /> VLOŽIT VYBRANÉ ({selectedAiIndices.size})
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {deletingOrder && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setDeletingOrder(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6">
                <AlertCircle className="w-10 h-10" />
              </div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-2">Opravdu smazat?</h3>
              <p className="text-slate-500 font-medium mb-8 leading-relaxed">
                Opravdu chcete smazat zakázku č. <span className="font-bold text-slate-900">{deletingOrder.id}</span>? Tato akce je nevratná.
              </p>
              <div className="flex gap-3">
                <button 
                  onClick={() => setDeletingOrder(null)}
                  className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm hover:bg-slate-200 transition-all"
                >
                  ZRUŠIT
                </button>
                <button 
                  onClick={() => { onDeleteService(deletingOrder.id); setDeletingOrder(null); }}
                  className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm hover:bg-red-700 transition-all shadow-lg shadow-red-600/20"
                >
                  SMAZAT
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Invoice Prompt Modal */}
      {showInvoicePrompt && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setShowInvoicePrompt(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-10 text-center">
              <div className="w-20 h-20 bg-emerald-50 text-emerald-500 rounded-full flex items-center justify-center mx-auto mb-6">
                <Receipt className="w-10 h-10" />
              </div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-2">Zakázka dokončena</h3>
              <p className="text-slate-500 font-medium mb-8 leading-relaxed">
                Přejete si k zakázce <span className="font-bold text-slate-900">#{showInvoicePrompt}</span> okamžitě vystavit fakturu?
              </p>
              <div className="flex flex-col gap-3">
                <button 
                  onClick={() => {
                    if (onCreateInvoice) onCreateInvoice(showInvoicePrompt);
                    setShowInvoicePrompt(null);
                  }}
                  className="w-full py-4 bg-blue-600 text-white rounded-2xl font-black text-sm shadow-lg shadow-blue-600/20 hover:bg-blue-700 transition-all"
                >
                  ANO, VYSTAVIT FAKTURU
                </button>
                <button 
                  onClick={() => setShowInvoicePrompt(null)}
                  className="w-full py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm hover:bg-slate-200 transition-all"
                >
                  NE, MOŽNÁ POZDĚJI
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      <style>{`
        @media print {
          @page { size: A4 portrait; margin: 0; }
          html, body { height: 100%; margin: 0 !important; padding: 0 !important; overflow: visible !important; background: white !important; }
          #root { display: none !important; }
          .print-block { display: block !important; visibility: visible !important; position: absolute !important; left: 0 !important; top: 0 !important; width: 210mm !important; min-height: 297mm !important; background: white !important; color: black !important; font-family: sans-serif !important; padding: 10mm !important; box-sizing: border-box !important; }
          .print-block * { visibility: visible !important; }
          .no-print { display: none !important; }
        }
      `}</style>
    </div>
  );
};

