            <p className="text-sm font-black text-blue-600 font-mono tracking-widest uppercase">{vehicle?.licensePlate}</p>
            <p className="text-sm font-bold text-slate-500">VIN: {vehicle?.vin}</p>
          </div>
        </div>
      </div>

      {/* Details Grid */}
      <div className="grid grid-cols-3 gap-6 mb-12 bg-slate-50 p-6 rounded-3xl border border-slate-100">
