          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Stav tachometru</p>
          {isEditable ? (
            <input type="number" className="bg-white border p-1 rounded font-bold w-full" value={order.mileageAtEntry} onChange={e => onUpdateOrder?.('mileageAtEntry', parseInt(e.target.value))} />
          ) : (
            <p className="font-bold">{order.mileageAtEntry?.toLocaleString()} km</p>
          )}
        </div>
        <div>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Technik</p>
          {isEditable ? (
            <select className="bg-white border p-1 rounded font-bold w-full" value={order.technician} onChange={e => onUpdateOrder?.('technician', e.target.value)}>
              {technicians.map(t => <option key={t} value={t}>{t}</option>)}
            </select>
          ) : (
            <p className="font-bold">{order.technician}</p>
          )}
        </div>
      </div>

      {/* Description */}
      <div className="mb-12">
        <div className="flex justify-between items-center mb-4 border-b pb-2">
          <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest">Popis závady / požadované práce</h3>
          {isEditable && (
            <button onClick={onOpenTemplates} className="text-[10px] font-black text-blue-600 hover:underline flex items-center gap-1">
              <ListPlus className="w-3 h-3" /> POUŽÍT ŠABLONU
            </button>
          )}
        </div>
        {isEditable ? (
          <textarea 
            className="w-full bg-slate-50 p-4 rounded-2xl font-medium text-sm outline-none focus:ring-2 focus:ring-blue-500 min-h-[120px]"
            value={order.description}
            onChange={e => onUpdateOrder?.('description', e.target.value)}
          />
        ) : (
          <p className="whitespace-pre-wrap text-sm leading-relaxed text-slate-700 italic">{order.description || 'Bez popisu...'}</p>
        )}
      </div>

      {/* Parts Table */}
      <div className="mb-12">
        <div className="flex justify-between items-center mb-4 border-b pb-2">
          <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest">Rozpočet materiálu a práce</h3>
          {isEditable && (
            <div className="flex gap-4">
              <button onClick={onOpenPriceList} className="text-[10px] font-black text-emerald-600 hover:underline flex items-center gap-1">
                <Tag className="w-3 h-3" /> CENÍK
              </button>
              <button onClick={() => document.getElementById('ai-file-input')?.click()} className="text-[10px] font-black text-purple-600 hover:underline flex items-center gap-1">
                <Sparkles className="w-3 h-3" /> AI IMPORT
              </button>
              <input id="ai-file-input" type="file" className="hidden" onChange={onFileUpload} accept=".xlsx,.xls,.pdf" />
            </div>
          )}
        </div>
        <table className="w-full text-left">
          <thead>
            <tr className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
              <th className="p-4">Popis položky</th>
              <th className="p-4 text-center">Množství</th>
              <th className="p-4 text-right">Cena / MJ</th>
              <th className="p-4 text-right">Celkem</th>
              {isEditable && <th className="p-4 w-10"></th>}
            </tr>
          </thead>
          <tbody className="divide-y">
            {order.parts?.map((part: PartItem) => (
              <tr key={part.id}>
                <td className="p-4">
                  {isEditable ? (
                    <input className="w-full bg-transparent font-bold outline-none" value={part.description} onChange={e => onUpdatePart?.(part.id, 'description', e.target.value)} />
                  ) : part.description}
                </td>
                <td className="p-4 text-center">
                  {isEditable ? (
                    <input type="number" className="w-16 bg-transparent font-bold text-center outline-none" value={part.quantity} onChange={e => onUpdatePart?.(part.id, 'quantity', parseFloat(e.target.value))} />
                  ) : part.quantity}
                </td>
                <td className="p-4 text-right">
                  {isEditable ? (
                    <input type="number" className="w-24 bg-transparent font-black text-right outline-none text-blue-600" value={part.unitPrice} onChange={e => onUpdatePart?.(part.id, 'unitPrice', parseInt(e.target.value))} />
                  ) : `${part.unitPrice.toLocaleString()} Kč`}
                </td>
                <td className="p-4 text-right font-black">{(part.quantity * part.unitPrice).toLocaleString()} Kč</td>
                {isEditable && (
                  <td className="p-4 text-right">
                    <button onClick={() => onRemovePart?.(part.id)} className="text-slate-300 hover:text-red-500"><Trash2 className="w-4 h-4" /></button>
                  </td>
                )}
              </tr>
            ))}
            <tr>
              <td className="p-4 font-bold text-slate-500 italic">Servisní práce (vlastní výkon)</td>
              <td className="p-4 text-center">
                {isEditable ? (
                  <input type="number" className="w-16 bg-transparent font-bold text-center outline-none" value={order.laborHours} onChange={e => onUpdateOrder?.('laborHours', parseFloat(e.target.value))} />
                ) : `${order.laborHours} h`}
              </td>
              <td className="p-4 text-right text-slate-400">{hourlyRate.toLocaleString()} Kč/h</td>
              <td className="p-4 text-right font-black">{( (order.laborHours || 0) * hourlyRate).toLocaleString()} Kč</td>
              {isEditable && <td className="p-4"></td>}
            </tr>
          </tbody>
        </table>
        {isEditable && (
          <button onClick={onAddPart} className="mt-4 w-full py-3 border-2 border-dashed border-slate-200 rounded-2xl text-slate-400 font-black text-[10px] uppercase hover:bg-slate-50 transition-all flex items-center justify-center gap-2">
            <Plus className="w-4 h-4" /> PŘIDAT DALŠÍ POLOŽKU
          </button>
        )}
      </div>

      {/* Summary */}
      <div className="flex justify-end mb-12">
        <div className="w-80 bg-slate-900 text-white p-8 rounded-3xl shadow-2xl">
          <div className="flex justify-between items-center mb-2 opacity-50 text-[10px] font-black uppercase tracking-widest">
            <span>Celkem bez DPH</span>
            <span>{Math.round(order.cost).toLocaleString()} Kč</span>
          </div>
          <div className="flex justify-between items-center mb-6 opacity-50 text-[10px] font-black uppercase tracking-widest">
            <span>DPH (21%)</span>
            <span>{Math.round(order.cost * 0.21).toLocaleString()} Kč</span>
          </div>
          <div className="flex justify-between items-center border-t border-white/10 pt-4">
            <span className="text-[10px] font-black uppercase tracking-[0.2em]">CELKEM K ÚHRADĚ</span>
            <span className="text-2xl font-black">{Math.round(order.cost * 1.21).toLocaleString()} Kč</span>
          </div>
        </div>
      </div>

      {/* Signatures */}
      <div className="grid grid-cols-2 gap-20 pt-20">
        <div className="text-center">
          <div className="border-t-2 border-slate-900 pt-2">
            <p className="text-[10px] font-black uppercase tracking-widest">Převzal (Servis)</p>
          </div>
        </div>
        <div className="text-center">
          <div className="border-t-2 border-slate-900 pt-2">
            <p className="text-[10px] font-black uppercase tracking-widest">Předal (Zákazník)</p>
          </div>
          <p className="text-[8px] font-bold text-slate-400 mt-2 uppercase">Souhlasím se zakázkou a cenou</p>
        </div>
      </div>
    </div>
  );
};

export default OrderManager;

