                {isEditable && <button type="button" onClick={() => fileInputRef.current?.click()} className="no-print bg-blue-600 text-white p-0.5 rounded"><Plus className="w-3 h-3" /></button>}
                <input type="file" className="hidden" ref={fileInputRef} onChange={onFileUpload} accept="image/*,.pdf,.xlsx,.xls" />
             </div>
             <div className="flex flex-col gap-1 overflow-y-auto max-h-[80px]">
                {order.attachments?.slice(0, 4).map(att => (
                   <div key={att.id} className="flex items-center justify-between bg-slate-50 p-1 rounded border group">
                      <div className="flex items-center gap-1 truncate max-w-[120px]"><span className="text-[8px] truncate">{att.name}</span></div>
                      <div className="flex gap-1 no-print">
                        <button type="button" onClick={() => onOpenAttachment?.(att)} className="text-blue-500"><Eye className="w-2.5 h-2.5" /></button>
