                <tbody className="font-bold">
                   {order.parts?.map((p) => (
                     <tr key={p.id} className="border-b border-gray-100"><td className="p-1 px-2 border-r border-black">{isEditable ? <input className="w-full bg-transparent outline-none" value={p.description} onChange={(e) => onUpdatePart?.(p.id, 'description', e.target.value)} /> : p.description}</td><td className="p-1 text-center border-r border-black">{isEditable ? <input type="number" className="w-full bg-transparent outline-none text-center" value={p.quantity} onChange={(e) => onUpdatePart?.(p.id, 'quantity', parseFloat(e.target.value) || 0)} /> : p.quantity}</td><td className="p-1 text-right border-r border-black">{isEditable ? <input type="number" className="w-full bg-transparent outline-none text-right" value={p.unitPrice} onChange={(e) => onUpdatePart?.(p.id, 'unitPrice', parseFloat(e.target.value) || 0)} /> : p.unitPrice.toLocaleString()}</td><td className="p-1 text-right">{(p.quantity * p.unitPrice).toLocaleString()}</td>{isEditable && <td className="p-1 text-center print:hidden"><button onClick={() => onRemovePart?.(p.id)} className="text-red-400"><Trash2 className="w-3 h-3" /></button></td>}</tr>
