                   {isEditable && <tr><td colSpan={5} className="p-1 text-right border-t"><button onClick={() => document.getElementById('ai-parts-input')?.click()} className="text-[7px] text-purple-600 font-black px-2 flex items-center gap-1 ml-auto"><Sparkles className="w-2.5 h-2.5" /> AI IMPORT SOUBORU</button><input id="ai-parts-input" type="file" className="hidden" onChange={onFileUpload} accept=".xlsx,.xls,.pdf" /></td></tr>}
