                    <input 
                      type="number"
                      placeholder="0"
                      className="bg-slate-50 border-2 border-slate-100 rounded-xl px-4 py-2 text-xs font-black outline-none w-32 focus:border-red-400 transition-all"
                      value={selectedInvoice.costs || ''}
                      onChange={(e) => handleUpdateActiveInvoice('costs', parseFloat(e.target.value) || 0)}
                    />
