         <div className="col-span-8 border-r-2 border-black p-4 bg-slate-50/30">
            <h1 className="text-3xl font-black uppercase tracking-tighter mb-1">FAKTURA - DAŇOVÝ DOKLAD</h1>
            <p className="text-xl font-bold">Číslo faktury: <span className="font-black">{invoice.id}</span></p>
         </div>
         <div className="col-span-4 p-4 flex flex-col justify-center items-center bg-slate-100">
            <p className="text-[9px] font-black uppercase text-slate-500 mb-1">Variabilní symbol</p>
            <p className="text-2xl font-black tracking-widest">{(invoice.id || '').replace(/\D/g, '')}</p>
         </div>
      </div>

      <div className="grid grid-cols-12 border-x-2 border-b-2 border-black">
         <div className="col-span-6 border-r-2 p-6">
            <p className="text-[8px] font-black uppercase mb-4 text-slate-400 tracking-widest">DODAVATEL</p>
            <p className="text-xl font-black uppercase leading-tight mb-2">{company.name}</p>
            <p className="font-bold text-sm mb-4">{company.address}</p>
            <div className="grid grid-cols-2 gap-2 text-sm">
               <p><span className="font-black">IČO:</span> {company.ico}</p>
               <p><span className="font-black">DIČ:</span> {company.dic}</p>
               <p className="col-span-2"><span className="font-black">Tel:</span> {company.phone}</p>
               <p className="col-span-2"><span className="font-black">Email:</span> {company.email}</p>
            </div>
         </div>
         <div className="col-span-6 p-6 bg-slate-50/50">
            <p className="text-[8px] font-black uppercase mb-4 text-slate-400 tracking-widest">ODBĚRATEL</p>
            <p className="text-xl font-black uppercase leading-tight mb-2">{customer?.companyName || `${customer?.firstName} ${customer?.lastName}`}</p>
            <p className="font-bold text-sm mb-4">{customer?.address || "---"}</p>
            <div className="grid grid-cols-2 gap-2 text-sm">
               {customer?.ico && <p><span className="font-black">IČO:</span> {customer.ico}</p>}
               {customer?.dic && <p><span className="font-black">DIČ:</span> {customer.dic}</p>}
               <div className="col-span-2 mt-4 pt-4 border-t border-black/10">
                  <p className="text-[9px] font-black uppercase text-blue-600 tracking-widest mb-1">Předmět fakturace / Vozidlo</p>
                  <p className="font-black text-blue-800">{invoice.vehicleInfo || '---'}</p>
               </div>
            </div>
         </div>
      </div>

      <div className="grid grid-cols-4 border-x-2 border-b-2 border-black">
         <div className="p-4 border-r-2 border-black bg-slate-100/50">
            <p className="text-[8px] font-black uppercase text-slate-500 mb-1">Způsob úhrady</p>
            <p className="font-black text-sm uppercase">{invoice.paymentType}</p>
         </div>
         <div className="p-4 border-r-2 border-black">
            <p className="text-[8px] font-black uppercase text-slate-500 mb-1">Datum vystavení</p>
            <p className="font-black text-sm">{formatDate(invoice.issueDate)}</p>
         </div>
         <div className="p-4 border-r-2 border-black">
            <p className="text-[8px] font-black uppercase text-slate-500 mb-1">Datum uskut. zd. pln.</p>
            <p className="font-black text-sm">{formatDate(invoice.issueDate)}</p>
         </div>
         <div className="p-4 bg-red-50">
            <p className="text-[8px] font-black uppercase text-red-400 mb-1">Datum splatnosti</p>
            <p className="font-black text-sm text-red-600">{formatDate(invoice.dueDate)}</p>
         </div>
      </div>

      <div className="border-x-2 border-b-2 border-black flex-1 min-h-[450px] flex flex-col">
         <table className="w-full border-collapse">
            <thead>
               <tr className="bg-slate-100 border-b-2 border-black text-[9px] font-black uppercase tracking-widest">
                  <th className="p-3 text-left border-r-2 border-black">Popis položky / Služby</th>
                  <th className="p-3 text-center border-r-2 border-black w-24">Množství</th>
                  <th className="p-3 text-right border-r-2 border-black w-32">Cena/jedn.</th>
                  <th className="p-3 text-right w-36">Celkem (bez DPH)</th>
               </tr>
            </thead>
            <tbody className="text-sm font-bold divide-y divide-black/10">
               {items.length > 0 ? items.map((item, idx) => (
                  <tr key={idx}>
                     <td className="p-3 border-r-2 border-black">{item.description}</td>
                     <td className="p-3 text-center border-r-2 border-black font-black">{item.quantity} {item.unit}</td>
                     <td className="p-3 text-right border-r-2 border-black">{item.unitPrice.toLocaleString()} Kč</td>
                     <td className="p-3 text-right">{(item.quantity * item.unitPrice).toLocaleString()} Kč</td>
                  </tr>
               )) : (
                 <tr className="h-10">
                    <td className="p-3 border-r-2 border-black text-slate-300 italic">Nebyl zadán žádný materiál ani práce</td>
