/**
 * Specializovaná analýza pro zjištění nákupních nákladů ze souborů dodavatele.
 * Přesně podle zadání: PDF -> objednací kód + vase cena s dph, XLSX -> id položky + Nákupní cena celkem vč. DPH.
 */
export const analyzeCostsFromDocument = async (
  fileData: string | any[], 
  isPdf: boolean
): Promise<{ code: string; description: string; costWithDph: number }[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const instruction = isPdf 
    ? `Jsi expertní analytik faktur. Analyzuj tuto PDF fakturu od dodavatele autodílů.
       Pro každou jednotlivou položku (dílu) v seznamu najdi:
       1. "objednací kód" (často označen jako Obj. kód, Kód, Part Number)
       2. "popis" (název dílu)
       3. "vase cena s dph" (nákupní cena pro servis VČETNĚ DPH).
       Vrať pole JSON s těmito klíči: "code", "description", "costWithDph".
       Důležité: Extrahuj pouze skutečné díly, nikoliv souhrnné slevy nebo poplatky za dopravu, pokud nemají kód.`
    : `Jsi expertní analytik dat. Analyzuj tento seznam z Excelu.
       Pro každou položku najdi:
       1. "id položky" (unikátní kód dílu)
       2. "popis" (název dílu)
       3. "Nákupní cena celkem vč. DPH" (celková pořizovací cena za dané množství včetně DPH).
       Data k analýze: ${JSON.stringify(fileData).slice(0, 8000)}
       Vrať pole JSON s klíči: "code", "description", "costWithDph".`;

  try {
    const contents = isPdf 
      ? { parts: [{ inlineData: { mimeType: "application/pdf", data: fileData as string } }, { text: instruction }] }
      : instruction;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: contents,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              code: { type: Type.STRING, description: "Objednací kód nebo ID položky" },
              description: { type: Type.STRING, description: "Název dílu" },
              costWithDph: { type: Type.NUMBER, description: "Nákupní cena s DPH" }
            },
            required: ["code", "description", "costWithDph"]
          }
        }
      }
    });

    const result = JSON.parse(response.text || "[]");
    console.debug("AI Cost Analysis Output:", result);
    return result;
  } catch (error) {
    console.error("Gemini Cost Analysis Error:", error);
    return [];
  }
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  Search, Receipt, Printer, Trash2, CheckCircle, XCircle, AlertCircle, 
  FileText, X, Percent, CreditCard, Wallet, CalendarDays, TrendingUp, 
  AlertOctagon, MoreHorizontal, Archive, ArrowUpRight, Calculator,
  FileSearch, Loader2, FilePlus, Sparkles
} from 'lucide-react';
import { Invoice, CompanyInfo, Customer, PartItem } from '../types';
import * as XLSX from 'xlsx';
import { analyzeCostsFromDocument } from '../services/geminiService';

interface InvoiceManagerProps {
  invoices: Invoice[];
  customers: Customer[];
  companyInfo: CompanyInfo;
  discountLevels: number[];
  onDeleteInvoice: (id: string) => void;
  onUpdateInvoiceStatus: (id: string, status: 'uhrazeno' | 'neuhrazeno') => void;
  onUpdateInvoice: (invoice: Invoice) => void;
  search: string;
  onSearchChange: (value: string) => void;
}

const formatDate = (dateStr: string) => {
  if (!dateStr) return '---';
  const parts = dateStr.split('T')[0].split('-');
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}.${parts[1]}.${parts[0]}`;
};

const InvoiceManager: React.FC<InvoiceManagerProps> = ({ invoices, customers, companyInfo, discountLevels, onDeleteInvoice, onUpdateInvoiceStatus, onUpdateInvoice, search, onSearchChange }) => {
  const [selectedInvoice, setSelectedInvoice] = useState<Invoice | null>(null);
  const [deletingInvoice, setDeletingInvoice] = useState<Invoice | null>(null);
  const [isAiCostLoading, setIsAiCostLoading] = useState(false);

  const today = new Date().toISOString().split('T')[0];
  const costFileInputRef = useRef<HTMLInputElement>(null);

  const filteredInvoices = useMemo(() => {
    return invoices.filter(inv => {
      if (inv.archived) return false;
      const customer = customers.find(c => c.id === inv.customerId);
      const searchLower = search.toLowerCase();
      return (
        inv.id.toLowerCase().includes(searchLower) ||
        (customer?.lastName || '').toLowerCase().includes(searchLower) ||
        (customer?.companyName || '').toLowerCase().includes(searchLower) ||
        inv.vehicleInfo.toLowerCase().includes(searchLower)
      );
    });
  }, [invoices, customers, search]);

  const { unpaidInvoices, paidInvoices, totalUnpaid, totalPaid } = useMemo(() => {
    const unpaid = filteredInvoices.filter(inv => inv.status === 'neuhrazeno');
    const paid = filteredInvoices.filter(inv => inv.status === 'uhrazeno');

    return {
      unpaidInvoices: unpaid,
      paidInvoices: paid,
      totalUnpaid: unpaid.reduce((sum, inv) => sum + (Number(inv.totalInclDph) || 0), 0),
      totalPaid: paid.reduce((sum, inv) => sum + (Number(inv.totalInclDph) || 0), 0)
    };
  }, [filteredInvoices]);

  const handlePrint = () => {
    window.print();
  };

  const handleUpdateActiveInvoice = (field: keyof Invoice, value: any) => {
    if (!selectedInvoice) return;

    let updated = { ...selectedInvoice, [field]: value };

    if (field === 'paymentType') {
      if (value === 'Hotově') {
        updated.dueDate = updated.issueDate;
      } else {
        const date = new Date(updated.issueDate);
        date.setDate(date.getDate() + 14);
        updated.dueDate = date.toISOString().split('T')[0];
      }
    }

    if (field === 'discount' || field === 'items') {
      const currentItems = updated.items || [];
      const baseTotal = currentItems.reduce((sum, item) => sum + (Number(item.quantity) * Number(item.unitPrice)), 0);
      const discountedBase = baseTotal * (1 - ((Number(updated.discount) || 0) / 100));
      updated.totalExclDph = discountedBase;
      updated.totalInclDph = Math.round(discountedBase * 1.21);
    }

    setSelectedInvoice(updated);
    onUpdateInvoice(updated);
  };

  const handleUpdateDueDays = (days: number) => {
    if (!selectedInvoice) return;
    const date = new Date(selectedInvoice.issueDate);
    date.setDate(date.getDate() + days);
    const updated = { ...selectedInvoice, dueDate: date.toISOString().split('T')[0] };
    setSelectedInvoice(updated);
    onUpdateInvoice(updated);
  };

  const handleArchiveInvoice = (inv: Invoice) => {
    const updated = { ...inv, archived: true };
    onUpdateInvoice(updated);
  };

  const handleCostFileAnalyze = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !selectedInvoice) return;

    setIsAiCostLoading(true);
    try {
      let analysisResult: { code: string; description: string; costWithDph: number }[] = [];
      const isPdf = file.type === 'application/pdf';

      if (isPdf) {
        const reader = new FileReader();
        const base64Promise = new Promise<string>((resolve) => {
          reader.onload = () => resolve(reader.result as string);
          reader.readAsDataURL(file);
        });
        const base64Data = await base64Promise;
        analysisResult = await analyzeCostsFromDocument(base64Data.split(',')[1], true);
      } else {
        const buffer = await file.arrayBuffer();
        const workbook = XLSX.read(buffer, { type: 'buffer' });
        const jsonData = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        analysisResult = await analyzeCostsFromDocument(jsonData, false);
      }

      console.debug("Analysis matches starting for invoice items:", selectedInvoice.items);

      // Robustnější párování (fuzzy match)
      let totalMatchedCost = 0;
      let matchedItemsCount = 0;

      selectedInvoice.items.forEach(invItem => {
        const invDesc = invItem.description.toLowerCase();
        const invId = invItem.id.toLowerCase();

        // Hledáme shodu v AI výsledcích
        const match = analysisResult.find(res => {
          const resCode = (res.code || "").toLowerCase();
          const resDesc = (res.description || "").toLowerCase();

          return (
            (resCode && invId === resCode) || // Přesná shoda ID
            (resCode && invDesc.includes(resCode)) || // Kód z faktury dodavatele je v našem popisu
            (resDesc && invDesc.includes(resDesc)) || // Náš popis obsahuje název z dokumentu
            (resDesc && resDesc.includes(invDesc))    // Název z dokumentu obsahuje náš popis
          );
        });

        if (match) {
          totalMatchedCost += match.costWithDph;
          matchedItemsCount++;
          console.debug(`Matched item: ${invItem.description} -> Cost: ${match.costWithDph} (Code: ${match.code})`);
        }
      });

      if (totalMatchedCost > 0) {
        handleUpdateActiveInvoice('costs', totalMatchedCost);
        alert(`Analýza dokončena. Spárováno ${matchedItemsCount} z ${selectedInvoice.items.length} položek. Celkové náklady: ${totalMatchedCost.toLocaleString()} Kč.`);
      } else {
        alert("Nebyly nalezeny žádné odpovídající položky. Zkontrolujte, zda vaše popisy obsahují kódy dílů z dokumentu dodavatele.");
      }
    } catch (error) {
      console.error("Cost analysis failed:", error);
      alert("Analýza souboru selhala. Zkuste jiný soubor nebo zkontrolujte připojení.");
    } finally {
      setIsAiCostLoading(false);
      if (costFileInputRef.current) costFileInputRef.current.value = '';
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">

      <div className="hidden print:block">
        {selectedInvoice && <InvoicePrintTemplate invoice={selectedInvoice} company={companyInfo} customers={customers} />}
      </div>

      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 print:hidden">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Fakturační systém</h2>
          <p className="text-slate-500 font-medium">Správa vydaných faktur a sledování plateb.</p>
        </div>

        <div className="bg-white p-4 rounded-[2rem] border border-slate-200 shadow-sm flex items-center gap-8 px-8">
          <div className="flex flex-col">
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">K úhradě celkem</span>
            <span className="text-xl font-black text-blue-600">{totalUnpaid.toLocaleString()} Kč</span>
          </div>
          <div className="w-px h-10 bg-slate-100"></div>
          <div className="flex flex-col">
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Uhrazeno celkem</span>
            <span className="text-xl font-black text-emerald-600">{totalPaid.toLocaleString()} Kč</span>
          </div>
        </div>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3 print:hidden">
        <Search className="w-5 h-5 text-slate-400" />
        <input 
          type="text" 
          placeholder="Hledat fakturu (ID, Zákazník, Vozidlo)..." 
