                    <div className="space-y-3">
                       <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 flex items-center gap-2"><FolderOpen className="w-3 h-3" /> Cílová složka</label>
                       <div className="flex gap-2">
                          <div className="flex-1 bg-slate-800 rounded-xl px-4 py-3 text-xs font-bold text-slate-300 truncate">
                             {autoBackupSettings.folderName || 'Není vybrána...'}
                          </div>
                          <button onClick={handleSelectFolder} className="bg-white text-slate-900 px-4 py-3 rounded-xl font-black text-[10px] uppercase hover:bg-blue-400 transition-colors">Změnit</button>
                       </div>
                    </div>
                    <div className="space-y-3">
                       <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 flex items-center gap-2"><Clock className="w-3 h-3" /> Čas zálohování</label>
                       <div className="flex items-center gap-3">
                          <input 
                            type="number" 
                            min="0" max="23" 
                            className="w-20 bg-slate-800 rounded-xl px-4 py-3 text-sm font-black text-center outline-none border border-slate-700 focus:border-blue-500" 
                            value={autoBackupSettings.hour}
                            onChange={(e) => onAutoBackupSettingsChange({...autoBackupSettings, hour: parseInt(e.target.value) || 0})}
                          />
                          <span className="text-xs font-bold text-slate-500">hodin</span>
                       </div>
                    </div>
                  </div>

                  {!directoryHandle && autoBackupSettings.enabled && (
                    <div className="bg-amber-500/10 border border-amber-500/30 p-4 rounded-xl flex items-center gap-3">
                       <AlertCircle className="w-5 h-5 text-amber-500" />
                       <p className="text-xs font-bold text-amber-200">Pro fungování automatické zálohy je nutné po každém startu aplikace "Změnit" složku.</p>
                    </div>
                  )}
               </div>
            </div>
          </div>
        )}
      </div>

      {deletingFixedService && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setDeletingFixedService(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6">
                <AlertCircle className="w-10 h-10" />
              </div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-2">Smazat položku?</h3>
              <p className="text-slate-500 font-medium mb-8 leading-relaxed">
                Opravdu chcete smazat službu <span className="font-bold text-slate-900">{deletingFixedService.name}</span> z ceníku?
              </p>
              <div className="flex gap-3">
                <button onClick={() => setDeletingFixedService(null)} className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm">ZRUŠIT</button>
                <button onClick={() => { onFixedServicesChange(fixedServices.filter(fs => fs.id !== deletingFixedService.id)); setDeletingFixedService(null); }} className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm shadow-lg shadow-red-600/20">SMAZAT</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {deletingTemplate && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setDeletingTemplate(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6">
                <AlertCircle className="w-10 h-10" />
              </div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-2">Smazat šablonu?</h3>
              <p className="text-slate-500 font-medium mb-8 leading-relaxed">
                Opravdu chcete smazat šablonu <span className="font-bold text-slate-900">{deletingTemplate.label}</span>?
              </p>
              <div className="flex gap-3">
                <button onClick={() => setDeletingTemplate(null)} className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm">ZRUŠIT</button>
                <button onClick={() => { onPredefinedTasksChange(predefinedTasks.filter(pt => pt.id !== deletingTemplate.id)); setDeletingTemplate(null); }} className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm shadow-lg shadow-red-600/20">SMAZAT</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

