                    </div>
                    <p className="text-lg font-black text-slate-900">{inv.totalInclDph.toLocaleString()} Kč <span className="text-[10px] font-bold text-slate-400">vč. DPH</span></p>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {(previewOrder || previewInvoice) && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 print:hidden">
          <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md" onClick={() => { setPreviewOrder(null); setPreviewInvoice(null); }}></div>
          <div className="bg-white w-full max-w-5xl h-[90vh] rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden flex flex-col animate-in zoom-in-95 duration-300">
