export default ArchiveManager;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  Search, Receipt, Printer, Trash2, CheckCircle, XCircle, AlertCircle, 
  FileText, X, Percent, CreditCard, Wallet, CalendarDays, TrendingUp, 
  AlertOctagon, MoreHorizontal, Archive, ArrowUpRight, Calculator,
  FileSearch, Loader2, FilePlus, Sparkles
} from 'lucide-react';
import { Invoice, CompanyInfo, Customer, PartItem } from '../types';
import * as XLSX from 'xlsx';
import { analyzeCostsFromDocument } from '../services/geminiService';

interface InvoiceManagerProps {
  invoices: Invoice[];
  customers: Customer[];
  companyInfo: CompanyInfo;
  discountLevels: number[];
  onDeleteInvoice: (id: string) => void;
  onUpdateInvoiceStatus: (id: string, status: 'uhrazeno' | 'neuhrazeno') => void;
  onUpdateInvoice: (invoice: Invoice) => void;
  search: string;
  onSearchChange: (value: string) => void;
}

const formatDate = (dateStr: any) => {
  if (typeof dateStr !== 'string' || !dateStr) return '---';
  const datePart = dateStr.split('T')[0];
  if (!datePart) return '---';
  const parts = datePart.split('-');
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}.${parts[1]}.${parts[0]}`;
};

const InvoiceManager: React.FC<InvoiceManagerProps> = ({ invoices, customers, companyInfo, discountLevels, onDeleteInvoice, onUpdateInvoiceStatus, onUpdateInvoice, search, onSearchChange }) => {
  const [selectedInvoice, setSelectedInvoice] = useState<Invoice | null>(null);
  const [deletingInvoice, setDeletingInvoice] = useState<Invoice | null>(null);
  const [isAiCostLoading, setIsAiCostLoading] = useState(false);

  const today = new Date().toISOString().split('T')[0];
  const costFileInputRef = useRef<HTMLInputElement>(null);

  const filteredInvoices = useMemo(() => {
    return invoices.filter(inv => {
      if (inv.archived) return false;
      const customer = customers.find(c => c.id === inv.customerId);
      const searchLower = search.toLowerCase();
      return (
        (inv.id || "").toLowerCase().includes(searchLower) ||
        (customer?.lastName || '').toLowerCase().includes(searchLower) ||
        (customer?.companyName || '').toLowerCase().includes(searchLower) ||
        (inv.vehicleInfo || "").toLowerCase().includes(searchLower)
      );
    });
  }, [invoices, customers, search]);

  const { unpaidInvoices, paidInvoices, totalUnpaid, totalPaid } = useMemo(() => {
    const unpaid = filteredInvoices.filter(inv => inv.status === 'neuhrazeno');
    const paid = filteredInvoices.filter(inv => inv.status === 'uhrazeno');

    return {
      unpaidInvoices: unpaid,
      paidInvoices: paid,
      totalUnpaid: unpaid.reduce((sum, inv) => sum + (Number(inv.totalInclDph) || 0), 0),
      totalPaid: paid.reduce((sum, inv) => sum + (Number(inv.totalInclDph) || 0), 0)
    };
  }, [filteredInvoices]);

  const handlePrint = () => {
    window.print();
  };

  const handleUpdateActiveInvoice = (field: keyof Invoice, value: any) => {
    if (!selectedInvoice) return;

    let updated = { ...selectedInvoice, [field]: value };

    if (field === 'paymentType') {
      if (value === 'Hotově') {
        updated.dueDate = updated.issueDate;
      } else {
        const date = new Date(updated.issueDate);
        date.setDate(date.getDate() + 14);
        updated.dueDate = date.toISOString().split('T')[0];
      }
    }

    if (field === 'discount' || field === 'items') {
      const currentItems = updated.items || [];
      const baseTotal = currentItems.reduce((sum, item) => sum + (Number(item.quantity) * Number(item.unitPrice)), 0);
      const discountedBase = baseTotal * (1 - ((Number(updated.discount) || 0) / 100));
      updated.totalExclDph = discountedBase;
      updated.totalInclDph = Math.round(discountedBase * 1.21);
    }

    setSelectedInvoice(updated);
    onUpdateInvoice(updated);
  };

  const handleUpdateDueDays = (days: number) => {
    if (!selectedInvoice) return;
    const date = new Date(selectedInvoice.issueDate);
    date.setDate(date.getDate() + days);
    const updated = { ...selectedInvoice, dueDate: date.toISOString().split('T')[0] };
    setSelectedInvoice(updated);
    onUpdateInvoice(updated);
  };

  const handleArchiveInvoice = (inv: Invoice) => {
    const updated = { ...inv, archived: true };
    onUpdateInvoice(updated);
  };

  const handleCostFileAnalyze = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !selectedInvoice) return;

    setIsAiCostLoading(true);
    try {
      let analysisResult: { code: string; description: string; costWithDph: number }[] = [];
      const isPdf = file.type === 'application/pdf';

      if (isPdf) {
        const reader = new FileReader();
        const base64Promise = new Promise<string>((resolve) => {
          reader.onload = () => resolve(reader.result as string);
          reader.readAsDataURL(file);
        });
        const base64Data = await base64Promise;
        const splitted = base64Data.split(',');
        analysisResult = await analyzeCostsFromDocument(splitted.length > 1 ? splitted[1] : splitted[0], true);
      } else {
        const buffer = await file.arrayBuffer();
        const workbook = XLSX.read(buffer, { type: 'buffer' });
        const jsonData = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        analysisResult = await analyzeCostsFromDocument(jsonData, false);
      }

      let totalMatchedCost = 0;
      let matchedCount = 0;

      selectedInvoice.items.forEach(invItem => {
        const invDesc = (invItem.description || "").toLowerCase();
        const invId = (invItem.id || "").toLowerCase();

        const match = analysisResult.find(res => {
          const resCode = (res.code || "").toLowerCase();
          const resDesc = (res.description || "").toLowerCase();

          return (
            (resCode && invId === resCode) || 
            (resCode && invDesc.includes(resCode)) || 
            (resDesc && invDesc.includes(resDesc)) || 
            (resDesc && resDesc.includes(invDesc))    
          );
        });

        if (match) {
          totalMatchedCost += (match.costWithDph || 0);
          matchedCount++;
        }
      });

      if (totalMatchedCost > 0) {
        handleUpdateActiveInvoice('costs', totalMatchedCost);
        alert(`Analýza dokončena. Spárováno ${matchedCount} z ${selectedInvoice.items.length} položek. Celkové náklady: ${totalMatchedCost.toLocaleString()} Kč.`);
      } else {
        alert("Nebyly nalezeny žádné odpovídající položky. Ujistěte se, že vaše popisy položek obsahují objednací kódy z dokumentu dodavatele.");
      }
    } catch (error) {
      console.error("Analysis failed:", error);
      alert("Analýza souboru selhala. Zkontrolujte formát souboru.");
    } finally {
      setIsAiCostLoading(false);
      if (costFileInputRef.current) costFileInputRef.current.value = '';
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">

      <div className="hidden print:block">
        {selectedInvoice && <InvoicePrintTemplate invoice={selectedInvoice} company={companyInfo} customers={customers} />}
      </div>

      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 print:hidden">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Fakturační systém</h2>
          <p className="text-slate-500 font-medium">Správa vydaných faktur a sledování plateb.</p>
        </div>

        <div className="bg-white p-4 rounded-[2rem] border border-slate-200 shadow-sm flex items-center gap-8 px-8">
          <div className="flex flex-col">
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">K úhradě celkem</span>
            <span className="text-xl font-black text-blue-600">{totalUnpaid.toLocaleString()} Kč</span>
          </div>
          <div className="w-px h-10 bg-slate-100"></div>
          <div className="flex flex-col">
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Uhrazeno celkem</span>
            <span className="text-xl font-black text-emerald-600">{totalPaid.toLocaleString()} Kč</span>
          </div>
        </div>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3 print:hidden">
        <Search className="w-5 h-5 text-slate-400" />
        <input 
          type="text" 
          placeholder="Hledat fakturu (ID, Zákazník, Vozidlo)..." 
          className="flex-1 text-sm font-medium outline-none bg-transparent"
          value={search}
          onChange={(e) => onSearchChange(e.target.value)}
        />
        {search && (
          <button onClick={() => onSearchChange('')} className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all">Zrušit filtr</button>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-0 lg:divide-x divide-slate-200 print:hidden pb-12">

        <div className="lg:pr-8 space-y-6">
          <div className="flex items-center justify-between mb-4 px-2">
            <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
              <AlertOctagon className="w-4 h-4 text-blue-500" />
              K úhradě ({unpaidInvoices.length})
            </h3>
          </div>
          <div className="grid grid-cols-1 gap-6">
            {unpaidInvoices.map(inv => (
              <InvoiceCard 
                key={inv.id} 
                inv={inv} 
                customers={customers} 
                today={today}
                onSelect={setSelectedInvoice}
                onDelete={setDeletingInvoice}
                onUpdateStatus={onUpdateInvoiceStatus}
                onArchive={handleArchiveInvoice}
              />
            ))}
            {unpaidInvoices.length === 0 && (
              <div className="py-12 text-center bg-slate-50/50 rounded-[2rem] border-2 border-dashed border-slate-200">
                <p className="text-slate-400 font-bold italic">Žádné faktury k úhradě.</p>
              </div>
            )}
          </div>
        </div>

        <div className="lg:pl-8 space-y-6 mt-12 lg:mt-0">
          <div className="flex items-center justify-between mb-4 px-2">
            <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
              <CheckCircle className="w-4 h-4 text-emerald-500" />
              Uhrazeno ({paidInvoices.length})
            </h3>
          </div>
          <div className="grid grid-cols-1 gap-6">
            {paidInvoices.map(inv => (
              <InvoiceCard 
                key={inv.id} 
                inv={inv} 
                customers={customers} 
                today={today}
                onSelect={setSelectedInvoice}
                onDelete={setDeletingInvoice}
                onUpdateStatus={onUpdateInvoiceStatus}
                onArchive={handleArchiveInvoice}
              />
            ))}
            {paidInvoices.length === 0 && (
              <div className="py-12 text-center bg-slate-50/50 rounded-[2rem] border-2 border-dashed border-slate-200">
                <p className="text-slate-400 font-bold italic">Žádné uhrazené faktury.</p>
              </div>
            )}
          </div>
        </div>
      </div>

      {selectedInvoice && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 print:hidden">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setSelectedInvoice(null)}></div>
          <div className="bg-white w-full max-w-6xl h-[95vh] rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden flex flex-col animate-in zoom-in-95 duration-300">
            <div className="p-6 border-b flex flex-col gap-4 bg-slate-50">
              <div className="flex justify-between items-center">
                <div className="flex items-center gap-4">
                  <FileText className="w-6 h-6 text-blue-600" />
                  <h3 className="text-xl font-black uppercase">Faktura {selectedInvoice.id}</h3>
                </div>
                <div className="flex gap-4">
                  <button 
                    onClick={() => onUpdateInvoiceStatus(selectedInvoice.id, selectedInvoice.status === 'uhrazeno' ? 'neuhrazeno' : 'uhrazeno')}
                    className={`px-6 py-3 rounded-xl font-black text-xs flex items-center gap-2 ${selectedInvoice.status === 'uhrazeno' ? 'bg-amber-100 text-amber-700' : 'bg-emerald-100 text-emerald-700'}`}
                  >
                    {selectedInvoice.status === 'uhrazeno' ? <XCircle className="w-4 h-4" /> : <CheckCircle className="w-4 h-4" />}
                    {selectedInvoice.status === 'uhrazeno' ? 'OZNAČIT JAKO NEUHRAZENO' : 'OZNAČIT JAKO UHRAZENO'}
                  </button>
                  <button 
                    onClick={handlePrint}
                    className="bg-blue-600 text-white px-8 py-3 rounded-xl font-black text-xs flex items-center gap-2 shadow-lg shadow-blue-200"
                  >
                    <Printer className="w-4 h-4" /> TISK / PDF
                  </button>
                  <button onClick={() => setSelectedInvoice(null)} className="p-2 hover:bg-slate-100 rounded-xl"><X className="w-6 h-6 text-slate-400" /></button>
                </div>
              </div>

              <div className="flex flex-wrap items-center gap-6 p-4 bg-white rounded-[2rem] border border-slate-200 shadow-sm">
                <div className="flex items-center gap-3">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Úhrada:</span>
                  <div className="flex bg-slate-100 p-1 rounded-xl">
                    <button 
                      onClick={() => handleUpdateActiveInvoice('paymentType', 'Hotově')}
                      className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${selectedInvoice.paymentType === 'Hotově' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500 hover:text-slate-700'}`}
                    >
                      <Wallet className="w-3.5 h-3.5" /> Hotově
                    </button>
                    <button 
                      onClick={() => handleUpdateActiveInvoice('paymentType', 'Převodem')}
                      className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${selectedInvoice.paymentType === 'Převodem' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500 hover:text-slate-700'}`}
                    >
                      <CreditCard className="w-3.5 h-3.5" /> Převodem
                    </button>
                  </div>
                </div>

                {selectedInvoice.paymentType === 'Převodem' && (
                  <div className="flex items-center gap-3">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Splatnost:</span>
                    <div className="flex bg-slate-100 p-1 rounded-xl">
                      {[7, 14, 31].map(days => (
                        <button 
                          key={days}
                          onClick={() => handleUpdateDueDays(days)}
                          className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${
                            Math.round((new Date(selectedInvoice.dueDate).getTime() - new Date(selectedInvoice.issueDate).getTime()) / (1000 * 3600 * 24)) === days 
                            ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500 hover:text-slate-700'
                          }`}
                        >
                          {days} d
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                <div className="flex items-center gap-3">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Sleva:</span>
                  <select 
                    value={selectedInvoice.discount || 0}
                    onChange={(e) => handleUpdateActiveInvoice('discount', parseInt(e.target.value) || 0)}
                    className="bg-slate-100 border-none rounded-xl px-4 py-2 text-xs font-bold outline-none cursor-pointer hover:bg-slate-200 transition-colors"
                  >
                    {discountLevels.map(level => (
                      <option key={level} value={level}>{level}% sleva</option>
                    ))}
                  </select>
                </div>

                <div className="flex items-center gap-3 border-l border-slate-100 pl-6">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1">
                    <Calculator className="w-3 h-3" /> Pořizovací náklady:
                  </span>

                  <div className="flex items-center gap-2">
                    <div className="relative">
                      <input 
                        type="number"
                        placeholder="0"
                        className="bg-slate-50 border-2 border-slate-100 rounded-xl px-4 py-2 text-xs font-black outline-none w-28 focus:border-emerald-500 transition-all"
                        value={selectedInvoice.costs || ''}
                        onChange={(e) => handleUpdateActiveInvoice('costs', parseFloat(e.target.value) || 0)}
                      />
                      <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] font-black text-slate-300">Kč</span>
                    </div>

                    <button 
                      onClick={() => costFileInputRef.current?.click()}
                      disabled={isAiCostLoading}
                      className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                        isAiCostLoading 
                        ? 'bg-slate-100 text-slate-400' 
                        : 'bg-emerald-600 text-white hover:bg-emerald-700 shadow-lg shadow-emerald-200'
                      }`}
                    >
                      {isAiCostLoading ? <Loader2 className="w-3 h-3 animate-spin" /> : <Sparkles className="w-3 h-3" />}
                      {isAiCostLoading ? 'Analyzuji...' : 'AI SCAN NÁKLADŮ'}
                    </button>
                    <input 
                      type="file" 
                      className="hidden" 
                      ref={costFileInputRef} 
                      onChange={handleCostFileAnalyze} 
                      accept=".pdf,.xlsx,.xls"
                    />
                  </div>
                </div>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-12 bg-slate-100 flex justify-center custom-scrollbar">
               <InvoicePrintTemplate invoice={selectedInvoice} company={companyInfo} customers={customers} />
            </div>
          </div>
        </div>
      )}

      {deletingInvoice && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setDeletingInvoice(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-10 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6"><AlertCircle className="w-10 h-10" /></div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-2">Smazat fakturu?</h3>
              <p className="text-slate-500 font-medium mb-8 leading-relaxed">
                Opravdu chcete nenávratně odstranit fakturu <span className="font-bold text-slate-900">{deletingInvoice.id}</span>?
              </p>
              <div className="flex gap-3">
                <button onClick={() => setDeletingInvoice(null)} className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm uppercase">Zrušit</button>
                <button 
                  onClick={() => { onDeleteInvoice(deletingInvoice.id); setDeletingInvoice(null); }}
                  className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm uppercase shadow-lg shadow-red-600/20"
                >
                  Smazat
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { 
  Building, Bell, Save, 
  DollarSign, Loader2,
  Plus, Trash2, Database, DownloadCloud, UploadCloud, CheckCircle2, AlertCircle, Check,
  Tag, User, Layout, Percent, X, FolderOpen, Clock, ShieldCheck, ShieldAlert
} from 'lucide-react';
import { CompanyInfo, NotificationSettings, Customer, Vehicle, ServiceRecord, AutoBackupSettings, UserSettings, FixedService, PredefinedTask, PartItem, Invoice } from '../types';

interface SettingsProps {
  hourlyRate: number;
  onRateChange: (rate: number) => void;
  fixedServices: FixedService[];
  onFixedServicesChange: (services: FixedService[]) => void;
  predefinedTasks: PredefinedTask[];
  onPredefinedTasksChange: (tasks: PredefinedTask[]) => void;
  discountLevels: number[];
  onDiscountLevelsChange: (levels: number[]) => void;
  technicians: string[];
  onTechniciansChange: (techs: string[]) => void;
  companyInfo: CompanyInfo;
  onCompanyChange: (info: CompanyInfo) => void;
  notifSettings: NotificationSettings;
  onNotifSettingsChange: (settings: NotificationSettings) => void;
  customers: Customer[];
  vehicles: Vehicle[];
  services: ServiceRecord[];
  invoices: Invoice[];
  onRestoreData: (fullState: any) => void;
  autoBackupSettings: AutoBackupSettings;
  onAutoBackupSettingsChange: (settings: AutoBackupSettings) => void;
  setDirectoryHandle: (handle: FileSystemDirectoryHandle | null) => void;
  directoryHandle: FileSystemDirectoryHandle | null;
  userSettings: UserSettings;
  onUserSettingsChange: (settings: UserSettings) => void;
  selectedPrinter: string;
  onPrinterChange: (printer: string) => void;
}

const Settings: React.FC<SettingsProps> = ({ 
  hourlyRate, onRateChange, fixedServices, onFixedServicesChange,
  predefinedTasks, onPredefinedTasksChange,
  discountLevels, onDiscountLevelsChange,
  technicians, onTechniciansChange,
  companyInfo, onCompanyChange, notifSettings, onNotifSettingsChange,
  customers, vehicles, services, invoices, onRestoreData,
  autoBackupSettings, onAutoBackupSettingsChange, setDirectoryHandle, directoryHandle
}) => {
  const [activeTab, setActiveTab] = useState<'company' | 'invoicing' | 'notifications' | 'services' | 'backups' | 'team' | 'templates'>('company');
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [backupStatus, setBackupStatus] = useState<'idle' | 'processing' | 'success' | 'error'>('idle');

  const [newTechName, setNewTechName] = useState('');
  const [newDiscount, setNewDiscount] = useState<string>('');
  const [deletingFixedService, setDeletingFixedService] = useState<FixedService | null>(null);
  const [deletingTemplate, setDeletingTemplate] = useState<PredefinedTask | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSave = () => {
    setSaveStatus('saving');
    setTimeout(() => {
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 800);
  };

  const handleSelectFolder = async () => {
    try {
      // @ts-ignore
      const handle = await window.showDirectoryPicker();
      setDirectoryHandle(handle);
      onAutoBackupSettingsChange({ ...autoBackupSettings, folderName: handle.name });
    } catch (err) {
      console.error("Folder picker cancelled or failed", err);
    }
  };

  const addDiscountLevel = () => {
    const val = parseInt(newDiscount);
    if (!isNaN(val) && !discountLevels.includes(val)) {
      onDiscountLevelsChange([...discountLevels, val].sort((a, b) => a - b));
      setNewDiscount('');
    }
  };

  const removeDiscountLevel = (val: number) => {
    onDiscountLevelsChange(discountLevels.filter(d => d !== val));
  };

  const addFixedService = () => {
    onFixedServicesChange([...fixedServices, { id: `fs${Date.now()}`, name: '', price: 0, costPrice: 0 }]);
  };

  const updateFixedService = (id: string, field: keyof FixedService, value: string | number) => {
    onFixedServicesChange(fixedServices.map(fs => fs.id === id ? { ...fs, [field]: value } : fs));
  };

  const addTemplate = () => {
    onPredefinedTasksChange([...predefinedTasks, { id: `pt${Date.now()}`, label: '', description: '' }]);
  };

  const updateTemplate = (id: string, field: keyof PredefinedTask, value: string) => {
    onPredefinedTasksChange(predefinedTasks.map(pt => pt.id === id ? { ...pt, [field]: value } : pt));
  };

  const addTechnician = () => {
    if (newTechName.trim()) {
      onTechniciansChange([...technicians, newTechName.trim()]);
      setNewTechName('');
    }
  };

  const removeTechnician = (name: string) => {
    onTechniciansChange(technicians.filter(t => t !== name));
  };

  const xmlTag = (name: string, value: any) => `    <${name}>${value !== undefined && value !== null ? String(value).replace(/[<>&"']/g, (c) => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":"&apos;"}[c] || c)) : ''}</${name}>\n`;

  const generateBackupXml = () => {
    const timestamp = new Date().toISOString();
    let xml = `<?xml version="1.0" encoding="UTF-8"?>\n<AutoServiceBackup timestamp="${timestamp}" version="2.5">\n`;

    xml += `  <CompanyInfo>\n`;
    xml += xmlTag('Name', companyInfo?.name || '');
    xml += xmlTag('Address', companyInfo?.address || '');
    xml += xmlTag('ICO', companyInfo?.ico || '');
    xml += xmlTag('DIC', companyInfo?.dic || '');
    xml += xmlTag('Phone', companyInfo?.phone || '');
    xml += xmlTag('Email', companyInfo?.email || '');
    xml += xmlTag('IsVatPayer', !!companyInfo?.isVatPayer);
    xml += `  </CompanyInfo>\n`;

    xml += `  <Customers>\n`;
    customers.forEach(c => {
      xml += `    <Customer id="${c.id}">\n`;
      xml += xmlTag('FirstName', c.firstName);
      xml += xmlTag('LastName', c.lastName);
      xml += xmlTag('Email', c.email);
      xml += xmlTag('Phone', c.phone);
      xml += xmlTag('Address', c.address);
      xml += xmlTag('CreatedAt', c.createdAt);
      if (c.companyName) xml += xmlTag('CompanyName', c.companyName);
      if (c.ico) xml += xmlTag('ICO', c.ico);
      if (c.dic) xml += xmlTag('DIC', c.dic);
      xml += `    </Customer>\n`;
    });
    xml += `  </Customers>\n`;

    xml += `  <Vehicles>\n`;
    vehicles.forEach(v => {
      xml += `    <Vehicle id="${v.id}" customerId="${v.customerId}">\n`;
      xml += xmlTag('Make', v.make);
      xml += xmlTag('Model', v.model);
      xml += xmlTag('Year', v.year);
      xml += xmlTag('VIN', v.vin);
      xml += xmlTag('LicensePlate', v.licensePlate);
      xml += xmlTag('Mileage', v.mileage);
      xml += xmlTag('EngineCode', v.engineCode);
      xml += xmlTag('STKExpirationDate', v.stkExpirationDate);
      xml += xmlTag('NextServiceDate', v.nextServiceDate);
      if (v.notes) xml += xmlTag('Notes', v.notes);
      xml += `    </Vehicle>\n`;
    });
    xml += `  </Vehicles>\n`;

    xml += `  <Services>\n`;
    services.forEach(s => {
      xml += `    <ServiceRecord id="${s.id}" vehicleId="${s.vehicleId}">\n`;
      xml += xmlTag('Date', s.date);
      xml += xmlTag('Description', s.description);
      xml += xmlTag('Cost', s.cost);
      xml += xmlTag('Status', s.status);
      xml += xmlTag('Technician', s.technician);
      xml += xmlTag('LaborHours', s.laborHours);
      if (s.parts) {
        xml += `      <Parts>\n`;
        s.parts.forEach(p => {
          xml += `        <Part id="${p.id}">\n`;
          xml += xmlTag('Description', p.description);
          xml += xmlTag('Quantity', p.quantity);
          xml += xmlTag('UnitPrice', p.unitPrice);
          xml += xmlTag('CostPrice', p.costPrice || 0);
          xml += `        </Part>\n`;
        });
        xml += `      </Parts>\n`;
      }
      xml += `    </ServiceRecord>\n`;
    });
    xml += `  </Services>\n`;

    xml += `  <Invoices>\n`;
    invoices.forEach(inv => {
      xml += `    <Invoice id="${inv.id}" orderId="${inv.orderId}">\n`;
      xml += xmlTag('IssueDate', inv.issueDate);
      xml += xmlTag('DueDate', inv.dueDate);
      xml += xmlTag('CustomerId', inv.customerId);
      xml += xmlTag('VehicleInfo', inv.vehicleInfo);
      xml += xmlTag('TotalExclDph', inv.totalExclDph);
      xml += xmlTag('TotalInclDph', inv.totalInclDph);
      xml += xmlTag('Costs', inv.costs || 0);
      xml += xmlTag('Status', inv.status);
      xml += xmlTag('PaymentType', inv.paymentType);
      xml += xmlTag('Discount', inv.discount || 0);
      xml += xmlTag('Archived', !!inv.archived);

      if (inv.items && inv.items.length > 0) {
        xml += `      <Items>\n`;
        inv.items.forEach(item => {
          xml += `        <Item id="${item.id}">\n`;
          xml += xmlTag('Description', item.description);
          xml += xmlTag('Quantity', item.quantity);
          xml += xmlTag('Unit', item.unit || 'ks');
          xml += xmlTag('UnitPrice', item.unitPrice);
          xml += xmlTag('CostPrice', item.costPrice || 0);
          xml += `        </Item>\n`;
        });
        xml += `      </Items>\n`;
      }
      xml += `    </Invoice>\n`;
    });
    xml += `  </Invoices>\n`;

    xml += `  <Settings>\n`;
    xml += xmlTag('HourlyRate', hourlyRate);
    xml += `    <FixedServices>\n`;
    fixedServices.forEach(fs => {
      xml += `      <FixedService id="${fs.id}">\n`;
      xml += xmlTag('Name', fs.name);
      xml += xmlTag('Price', fs.price);
      xml += xmlTag('CostPrice', fs.costPrice || 0);
      xml += `      </FixedService>\n`;
    });
    xml += `    </FixedServices>\n`;
    xml += `    <PredefinedTasks>\n`;
    predefinedTasks.forEach(pt => {
      xml += `      <PredefinedTask id="${pt.id}">\n`;
      xml += xmlTag('Label', pt.label);
      xml += xmlTag('Description', pt.description);
      xml += `      </PredefinedTask>\n`;
    });
    xml += `    </PredefinedTasks>\n`;
    xml += `    <Technicians>\n`;
    technicians.forEach(t => xml += `      <Technician>${t}</Technician>\n`);
    xml += `    </Technicians>\n`;
    xml += `    <DiscountLevels>\n`;
    discountLevels.forEach(d => xml += `      <Level>${d}</Level>\n`);
    xml += `    </DiscountLevels>\n`;
    xml += `  </Settings>\n`;

    xml += `</AutoServiceBackup>`;
    return xml;
  };

  const handleDownloadBackup = () => {
    setBackupStatus('processing');
    try {
      const xmlData = generateBackupXml();
      const blob = new Blob([xmlData], { type: 'text/xml' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `autoservice_full_backup_${new Date().toISOString().split('T')[0]}.xml`;
      link.click();
      setBackupStatus('success');
      setTimeout(() => setBackupStatus('idle'), 3000);
    } catch (err) { setBackupStatus('error'); }
  };

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setBackupStatus('processing');
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const parser = new DOMParser();
        const xmlDoc = parser.parseFromString(content, "text/xml");

        const companyNode = xmlDoc.querySelector("CompanyInfo");
        const importedCompany: Partial<CompanyInfo> = companyNode ? {
          name: companyNode.querySelector("Name")?.textContent || '',
          address: companyNode.querySelector("Address")?.textContent || '',
          ico: companyNode.querySelector("ICO")?.textContent || '',
          dic: companyNode.querySelector("DIC")?.textContent || '',
          phone: companyNode.querySelector("Phone")?.textContent || '',
          email: companyNode.querySelector("Email")?.textContent || '',
          isVatPayer: companyNode.querySelector("IsVatPayer")?.textContent === 'true'
        } : {};

        const importedData: any = {
          companyInfo: importedCompany,
          customers: Array.from(xmlDoc.querySelectorAll("Customer")).map(node => ({
            id: node.getAttribute("id") || `c-${Math.random()}`,
            firstName: node.querySelector("FirstName")?.textContent || '',
            lastName: node.querySelector("LastName")?.textContent || '',
            email: node.querySelector("Email")?.textContent || '',
            phone: node.querySelector("Phone")?.textContent || '',
            address: node.querySelector("Address")?.textContent || '',
            createdAt: node.querySelector("CreatedAt")?.textContent || '',
            companyName: node.querySelector("CompanyName")?.textContent || undefined,
            ico: node.querySelector("ICO")?.textContent || undefined,
            dic: node.querySelector("DIC")?.textContent || undefined,
          })),
          vehicles: Array.from(xmlDoc.querySelectorAll("Vehicle")).map(node => ({
            id: node.getAttribute("id") || `v-${Math.random()}`,
            customerId: node.getAttribute("customerId") || '',
            make: node.querySelector("Make")?.textContent || '',
            model: node.querySelector("Model")?.textContent || '',
            year: parseInt(node.querySelector("Year")?.textContent || "0"),
            vin: node.querySelector("VIN")?.textContent || '',
            licensePlate: node.querySelector("LicensePlate")?.textContent || '',
            mileage: parseInt(node.querySelector("Mileage")?.textContent || "0"),
            engineCode: node.querySelector("EngineCode")?.textContent || '',
            stkExpirationDate: node.querySelector("STKExpirationDate")?.textContent || '',
            nextServiceDate: node.querySelector("NextServiceDate")?.textContent || '',
            notes: node.querySelector("Notes")?.textContent || undefined,
          })),
          services: Array.from(xmlDoc.querySelectorAll("ServiceRecord")).map(node => ({
            id: node.getAttribute("id") || `s-${Math.random()}`,
            vehicleId: node.getAttribute("vehicleId") || '',
            date: node.querySelector("Date")?.textContent || '',
            description: node.querySelector("Description")?.textContent || '',
            cost: parseFloat(node.querySelector("Cost")?.textContent || "0"),
            status: node.querySelector("Status")?.textContent || 'naplánováno',
            technician: node.querySelector("Technician")?.textContent || '',
            laborHours: parseFloat(node.querySelector("LaborHours")?.textContent || "0"),
            parts: Array.from(node.querySelectorAll("Part")).map(p => ({
              id: p.getAttribute("id") || `p-${Math.random()}`,
              description: p.querySelector("Description")?.textContent || '',
              quantity: parseFloat(p.querySelector("Quantity")?.textContent || "0"),
              unitPrice: parseFloat(p.querySelector("UnitPrice")?.textContent || "0"),
              costPrice: parseFloat(p.querySelector("CostPrice")?.textContent || "0"),
              unit: 'ks'
            }))
          })),
          invoices: Array.from(xmlDoc.querySelectorAll("Invoice")).map(node => ({
            id: node.getAttribute("id") || `i-${Math.random()}`,
            orderId: node.getAttribute("orderId") || '',
            issueDate: node.querySelector("IssueDate")?.textContent || '',
            dueDate: node.querySelector("DueDate")?.textContent || '',
            customerId: node.querySelector("CustomerId")?.textContent || '',
            vehicleInfo: node.querySelector("VehicleInfo")?.textContent || '',
            totalExclDph: parseFloat(node.querySelector("TotalExclDph")?.textContent || "0"),
            totalInclDph: parseFloat(node.querySelector("TotalInclDph")?.textContent || "0"),
            costs: parseFloat(node.querySelector("Costs")?.textContent || "0"),
            status: node.querySelector("Status")?.textContent || 'neuhrazeno',
            paymentType: node.querySelector("PaymentType")?.textContent || 'Převodem',
            discount: parseFloat(node.querySelector("Discount")?.textContent || "0"),
            archived: node.querySelector("Archived")?.textContent === 'true',
            items: Array.from(node.querySelectorAll("Item")).map(i => ({
              id: i.getAttribute("id") || `inv-p-${Math.random()}`,
              description: i.querySelector("Description")?.textContent || '',
              quantity: parseFloat(i.querySelector("Quantity")?.textContent || "1"),
              unit: i.querySelector("Unit")?.textContent || 'ks',
              unitPrice: parseFloat(i.querySelector("UnitPrice")?.textContent || "0"),
              costPrice: parseFloat(i.querySelector("CostPrice")?.textContent || "0"),
            }))
          })),
          settings: {
            hourlyRate: parseInt(xmlDoc.querySelector("HourlyRate")?.textContent || "850"),
            fixedServices: Array.from(xmlDoc.querySelectorAll("FixedService")).map(node => ({
              id: node.getAttribute("id") || `fs-${Math.random()}`,
              name: node.querySelector("Name")?.textContent || '',
              price: parseInt(node.querySelector("Price")?.textContent || "0"),
              costPrice: parseInt(node.querySelector("CostPrice")?.textContent || "0")
            })),
            predefinedTasks: Array.from(xmlDoc.querySelectorAll("PredefinedTask")).map(node => ({
              id: node.getAttribute("id") || `pt-${Math.random()}`,
              label: node.querySelector("Label")?.textContent || '',
              description: node.querySelector("Description")?.textContent || ''
            })),
            technicians: Array.from(xmlDoc.querySelectorAll("Technician")).map(node => node.textContent || ''),
            discountLevels: Array.from(xmlDoc.querySelectorAll("Level")).map(node => parseInt(node.textContent || "0")),
          }
        };

        onRestoreData(importedData);
        setBackupStatus('success');
        setTimeout(() => setBackupStatus('idle'), 4000);
      } catch (err) {
        console.error("Restore Error:", err);
        setBackupStatus('error');
      }
    };
    reader.readAsText(file);
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700 pb-12">
