                    onClick={() => { onNavigateToCustomer(selectedVehicle.customerId); setSelectedVehicle(null); }}
                  >
                    {customers.find(c => c.id === selectedVehicle.customerId)?.companyName || 
                     `${customers.find(c => c.id === selectedVehicle.customerId)?.lastName || ''} ${customers.find(c => c.id === selectedVehicle.customerId)?.firstName || ''}`}
                    <ChevronRight className="w-4 h-4" />
                  </p>
                </div>
              </div>
            </div>

            <div className="p-8 border-t border-slate-50 bg-white shrink-0">
              <button 
                onClick={() => setSelectedVehicle(null)}
                className="w-full bg-slate-900 text-white font-black py-4 rounded-2xl transition-all hover:bg-slate-800 shadow-xl shadow-slate-900/10"
              >
                ZAVŘÍT
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default VehicleManager;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  ClipboardList, Plus, User, Car, ArrowRight, X, Check, 
  Search, Package, Printer, Trash2, Tag, FileText, AlertCircle, Eye, CheckSquare, Square, Receipt,
  MoreHorizontal, Edit3, Clock, Timer, CheckCircle2, ChevronRight, ChevronDown, ListPlus, Calculator, Layout,
  Paperclip, FilePlus, Image as ImageIcon, Loader2, Table, FileSearch, Sparkles
} from 'lucide-react';
import { ServiceRecord, Vehicle, Customer, PartItem, CompanyInfo, FixedService, VehicleChecklist, PredefinedTask, Invoice, VehicleAttachment } from '../types';
import * as XLSX from 'xlsx';
import { analyzeExcelParts, analyzePdfParts } from '../services/geminiService';

interface OrderManagerProps {
  services: ServiceRecord[];
  vehicles: Vehicle[];
  customers: Customer[];
  invoices: Invoice[];
  technicians: string[];
  predefinedTasks: PredefinedTask[];
  hourlyRate: number;
  fixedServices: FixedService[];
  companyInfo: CompanyInfo;
  onAddService: (service: ServiceRecord) => void;
  onUpdateService: (service: ServiceRecord) => void;
  onDeleteService: (orderId: string) => void;
  onCreateInvoice?: (orderId: string) => void;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  initialOrderId?: string | null;
  preselectedVehicleId?: string | null;
  selectedPrinter?: string;
  search: string;
  onSearchChange: (value: string) => void;
}

const formatDate = (dateStr: any) => {
  if (typeof dateStr !== 'string' || !dateStr) return '---';
  const datePart = dateStr.split('T')[0];
  if (!datePart) return '---';
  const parts = datePart.split('-');
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}.${parts[1]}.${parts[0]}`;
};

const OrderManager: React.FC<OrderManagerProps> = ({ 
  services, 
  vehicles, 
  customers,
  invoices,
  technicians,
  predefinedTasks,
  hourlyRate,
  fixedServices,
  companyInfo,
  onAddService,
  onUpdateService,
  onDeleteService,
  onCreateInvoice,
  autoOpen, 
  onModalOpened, 
  initialOrderId,
  preselectedVehicleId,
  search,
  onSearchChange
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrderId, setEditingOrderId] = useState<string | null>(null);
  const [isPriceListPickerOpen, setIsPriceListPickerOpen] = useState(false);
  const [isTemplatePickerOpen, setIsTemplatePickerOpen] = useState(false);

  const [isAiImportOpen, setIsAiImportOpen] = useState(false);
  const [aiLoading, setAiLoading] = useState(false);
  const [aiImportItems, setAiImportItems] = useState<Partial<PartItem>[]>([]);
  const [selectedAiIndices, setSelectedAiIndices] = useState<Set<number>>(new Set());

  const [deletingOrder, setDeletingOrder] = useState<ServiceRecord | null>(null);
  const [showInvoicePrompt, setShowInvoicePrompt] = useState<string | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const [formData, setFormData] = useState({
    id: '',
    vehicleId: '',
    description: '',
    parts: [] as PartItem[],
    date: new Date().toISOString().split('T')[0],
    deliveryDate: '',
    endDate: '',
    technician: technicians[0] || '',
    laborHours: 0,
    status: 'naplánováno' as ServiceRecord['status'],
    fuelLevel: '50%' as ServiceRecord['fuelLevel'],
    mileageAtEntry: 0,
    estimatedPrice: 0,
    paymentType: 'Hotovost' as ServiceRecord['paymentType'],
    checklist: {
      rezerva: false, zvedak: false, klic: false, bezp_klic: false,
      trojuhelnik: false, lekarna: false, lepeni: false
    } as VehicleChecklist,
    attachments: [] as VehicleAttachment[]
  });

  const materialCost = useMemo(() => {
    return formData.parts.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
  }, [formData.parts]);

  const calculatedCost = useMemo(() => {
    return (formData.laborHours * hourlyRate) + materialCost;
  }, [formData.laborHours, materialCost, hourlyRate]);

  const resetForm = (vId?: string) => {
    const selectedVeh = vId ? vehicles.find(v => v.id === vId) : null;
    setFormData({
      id: '',
      vehicleId: vId || '',
      description: '',
      parts: [] as PartItem[],
      date: new Date().toISOString().split('T')[0],
      deliveryDate: '',
      endDate: '',
      technician: technicians[0] || '',
      laborHours: 0,
      status: 'naplánováno',
      fuelLevel: '50%',
      mileageAtEntry: selectedVeh ? selectedVeh.mileage : 0,
      estimatedPrice: 0,
      paymentType: 'Hotovost',
      checklist: {
        rezerva: false, zvedak: false, klic: false, bezp_klic: false,
        trojuhelnik: false, lekarna: false, lepeni: false
      },
      attachments: []
    });
  };

  const handleAddNew = (vId?: string) => {
    resetForm(vId);
    setEditingOrderId(null);
    setIsModalOpen(true);
  };

  useEffect(() => {
    if (autoOpen) {
      handleAddNew(preselectedVehicleId || undefined);
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen, preselectedVehicleId]);

  useEffect(() => {
    if (initialOrderId) {
      const order = services.find(s => s.id === initialOrderId);
      if (order) {
        handleEdit(order);
        if (onModalOpened) onModalOpened();
      }
    }
  }, [initialOrderId, services]);

  const handleEdit = (order: ServiceRecord) => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    setEditingOrderId(order.id);
    setFormData({
      id: order.id,
      vehicleId: order.vehicleId,
      description: order.description,
      parts: order.parts || [],
      date: order.date,
      deliveryDate: order.deliveryDate || '',
      endDate: order.endDate || '',
      technician: order.technician,
      laborHours: order.laborHours || 0,
      status: order.status,
      fuelLevel: order.fuelLevel || '50%',
      mileageAtEntry: order.mileageAtEntry || (vehicle?.mileage || 0),
      estimatedPrice: order.estimatedPrice || 0,
      paymentType: order.paymentType || 'Hotovost',
      checklist: order.checklist || {
        rezerva: false, zvedak: false, klic: false, bezp_klic: false,
        trojuhelnik: false, lekarna: false, lepeni: false
      },
      attachments: order.attachments || []
    });
    setIsModalOpen(true);
    setOpenMenuId(null);
  };

  const generateNewId = () => {
    const now = new Date();
    const year = now.getFullYear().toString().slice(-2);
    const month = (now.getMonth() + 1).toString().padStart(2, '0');
    const prefix = `${year}/${month}/`;
    const monthlyOrders = services.filter(s => s.id.startsWith(prefix));
    const nextSequence = (monthlyOrders.length + 1).toString().padStart(3, '0');
    return `${prefix}${nextSequence}`;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalId = editingOrderId || generateNewId();
    const serviceData: ServiceRecord = {
      ...formData,
      id: finalId,
      cost: calculatedCost
    };
    if (editingOrderId) onUpdateService(serviceData);
    else onAddService(serviceData);
    setIsModalOpen(false);

    const hasInvoice = invoices.some(inv => inv.orderId === finalId);
    if (serviceData.status === 'hotovo' && !hasInvoice) {
      setShowInvoicePrompt(finalId);
    }
    resetForm();
  };

  const addPart = () => {
    setFormData({
      ...formData,
      parts: [...formData.parts, { id: Date.now().toString(), description: '', quantity: 1, unit: 'ks', unitPrice: 0, costPrice: 0 }]
    });
  };

  const removePart = (id: string) => {
    setFormData({ ...formData, parts: formData.parts.filter(p => p.id !== id) });
  };

  const updatePart = (id: string, field: keyof PartItem, value: any) => {
    setFormData({
      ...formData,
      parts: formData.parts.map(p => p.id === id ? { ...p, [field]: value } : p)
    });
  };

  const updateOrderField = (field: string, value: any) => {
    if (field === 'vehicleId') {
      const selectedVeh = vehicles.find(v => v.id === value);
      setFormData({
        ...formData,
        vehicleId: value,
        mileageAtEntry: selectedVeh ? selectedVeh.mileage : formData.mileageAtEntry
      });
    } else {
      setFormData({ ...formData, [field]: value });
    }
  };

  const addFromPriceList = (item: FixedService) => {
    const priceExclVat = companyInfo?.isVatPayer ? (item.price / 1.21) : item.price;
    const costExclVat = companyInfo?.isVatPayer ? ((item.costPrice || 0) / 1.21) : (item.costPrice || 0);

    setFormData({
      ...formData,
      parts: [...formData.parts, { 
        id: Date.now().toString(), 
        description: item.name, 
        quantity: 1, 
        unit: 'ks', 
        unitPrice: priceExclVat,
        costPrice: costExclVat
      }]
    });
    setIsPriceListPickerOpen(false);
  };

  const addFromTemplates = (item: PredefinedTask) => {
    const currentDesc = formData.description;
    const separator = currentDesc.trim() ? '\n\n' : '';
    setFormData({ ...formData, description: `${currentDesc}${separator}${item.description}` });
    setIsTemplatePickerOpen(false);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    const file = files[0];
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64Data = reader.result as string;
      if (file.name.endsWith('.xlsx') || file.name.endsWith('.xls') || file.type === 'application/pdf') {
        setAiLoading(true);
        setIsAiImportOpen(true);
        try {
          let parts: Partial<PartItem>[] = [];
          if (file.type === 'application/pdf') {
            const splitted = base64Data.split(',');
            parts = await analyzePdfParts(splitted.length > 1 ? splitted[1] : splitted[0]);
          } else {
            const buffer = await file.arrayBuffer();
            const workbook = XLSX.read(buffer, { type: 'buffer' });
            const jsonData = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
            parts = await analyzeExcelParts(jsonData);
          }
          setAiImportItems(parts);
          setSelectedAiIndices(new Set(parts.map((_, i) => i)));
        } catch (err) { alert("Chyba při analýze."); }
        finally { setAiLoading(false); }
      }
      const newAttachment: VehicleAttachment = { id: `att-${Date.now()}`, name: file.name, type: file.type, data: base64Data, size: file.size };
      setFormData(prev => ({ ...prev, attachments: [...prev.attachments, newAttachment] }));
    };
    reader.readAsDataURL(file);
    e.target.value = '';
  };

  const filteredOrders = useMemo(() => {
    return services.filter(order => {
      const relatedInvoice = invoices.find(inv => inv.orderId === order.id);
      if (relatedInvoice?.status === 'uhrazeno' && (order.status === 'hotovo' || order.status === 'zrušeno')) return false;
      const vehicle = vehicles.find(v => v.id === order.vehicleId);
      const owner = customers.find(c => c.id === vehicle?.customerId);
      if (!search) return true;
      return (order.id || "").toLowerCase().includes(search.toLowerCase()) ||
             (order.description || "").toLowerCase().includes(search.toLowerCase()) ||
             (vehicle?.licensePlate || "").toLowerCase().includes(search.toLowerCase()) ||
             (owner?.lastName || "").toLowerCase().includes(search.toLowerCase());
    });
  }, [services, vehicles, customers, invoices, search]);

  const columns = useMemo(() => ({
    waiting: filteredOrders.filter(o => o.status === 'naplánováno').sort((a, b) => a.date.localeCompare(b.date)),
    active: filteredOrders.filter(o => o.status === 'probíhá').sort((a, b) => a.date.localeCompare(b.date)),
    done: filteredOrders.filter(o => o.status === 'hotovo' || o.status === 'zrušeno').sort((a, b) => b.date.localeCompare(a.date)),
  }), [filteredOrders]);

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="hidden print:block">
        <PrintTemplate order={{...formData, id: editingOrderId || 'NÁVRH', cost: calculatedCost}} company={companyInfo} vehicles={vehicles} customers={customers} hourlyRate={hourlyRate} technicians={technicians} />
      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 print:hidden">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Přehled zakázek</h2>
          <p className="text-slate-500 font-medium">Správa zakázkových listů a plánování.</p>
        </div>
        <button onClick={() => handleAddNew()} className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg">
          <Plus className="w-5 h-5" /> Nová zakázka
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3 print:hidden">
        <Search className="w-5 h-5 text-slate-400" />
        <input type="text" placeholder="Hledat zakázku (ID, SPZ, Zákazník)..." className="flex-1 text-sm font-medium outline-none bg-transparent" value={search} onChange={(e) => onSearchChange(e.target.value)} />
        {search && (
          <button 
            onClick={() => onSearchChange('')}
            className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all"
          >
            Zrušit filtr
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8 pb-12 print:hidden">
        <div className="space-y-6">
          <h3 className="text-sm font-black text-slate-600 uppercase tracking-widest px-2">K VYŘÍZENÍ</h3>
          <div className="space-y-4">
            {columns.waiting.map(order => (
              <OrderCard key={order.id} order={order} vehicles={vehicles} customers={customers} onEdit={handleEdit} onUpdateStatus={(s) => onUpdateService({...order, status: s})} onOpenMenu={setOpenMenuId} openMenuId={openMenuId} onCreateInvoice={onCreateInvoice} onDelete={() => setDeletingOrder(order)} />
            ))}
          </div>
        </div>
        <div className="space-y-6">
          <h3 className="text-sm font-black text-amber-700 uppercase tracking-widest px-2">PROBÍHÁ</h3>
          <div className="space-y-4">
            {columns.active.map(order => (
              <OrderCard key={order.id} order={order} vehicles={vehicles} customers={customers} onEdit={handleEdit} onUpdateStatus={(s) => onUpdateService({...order, status: s})} onOpenMenu={setOpenMenuId} openMenuId={openMenuId} onCreateInvoice={onCreateInvoice} onDelete={() => setDeletingOrder(order)} />
            ))}
          </div>
        </div>
        <div className="space-y-6">
          <h3 className="text-sm font-black text-emerald-700 uppercase tracking-widest px-2">HOTOVO</h3>
          <div className="space-y-4">
            {columns.done.map(order => (
              <OrderCard key={order.id} order={order} vehicles={vehicles} customers={customers} onEdit={handleEdit} onUpdateStatus={(s) => onUpdateService({...order, status: s})} onOpenMenu={setOpenMenuId} openMenuId={openMenuId} onCreateInvoice={onCreateInvoice} onDelete={() => setDeletingOrder(order)} />
            ))}
          </div>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 print:hidden">
          <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white w-full max-w-[1100px] h-[95vh] rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50 shrink-0">
              <div className="flex items-center gap-4">
                <div className="bg-blue-600 p-2 rounded-xl text-white"><FileText className="w-6 h-6" /></div>
                <h3 className="text-xl font-black tracking-tight uppercase">Editace Zakázkového Listu</h3>
              </div>
              <div className="flex gap-4">
                <button type="button" onClick={() => window.print()} className="bg-slate-100 text-slate-700 px-6 py-3 rounded-xl font-black text-sm flex items-center gap-2 hover:bg-slate-200"><Printer className="w-5 h-5" /> TISKNOUT</button>
                <button onClick={handleSubmit} className="bg-blue-600 text-white px-8 py-3 rounded-xl font-black text-sm flex items-center gap-2 shadow-lg hover:bg-blue-700"><Check className="w-5 h-5" /> ULOŽIT ZAKÁZKU</button>
                <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-slate-100 rounded-xl"><X className="w-6 h-6 text-slate-400" /></button>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto p-12 bg-slate-200/50 flex justify-center custom-scrollbar">
              <div className="bg-white shadow-2xl p-10 font-sans text-black border-[1px] border-slate-300 w-full max-w-[250mm] min-h-[297mm] h-fit">
                <PrintTemplate 
                  order={{...formData, id: editingOrderId || 'NÁVRH', cost: calculatedCost}} 
                  company={companyInfo} 
                  vehicles={vehicles} 
                  customers={customers} 
                  hourlyRate={hourlyRate}
                  technicians={technicians}
                  isEditable={true}
                  onUpdatePart={updatePart}
                  onRemovePart={removePart}
                  onAddPart={addPart}
                  onUpdateOrder={updateOrderField}
                  onOpenPriceList={() => setIsPriceListPickerOpen(true)}
                  onOpenTemplates={() => setIsTemplatePickerOpen(true)}
                  fixedServices={fixedServices}
                  onFileUpload={handleFileUpload}
                  onDeleteAttachment={(id) => setFormData(prev => ({ ...prev, attachments: prev.attachments.filter(a => a.id !== id) }))}
                  onOpenAttachment={(att) => {
                     const win = window.open();
                     if (win) win.document.write(`<iframe src="${att.data}" frameborder="0" style="border:0; top:0px; left:0px; bottom:0px; right:0px; width:100%; height:100%;" allowfullscreen></iframe>`);
                  }}
                />
              </div>
            </div>
          </div>
        </div>
      )}

      {isPriceListPickerOpen && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsPriceListPickerOpen(false)}></div>
          <div className="bg-white w-full max-w-xl rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-blue-600 p-6 text-white flex justify-between items-center">
              <h3 className="text-xl font-black uppercase">Vybrat z ceníku</h3>
              <button onClick={() => setIsPriceListPickerOpen(false)}><X className="w-6 h-6" /></button>
            </div>
            <div className="p-6 max-h-[60vh] overflow-y-auto custom-scrollbar space-y-2">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Ceny jsou uvedeny včetně DPH</p>
              {fixedServices.map(item => (
                <button 
                  key={item.id} 
                  onClick={() => addFromPriceList(item)}
                  className="w-full text-left p-4 bg-slate-50 hover:bg-blue-50 rounded-xl transition-all border border-slate-100 flex justify-between items-center group"
                >
                  <div className="flex-1">
                    <span className="font-bold text-slate-700 group-hover:text-blue-700 block">{item.name}</span>
                    <span className="text-[8px] font-bold text-slate-400 uppercase">Nákup: {item.costPrice?.toLocaleString() || 0} Kč vč. DPH</span>
                  </div>
                  <div className="text-right">
                    <span className="font-black text-blue-600 block">{item.price.toLocaleString()} Kč</span>
                    <span className="text-[8px] font-bold text-slate-400 uppercase tracking-tight">vč. DPH</span>
                  </div>
                </button>
              ))}
            </div>
          </div>
        </div>
      )}

      {isTemplatePickerOpen && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsTemplatePickerOpen(false)}></div>
          <div className="bg-white w-full max-w-xl rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-slate-900 p-6 text-white flex justify-between items-center">
              <h3 className="text-xl font-black uppercase">Šablony oprav</h3>
              <button onClick={() => setIsTemplatePickerOpen(false)}><X className="w-6 h-6" /></button>
            </div>
            <div className="p-6 max-h-[60vh] overflow-y-auto custom-scrollbar space-y-4">
              {predefinedTasks.map(item => (
                <button 
                  key={item.id} 
                  onClick={() => addFromTemplates(item)}
                  className="w-full text-left p-5 bg-slate-50 hover:bg-blue-50 rounded-2xl transition-all border border-slate-100 group"
                >
                  <span className="block font-black text-slate-900 text-sm mb-1 uppercase tracking-tight group-hover:text-blue-700">{item.label}</span>
                  <span className="block text-xs font-medium text-slate-500 italic leading-relaxed">{item.description}</span>
                </button>
              ))}
            </div>
          </div>
        </div>
      )}

      {isAiImportOpen && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md" onClick={() => !aiLoading && setIsAiImportOpen(false)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden flex flex-col max-h-[80vh]">
            <div className="bg-emerald-600 p-6 text-white flex justify-between items-center shrink-0">
               <div className="flex items-center gap-4">
                  <div className="bg-white/20 p-2 rounded-xl"><FileSearch className="w-6 h-6" /></div>
                  <h3 className="text-xl font-black uppercase">AI Import ze souboru</h3>
               </div>
               {!aiLoading && <button onClick={() => setIsAiImportOpen(false)} className="p-2 hover:bg-white/10 rounded-xl"><X className="w-5 h-5" /></button>}
            </div>
            <div className="flex-1 overflow-y-auto p-8 custom-scrollbar">
              {aiLoading ? (
                <div className="flex flex-col items-center justify-center py-20 gap-4">
                  <Loader2 className="w-12 h-12 text-emerald-600 animate-spin" />
                  <p className="font-black text-slate-900 uppercase">Analyzuji soubor...</p>
                </div>
              ) : (
                <div className="space-y-6">
                  <table className="w-full text-left">
                    <thead><tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b"><th className="p-2">Vybrat</th><th className="p-2">Díl</th><th className="p-2 text-right">Cena</th></tr></thead>
                    <tbody>
                      {aiImportItems.map((item, idx) => (
                        <tr key={idx} className="border-b hover:bg-slate-50 cursor-pointer" onClick={() => {
                          const n = new Set(selectedAiIndices);
                          if (n.has(idx)) n.delete(idx); else n.add(idx);
                          setSelectedAiIndices(n);
                        }}>
                          <td className="p-2"><input type="checkbox" checked={selectedAiIndices.has(idx)} readOnly /></td>
                          <td className="p-2 text-sm font-bold">{item.description}</td>
                          <td className="p-2 text-sm font-black text-blue-600 text-right">{item.unitPrice?.toLocaleString()} Kč</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  <button onClick={() => {
                     const items = aiImportItems.filter((_, i) => selectedAiIndices.has(i)).map(it => ({ 
                        id: `ai-${Math.random()}`, 
                        description: it.description || '', 
                        quantity: it.quantity || 1, 
                        unit: 'ks', 
                        unitPrice: it.unitPrice || 0,
                        costPrice: 0 
                     }));
                     setFormData(p => ({ ...p, parts: [...p.parts, ...items] }));
                     setIsAiImportOpen(false);
                  }} className="w-full py-4 bg-emerald-600 text-white rounded-2xl font-black">VLOŽIT VYBRANÉ ({selectedAiIndices.size})</button>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {deletingOrder && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setDeletingOrder(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2rem] p-8 text-center relative z-10 shadow-2xl">
             <AlertCircle className="w-16 h-16 text-red-500 mx-auto mb-4" />
             <h3 className="text-xl font-black mb-2">Opravdu smazat?</h3>
             <p className="text-slate-500 mb-8">Zakázka #{deletingOrder.id} bude trvale odstraněna.</p>
             <div className="flex gap-4">
                <button onClick={() => setDeletingOrder(null)} className="flex-1 py-4 bg-slate-100 rounded-xl font-bold">ZRUŠIT</button>
                <button onClick={() => { onDeleteService(deletingOrder.id); setDeletingOrder(null); }} className="flex-1 py-4 bg-red-600 text-white rounded-xl font-bold">SMAZAT</button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

const OrderCard: React.FC<{
  order: ServiceRecord;
  vehicles: Vehicle[];
  customers: Customer[];
  onEdit: (o: ServiceRecord) => void;
  onUpdateStatus: (s: any) => void;
  onOpenMenu: (id: string | null) => void;
  openMenuId: string | null;
  onCreateInvoice?: (id: string) => void;
  onDelete: () => void;
}> = ({ order, vehicles, customers, onEdit, onUpdateStatus, onOpenMenu, openMenuId, onCreateInvoice, onDelete }) => {
  const vehicle = vehicles.find(v => v.id === order.vehicleId);
  const customer = customers.find(c => c.id === vehicle?.customerId);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const click = (e: MouseEvent) => { if (menuRef.current && !menuRef.current.contains(e.target as Node)) onOpenMenu(null); };
    document.addEventListener('mousedown', click);
    return () => document.removeEventListener('mousedown', click);
  }, []);

  return (
    <div className="bg-white rounded-3xl border border-slate-100 p-6 shadow-sm hover:shadow-xl transition-all group relative">
       <div className="absolute top-4 right-4">
          <button onClick={(e) => { e.stopPropagation(); onOpenMenu(openMenuId === order.id ? null : order.id); }} className="p-2 hover:bg-slate-100 rounded-xl text-slate-400 hover:text-slate-900 transition-all"><MoreHorizontal className="w-6 h-6" /></button>
          {openMenuId === order.id && (
            <div ref={menuRef} className="absolute top-12 right-0 w-48 bg-white rounded-2xl shadow-2xl border p-2 z-[60]">
               <button onClick={() => { onEdit(order); onOpenMenu(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-sm font-bold"><Edit3 className="w-4 h-4" /> Upravit</button>
               {order.status === 'hotovo' && onCreateInvoice && <button onClick={() => { onCreateInvoice(order.id); onOpenMenu(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-blue-50 text-blue-600 text-sm font-bold"><Receipt className="w-4 h-4" /> Faktura</button>}
               <button onClick={() => { onDelete(); onOpenMenu(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 text-sm font-bold"><Trash2 className="w-4 h-4" /> Smazat</button>
            </div>
          )}
       </div>
       <div className="flex items-center gap-4 mb-4">
          <div className={`w-12 h-12 rounded-xl flex items-center justify-center text-white font-black ${order.status === 'hotovo' ? 'bg-emerald-50 text-emerald-600' : order.status === 'probíhá' ? 'bg-amber-500' : 'bg-blue-600'}`}><ClipboardList className="w-6 h-6" /></div>
          <div><h4 className="text-lg font-black leading-none">#{order.id}</h4><p className="text-[10px] font-bold text-slate-400 mt-1 uppercase">{formatDate(order.date)}</p></div>
       </div>
       <div className="space-y-2 border-t border-slate-50 pt-4">
          <div className="flex items-center gap-2 text-sm font-bold text-slate-700 truncate"><Car className="w-4 h-4 text-slate-300" /> {vehicle ? `${vehicle.make} ${vehicle.model}` : '---'} <span className="font-mono text-[10px] text-blue-600">{vehicle?.licensePlate}</span></div>
          <div className="flex items-center gap-2 text-sm font-bold text-slate-700 truncate"><User className="w-4 h-4 text-slate-300" /> {customer ? (customer.companyName || `${customer.lastName} ${customer.firstName}`) : '---'}</div>
       </div>
       <div className="mt-6 flex items-center justify-between bg-slate-50 p-3 rounded-2xl">
          <div className="flex flex-col"><span className="text-[8px] font-black text-slate-400 uppercase">Celkem</span><span className="text-sm font-black">{Math.round((order.cost || 0) * 1.21).toLocaleString()} Kč</span></div>
          <select value={order.status} onChange={(e) => onUpdateStatus(e.target.value)} className="text-[10px] font-black uppercase px-2 py-1 rounded-lg border outline-none bg-white">
             <option value="naplánováno">Naplánováno</option><option value="probíhá">Probíhá</option><option value="hotovo">Hotovo</option><option value="zrušeno">Zrušeno</option>
          </select>
       </div>
    </div>
  );
};

